window.SDT_LESSONS=window.SDT_LESSONS||{};window.SDT_LESSONS["L5"]={"deck":"L5","slides":[{"p":1,"title":"표지: #6 도장공사","terms":["도장공사","도료","도막","경량철골","Gypsum Board"],"pass1":[{"kind":"say","lines":["이번 강의는 #6 **도장공사**예요. 벽, 천장, 철골에 칠을 하는 공사예요.","현장 작업 순서 주문을 떠올려요. 가설, 철거, **경량철골**, 마감.","**도장공사**는 이 중 맨 끝, 마감 칸에 와요."]},{"kind":"analogy","head":"도장은 화장","scene":"화장을 하면 피부를 지키면서 예뻐 보이죠. 도장도 물체를 지키면서 보기 좋게 만들어요.","map":[["피부","벽, 천장, 철골처럼 칠을 받는 물체"],["화장품","**도료**"],["얼굴에 남은 얇은 막","**도막**"]]}],"pass2":[{"kind":"points","head":"이 범위(1~18쪽)에서 볼 것","items":["**도료**의 구성: **전색제(vehicle)** = **수지(resin)** + **용제(solvent)** + **보조제**, 그리고 **안료(pigment)**","일반 도료 7가지 (앞): **수성 페인트(water-based paint)**, **유성 페인트(oil-based paint)**, **퍼티(putty)**, **바니쉬(varnish)**","일반 도료 7가지 (뒤): **스테인(stain)**, **실러(sealer)**, **내열도료**","기능성 도료 7가지: 친환경, 내화, 방염, 방청, 다채무늬, **본타일**, 결로 방지","도장의 조건 첫 번째: 페인트 보관 및 장소"]},{"kind":"say","lines":["3강에서 **경량철골** 벽에 **석고보드(Gypsum Board)**를 붙였죠. 그 면 위에 칠하는 것이 이번 공사예요.","표지 아래 참고문헌은 네 권이에요. 인테리어 디자인 시공 실무, 실내건축재료,","실내건축실무, 다시 인테리어 도면 이해하기예요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.0,0.0,0.5,1.0],"c":[0,0.0,0.55,1],"r":0.9778,"img":"img/L5/walk/p001_22_01.jpg","say":"왼쪽 사진: 페인트 통과 붓이에요. 이번 강의의 주인공이 도료라는 뜻이에요."},{"b":[0.515,0.33,0.3,0.26],"c":[0.5,0.314,0.33,0.292],"r":2.0091,"img":"img/L5/walk/p001_22_02.jpg","say":"제목: 2026-2 실내디자인 시공과 실무, #6 도장공사."},{"b":[0.735,0.865,0.26,0.115],"c":[0.714,0.849,0.286,0.147],"r":3.4588,"img":"img/L5/walk/p001_22_03.jpg","say":"참고문헌 네 권. 앞 강의들과 같은 책들이에요."}]}},{"p":2,"title":"도장공사의 정의와 도료의 구성","terms":["도장공사","도료","도막","피도물","vehicle","pigment","resin","solvent","보조제","은폐력","소포제"],"pass1":[{"kind":"say","lines":["**도장공사**는 물체 겉에 **도료**를 발라 얇은 막을 만드는 공사예요.","**도료**가 마르면 생기는 얇은 껍질을 **도막**이라고 불러요.","목적은 두 가지예요. 물체를 지키고, 보기 좋게 만들어요."]},{"kind":"analogy","head":"전색제는 안료를 태운 버스","scene":"**도료**는 손님과 버스로 되어 있어요. 색을 내는 손님이 **안료(pigment)**, 손님을 태우고 다니는 액체 버스가 **전색제(vehicle)**예요.","map":[["손님","**안료(pigment)**: 색과 밑바탕을 가리는 힘"],["버스","**전색제(vehicle)**: 안료를 싣고 다니는 액체"],["버스의 부품","**수지(resin)**, **용제(solvent)**, **보조제**"]]}],"pass2":[{"kind":"points","head":"**도장공사**의 정의와 목적 (슬라이드 그대로)","items":["물체의 표면에 도장재료를 사용해서 **도막** 또는 도막층을 형성하는 작업을 통틀어 불러요.","목적: **피도물**(칠을 받는 물체)에 도막을 입혀 보호하고 미적 효과를 줘서 재료 가치를 높여요.","보호 쪽: 내습, 내식, 내약품성을 유지해 마감재 표면을 지켜요.","보기 좋게 쪽: 색채, 광택, 평활성(매끈함)을 도모해요.","도장은 물품의 최종 마감이에요. 공사 순서의 맨 끝에 와요."]},{"kind":"points","head":"6.1 도장 재료","items":["도장재료는 **안료(pigment)**를 포함하는 액상 또는 분말 형태의 물질이에요.","표면에 바르면 물리적 또는 화학적으로 변해서 고체가 돼요.","**도료**가 건조되면 표면에 피막이 생기는데, 이것이 **도막**이에요.","성분: **수지(resin)**, **안료(pigment)**, 소량의 **보조제**, 유동 상태를 유지하는 **용제(solvent)**. 이 중 수지, 용제, 보조제를 통틀어 **전색제(vehicle)**라고 해요."]},{"kind":"compare","head":"[도료의 구성] 나무 그림과 오른쪽 상자","cols":["성분","하는 일"],"rows":[["**전색제(vehicle)**","안료를 분산시키고 도막 형성에 관여하는 액상 성분 (= 수지 + 용제 + 보조제)"],["**안료(pigment)**","도막에 색채와 **은폐력**(밑바탕을 가리는 힘)을 부여"],["**수지(resin)**","천연수지(소나무 진액 등)와 합성수지(에폭시 레진, 아크릴 레진 등). 도막 형성"],["**용제(solvent)**","도막의 주 요소를 용해 및 희석. 점도와 건조 속도 조절. 평활한 도막 형성"],["**보조제**","소량 첨가해 최대 효과. 색분리방지재, 건조제, **소포제**(기포 방지) 등"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**전색제(vehicle)**를 이루는 성분이 아닌 것은?","choices":["**수지(resin)**","**용제(solvent)**","**보조제**","**안료(pigment)**"],"a":3,"why":"수지와 용제, 보조제를 통틀어 전색제라고 해요. **안료(pigment)**는 전색제와 나란히 놓이는 따로 된 성분이에요."},{"kind":"check","q":"도료가 건조되어 물체 표면에 형성되는 피막을 무엇이라 하는가?","choices":["**도막**","**피도물**","**은폐력**","**용제(solvent)**"],"a":0,"why":"피막이 곧 **도막**이에요. **피도물**은 칠을 받는 물체예요."},{"kind":"english","head":"서술 답안: 도장의 목적","en":"도장의 목적은 피도물에 도막을 입혀 물체를 보호(내습, 내식, 내약품성)하고 미적 효과(색채, 광택, 평활성)를 부여하여 재료의 가치를 향상시키는 데 있다.","ko":"보호 셋, 미적 효과 셋, 결론 하나로 나눠 적으면 빠짐이 없어요.","tip":"지키고(습, 식, 약), 꾸미고(색, 광, 평), 가치 올리기."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**안료(pigment)**는 전색제에 들어가지 않아요. 전색제 = 수지 + 용제 + 보조제.","이 쪽의 보조제 예(색분리방지재, 건조제, 소포제)와 다음 쪽 6.1.5 의 예가 달라요. 둘을 합쳐 외워요.","**도막**(막)과 **피도물**(칠 받는 물체)을 바꿔 쓰지 마세요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.0968,0.0551],"c":[0,0.0208,0.2,0.0871],"r":4.0822,"img":"img/L5/walk/p002_h.jpg"},"parts":[{"b":[0.02,0.1,0.76,0.17],"c":[0,0.084,0.836,0.202],"r":7.3575,"img":"img/L5/walk/p002_23_01.jpg","say":"6. 도장공사 네 줄: 정의, 목적, 보호(내습, 내식, 내약품성)와 미(색채, 광택, 평활성), 최종 마감."},{"b":[0.02,0.3,0.82,0.18],"c":[0,0.284,0.902,0.212],"r":7.5639,"img":"img/L5/walk/p002_23_02.jpg","say":"6.1 도장 재료 세 줄: 액상 또는 분말, 도막의 뜻, 수지와 용제와 보조제를 통틀어 전색제."},{"b":[0.03,0.51,0.42,0.4],"c":[0.009,0.49,0.462,0.44],"r":1.8667,"img":"img/L5/walk/p002_23_03.jpg","say":"나무 그림: 도료 아래 전색제와 안료, 전색제 아래 수지, 용제, 보조제."},{"b":[0.485,0.5,0.31,0.1],"c":[0.4695,0.484,0.341,0.132],"r":4.5926,"img":"img/L5/walk/p002_23_04.jpg","say":"위 상자: 전색제와 안료가 하는 일."},{"b":[0.485,0.615,0.4,0.36],"c":[0.465,0.597,0.44,0.396],"r":1.9753,"img":"img/L5/walk/p002_23_05.jpg","say":"아래 상자: 수지, 용제, 보조제가 하는 일과 예."}]}},{"p":3,"title":"도료의 다섯 성분: 전색제, 안료, 수지, 용제, 보조제","terms":["vehicle","pigment","resin","solvent","보조제","은폐력","방청안료","antifouling","소포제","도막"],"pass1":[{"kind":"say","lines":["앞 쪽 나무 그림의 다섯 칸을 하나씩 자세히 보는 쪽이에요.","**전색제(vehicle)**는 버스, **안료(pigment)**는 색을 내는 손님이었죠.","**수지(resin)**는 막의 몸통, **용제(solvent)**는 묽게 했다가 날아가 버리는 것이에요."]},{"kind":"compare","head":"다섯 성분 한 줄 별명","cols":["성분","별명"],"rows":[["**전색제(vehicle)**","안료를 태우는 버스"],["**안료(pigment)**","색을 내는 손님"],["**수지(resin)**","**도막**의 몸통"],["**용제(solvent)**","묽혔다가 날아가는 것"],["**보조제**","조금 넣는 양념"]]}],"pass2":[{"kind":"points","head":"6.1.1 **전색제(vehicle)**","items":["안료를 분산, 운반하고 도막을 형성하도록 하는 도료의 액상 성분이에요.","주로 **수지(resin)**와 **용제(solvent)**로 구성돼요.","도료의 작업성, 부착성, **도막** 형성에 관여해요.","vehicle 은 탈것이라는 뜻이에요. 안료를 싣고 다니는 버스라는 별명이 여기서 나와요."]},{"kind":"points","head":"6.1.2 **안료(pigment)**","items":["도료에 색상과 **은폐력**을 줘요. 은폐력은 밑바탕을 가려 안 보이게 하는 힘이에요.","내광성, 내후성 같은 도막 성능에도 영향을 줘요. 사용 환경과 요구 성능에 맞게 골라요.","내광성: 빛, 특히 자외선에 노출되어도 색이나 성질이 쉽게 변하지 않는 성질.","내후성: 햇빛, 비, 온도, 습도 같은 바깥 기후 변화에 견디는 성질."]},{"kind":"compare","head":"색 말고 다른 일을 하는 안료 두 가지","cols":["안료","하는 일"],"rows":[["**방청안료**","금속의 부식(녹)을 억제"],["**방오안료(antifouling)**","선박, 해양구조물에 따개비, 조류 같은 해양생물이 붙는 것을 억제 (방오 = 防汚)"]]},{"kind":"points","head":"6.1.3 **수지(resin)**, 6.1.4 **용제(solvent)**","items":["수지는 도료의 물성을 좌우하는 성분이에요. 도막 성능의 대부분을 결정해요.","수지 종류에 따라 도막의 경도, 접착성, 내수성, 내후성, 내약품성이 달라져요.","용제는 칠하기 알맞은 점성과 농도를 유지하려고 써요. 도장 방법과 환경에 따라 양을 조절해요.","용제는 칠한 뒤 휘발돼서 도막에 남지 않아요. 그래도 도막 성능에는 영향을 줘요."]},{"kind":"points","head":"6.1.5 **보조제** (첨가제)","items":["앞의 성분 말고 도료의 물성을 높이려고 쓰는 재료예요. 첨가제라고 해요.","종류: **소포제**, 건조제, 산화방지제, 분산제, 침전 방지제 등.","**소포제**: 도료 속이나 도막 표면의 기포를 없애 핀홀, 기포 자국 같은 결함을 줄여요.","분산제: 안료 같은 입자가 서로 뭉치지 않고 도료 속에 고르게 퍼지게 해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"도료가 도장된 뒤 휘발되어 도막 성분으로 남지 않는 것은?","choices":["**수지(resin)**","**안료(pigment)**","**용제(solvent)**","**방청안료**"],"a":2,"why":"**용제(solvent)**는 칠한 뒤 휘발돼요. 다만 도막 성능에는 영향을 미쳐요."},{"kind":"check","q":"선박 밑면에 따개비 같은 해양생물이 부착되는 것을 억제하는 안료는?","choices":["**방청안료**","**방오안료(antifouling)**","**소포제**","분산제"],"a":1,"why":"방오는 오염을 막는다는 뜻이에요. 녹을 막는 것은 **방청안료**예요."},{"kind":"exam","src":"기출 모양 연습문제","q":"도료의 성분 중 도료의 물성을 좌우하며 도막 성능의 대부분을 결정하는 성분을 쓰시오.","qko":"도막이 얼마나 단단하고 잘 붙는지 정하는 핵심 성분 이름을 묻는 문제예요.","solve":["슬라이드 6.1.3: 수지는 도료의 물성을 좌우하는 성분으로 도막 성능의 대부분을 결정해요.","수지 종류에 따라 경도, 접착성, 내수성, 내후성, 내약품성이 달라져요.","**안료(pigment)**는 색과 은폐력, **용제(solvent)**는 점도 조절이라 답이 아니에요."],"answer":"수지(resin)"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["방청(녹)과 방오(오염, 해양생물 부착)를 바꿔 쓰지 마세요.","용제는 도막에 남지 않지만 도막 성능에 영향은 미쳐요. '영향이 없다' 는 틀려요.","보조제 예가 p2(색분리방지재, 건조제, 소포제)와 p3(소포제, 건조제, 산화방지제, 분산제, 침전 방지제)에서 달라요. 모두 알아 둬요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1091,0.1012],"c":[0,0.0208,0.2,0.1332],"r":2.6693,"img":"img/L5/walk/p003_h.jpg"},"parts":[{"b":[0.02,0.14,0.42,0.13],"c":[0,0.124,0.462,0.162],"r":5.07,"img":"img/L5/walk/p003_25_01.jpg","say":"6.1.1 전색제: 안료를 분산, 운반, 도막 형성. 주로 수지와 용제."},{"b":[0.02,0.29,0.72,0.17],"c":[0,0.274,0.792,0.202],"r":6.9703,"img":"img/L5/walk/p003_25_02.jpg","say":"6.1.2 안료: 색상과 은폐력. 방청안료와 방오안료도 여기 있어요."},{"b":[0.25,0.29,0.29,0.055],"c":[0.2355,0.2625,0.319,0.11],"r":5.1556,"img":"img/L5/walk/p003_25_03.jpg","say":"보라색 메모: 내광성(자외선에 안 변함)과 내후성(기후에 견딤)의 뜻."},{"b":[0.02,0.48,0.47,0.125],"c":[0,0.464,0.517,0.157],"r":5.8542,"img":"img/L5/walk/p003_25_04.jpg","say":"6.1.3 수지: 도막 성능의 대부분을 결정해요."},{"b":[0.02,0.62,0.7,0.13],"c":[0,0.604,0.77,0.162],"r":8.4499,"img":"img/L5/walk/p003_25_05.jpg","say":"6.1.4 용제: 점성과 농도 유지, 칠한 뒤 휘발해서 도막에 안 남아요."},{"b":[0.02,0.775,0.65,0.18],"c":[0,0.759,0.715,0.212],"r":5.9958,"img":"img/L5/walk/p003_25_06.jpg","say":"6.1.5 보조제: 첨가제. 아래 보라색 메모가 소포제와 분산제의 뜻이에요."}]}},{"p":4,"title":"일반 도료 (1) 수성 페인트 ①~③","terms":["water-based paint","발수성 수성 페인트","비닐 페인트","도료","Gypsum Board","경량철골"],"pass1":[{"kind":"say","lines":["여기부터 **도료**의 종류예요. 먼저 가장 흔한 일반 도료부터 봐요.","**수성 페인트(water-based paint)**는 물로 묽혀 쓰는 페인트예요.","냄새가 적고 빨리 말라서 집 안 벽과 천장에 제일 많이 써요."]},{"kind":"compare","head":"수성 페인트 세 가지, 쓰는 곳으로 구별","cols":["이름","쓰는 곳"],"rows":[["**발수성 수성 페인트**","비가 닿는 바깥 벽"],["오염제거 기능 수성 페인트","자주 닦는 병원, 학교"],["**비닐 페인트**","매끈한 실내 벽, 천장"]]}],"pass2":[{"kind":"points","head":"(1) **수성 페인트(water-based paint)**의 정체","items":["물을 주된 희석제로 쓰는 **도료**예요. 결합재는 아크릴 수지 같은 합성수지예요.","바탕면: 콘크리트, 시멘트 모르타르, **석고보드(Gypsum Board)**, 벽지, 목재 등. 바탕재에 맞는 프라이머를 써요.","냄새가 비교적 적고, 작업성이 좋고, 건조가 빠른 편이에요.","색은 전용 조색제 또는 조색 시스템으로 만들어요.","실내 벽, 천장 마감에 널리 써요. 제품마다 내수성, 내오염성, 내후성이 달라요."]},{"kind":"points","head":"공사 순서에서의 자리","items":["3강에서 **경량철골** 벽에 **석고보드(Gypsum Board)**를 붙이고 이음매를 처리했어요.","그 면 위에 마지막으로 칠하는 것이 **수성 페인트(water-based paint)**예요.","주문으로 다시: 가설, 철거, **경량철골**, 마감. 지금은 마감 칸이에요."]},{"kind":"compare","head":"수성 페인트 ①~③","cols":["번호","이름","특징","쓰는 곳"],"rows":[["①","**발수성 수성 페인트**","빗물 침투를 억제해 바탕재 보호","콘크리트, 모르타르, 프리캐스트 콘크리트(PC) 등 외부 마감"],["②","오염제거 기능 수성 페인트","내오염성, 세척성을 높여 물이나 중성세제로 오염을 쉽게 제거","병원, 학교, 공공시설 등 청소가 잦은 곳"],["③","**비닐 페인트**","비닐계 에멀션 수지가 주성분. 평활성이 좋고 도장면이 매끄러움","실내 벽, 천장 마감. 현장 이름 VP도장"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"인테리어 현장에서 일반적으로 'VP도장' 이라고 부르는 도료는?","choices":["**비닐 페인트**","**발수성 수성 페인트**","**유성 페인트(oil-based paint)**","**바니쉬(varnish)**"],"a":0,"why":"**비닐 페인트**는 비닐계 에멀션 수지가 주성분인 수성도료예요."},{"kind":"check","q":"콘크리트, 모르타르, PC 등 외부 마감에 쓰여 빗물의 침투를 억제하는 수성도료는?","choices":["오염제거 기능 수성 페인트","**비닐 페인트**","**발수성 수성 페인트**","반광택 수성 페인트"],"a":2,"why":"발수는 물을 튕겨 낸다는 뜻이에요. **발수성 수성 페인트**가 외부 마감용이에요."},{"kind":"exam","src":"5강 문제풀이 (p52)","q":"수성도료의 장점 4가지만 기술하시오.","qko":"물로 묽히는 페인트가 좋은 점 네 가지를 쓰는 문제예요.","solve":["이 쪽 본문: 냄새가 비교적 적고 작업성이 좋으며 건조가 빠른 편이에요.","같은 덱 문제풀이 p52 의 답 네 가지를 그대로 외워요.","① 물을 용제로 사용하므로 공해가 적다. ② 건조가 빠르다.","③ 가격이 저렴하고 도포 방법이 간단하다. ④ 알칼리성에도 도포가 가능하다."],"answer":"공해가 적다(물이 용제), 건조가 빠르다, 가격이 저렴하고 도포가 간단하다, 알칼리성에도 도포 가능"},{"kind":"english","head":"서술 답안: 수성 페인트의 정의","en":"수성 페인트는 물을 주된 희석제로 사용하는 도료로, 냄새가 적고 작업성이 좋으며 건조가 빨라 실내 벽, 천장 마감에 널리 사용한다.","ko":"무엇으로 묽히는지, 장점 셋, 쓰는 곳 순서로 적어요.","tip":"물, 냄새 적음, 빨리 마름, 실내 벽."}],"walk":{"head":{"b":[0.0092,0.0368,0.135,0.1435],"c":[0,0.0208,0.2,0.1755],"r":2.026,"img":"img/L5/walk/p004_h.jpg"},"parts":[{"b":[0.02,0.235,0.66,0.27],"c":[0,0.219,0.726,0.302],"r":4.2737,"img":"img/L5/walk/p004_23_01.jpg","say":"(1) 수성 페인트 다섯 줄: 물 희석제, 바탕면, 냄새 적고 빨리 마름, 조색, 실내 벽과 천장."},{"b":[0.02,0.55,0.66,0.085],"c":[0,0.5192,0.726,0.1467],"r":8.798,"img":"img/L5/walk/p004_23_02.jpg","say":"① 발수성: 외부 마감, 빗물 침투 억제."},{"b":[0.02,0.645,0.56,0.125],"c":[0,0.629,0.616,0.157],"r":6.9752,"img":"img/L5/walk/p004_23_03.jpg","say":"② 오염제거 기능: 물이나 중성세제로 쉽게 닦임. 병원, 학교, 공공시설."},{"b":[0.02,0.785,0.66,0.13],"c":[0,0.769,0.726,0.162],"r":7.9671,"img":"img/L5/walk/p004_23_04.jpg","say":"③ 비닐 페인트: 비닐계 에멀션 수지, 매끈한 실내 마감. 현장 이름 VP도장."},{"b":[0.755,0.2,0.2,0.38],"c":[0.743,0.181,0.224,0.418],"r":0.9527,"img":"img/L5/walk/p004_23_05.jpg","say":"사진: 외벽용 수성 페인트 통."},{"b":[0.69,0.63,0.28,0.33],"c":[0.676,0.6135,0.308,0.363],"r":1.5084,"img":"img/L5/walk/p004_23_06.jpg","say":"사진: 인테리어용 수성 페인트 통 두 개."}]}},{"p":5,"title":"수성 페인트 ④⑤, 광도표, (2) 유성 페인트","terms":["water-based paint","광도","eggshell","oil-based paint","비닐 페인트","도막"],"pass1":[{"kind":"say","lines":["페인트는 반짝이는 정도로도 나뉘어요. 이것을 **광도**라고 해요.","잘 안 반짝이는 무광은 넓은 벽에, 많이 반짝이는 유광은 자주 만지는 문에 어울려요.","아래쪽은 기름 쪽 페인트인 **유성 페인트(oil-based paint)** 이야기예요."]},{"kind":"compare","head":"물 페인트와 기름 페인트","cols":["","**수성 페인트(water-based paint)**","**유성 페인트(oil-based paint)**"],"rows":[["묽히는 것","물","유기용제(신너)"],["마르는 속도","빠른 편","느린 편"],["냄새","적은 편","많은 편"],["잘 쓰는 곳","실내 벽, 천장","목재, 금속 표면 보호와 착색"]]}],"pass2":[{"kind":"points","head":"④ 반광택, ⑤ 고광택 **수성 페인트(water-based paint)**","items":["④ 반광택: 무광과 고광택의 중간 정도 광택. 무광보다 오염 제거와 유지관리가 쉬워요.","⑤ 고광택: 높은 광택과 우수한 세척성. 광택과 내오염성이 필요한 부분에 써요.","⑤ 아래 둘째 줄은 앞 쪽 ③ **비닐 페인트** 설명과 똑같은 문장이에요(3회독 주의 참고)."]},{"kind":"compare","head":"**광도** 표 (그림 속 숫자, 슬라이드 그대로)","cols":["광도","광택","추천용도"],"rows":[["무광 (FLAT)","~5%","벽체, 천장"],["벨벳광 (VELVET)","5~9%","침실"],["계란광 (반무광, EGGSHELL)","10~15%","벽체, 거실, 아이방"],["저광 (LOW SHEEN)","20~25%","주방"],["반광 (SEMI-GLOSS)","40~50%","주방, 욕실, 방문, 몰딩, 가구"],["유광 (고광, GLOSS)","70~80%","싱크대, 방문, 문틀"]]},{"kind":"points","head":"(2) **유성 페인트(oil-based paint)**의 정체","items":["건성유 또는 알키드수지 등의 유성 결합재를 쓰고, 유기용제(신너)로 희석해 써요.","마르면 단단하고 치밀한 **도막**. 내수성, 내후성, 내마모성이 우수하고 광택 표현이 쉬워요.","목재나 금속의 표면 보호와 착색에 써요. 필요하면 방청성과 내구성을 높일 수 있어요.","단점: 수성보다 냄새와 휘발성유기화합물(VOC)이 많고 건조가 느린 편이에요."]},{"kind":"points","head":"**유성 페인트(oil-based paint)** 시공 주의 두 가지","items":["너무 두껍게 칠하거나 한곳에 많이 바르면 흐름, 처짐이 생겨 눈물자국 같은 결함이 남아요.","기존 **도막** 위에 다시 칠할 때는 오염을 없애고 사포로 연마해 접착력을 높인 뒤 칠해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"슬라이드 광도표에서 광택 ~5%, 추천용도가 '벽체, 천장' 인 것은?","choices":["무광(FLAT)","벨벳광(VELVET)","저광(LOW SHEEN)","유광(고광, GLOSS)"],"a":0,"why":"무광은 ~5% 로 벽체, 천장에 추천해요. 유광은 70~80% 로 싱크대, 방문, 문틀이에요."},{"kind":"check","q":"**유성 페인트(oil-based paint)**에 대한 설명으로 옳지 않은 것은?","choices":["유기용제로 희석해 쓴다","수성 페인트보다 건조가 빠르다","내수성, 내후성, 내마모성이 우수하다","두껍게 칠하면 흐름, 처짐이 생길 수 있다"],"a":1,"why":"유성은 수성보다 냄새와 VOC 가 많고 건조가 느린 편이에요."},{"kind":"exam","src":"기출 모양 연습문제","q":"광택이 낮은 것부터 나열하시오: 반광, 무광, 유광, 저광, 벨벳광, 계란광","qko":"슬라이드 **광도**표의 여섯 칸을 낮은 광택부터 줄 세우는 문제예요.","solve":["무광 ~5% → 벨벳광 5~9% → 계란광 10~15%.","저광 20~25% → 반광 40~50% → 유광 70~80%.","표의 윗줄 세 칸, 아랫줄 세 칸을 왼쪽에서 오른쪽으로 읽은 순서와 같아요."],"answer":"무광 → 벨벳광 → 계란광 → 저광 → 반광 → 유광"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["⑤ 고광택 수성 페인트의 둘째 줄은 ③ 비닐 페인트 설명을 그대로 복사한 문장이에요. 고광택의 핵심은 높은 광택과 우수한 세척성이에요.","**에그쉘 광(eggshell)**: 이 쪽 표는 계란광 10~15% 와 저광 20~25% 를 따로 적지만, 뒤 p42 는 '저광 정도의 광택' 이라고 해요. 문제에 쓰인 말을 따라요.","유성은 느리게, 수성은 빠르게 말라요. 반대로 쓰면 틀려요."]}],"walk":{"head":null,"parts":[{"b":[0.02,0.29,0.5,0.125],"c":[0,0.274,0.55,0.157],"r":6.2279,"img":"img/L5/walk/p005_24_01.jpg","say":"④ 반광택 수성 페인트: 무광과 고광택의 중간."},{"b":[0.02,0.43,0.5,0.175],"c":[0,0.414,0.55,0.207],"r":4.7236,"img":"img/L5/walk/p005_24_02.jpg","say":"⑤ 고광택 수성 페인트: 첫 줄이 핵심. 둘째 줄은 ③ 비닐 페인트 문장의 복사예요."},{"b":[0.575,0.05,0.39,0.545],"c":[0.5555,0.0227,0.429,0.5995],"r":1.2722,"img":"img/L5/walk/p005_24_03.jpg","say":"광도표: 무광 ~5%부터 유광 70~80%까지 여섯 칸과 추천용도."},{"b":[0.02,0.635,0.62,0.315],"c":[0,0.619,0.682,0.347],"r":3.4941,"img":"img/L5/walk/p005_24_04.jpg","say":"(2) 유성 페인트 여섯 줄: 결합재와 신너, 단단한 도막, 쓰는 곳, 냄새와 VOC, 흐름과 처짐, 재도장."},{"b":[0.65,0.62,0.32,0.37],"c":[0.634,0.593,0.352,0.407],"r":1.5375,"img":"img/L5/walk/p005_24_05.jpg","say":"사진: 유성 페인트(에나멜) 통과 붓으로 칠하는 모습."}]}},{"p":6,"title":"일반 도료 (3) 퍼티","terms":["putty","2액형 퍼티","폴리에스테르 퍼티","에폭시 퍼티","Gypsum Board","하도"],"pass1":[{"kind":"say","lines":["**퍼티(putty)**는 벽의 패인 곳, 흠집, 금 간 곳을 메워 평평하게 만드는 재료예요.","현장에서는 '빠데' 라고도 불러요."]},{"kind":"analogy","head":"퍼티는 컨실러","scene":"화장할 때 잡티를 컨실러로 먼저 메우고 가려요. 칠하기 전 벽에도 같은 일을 해요.","map":[["잡티, 패인 곳","바탕면의 요철, 흠집, 균열, 접합부"],["컨실러","**퍼티(putty)**"],["매끈해진 피부","평활한 표면"]]}],"pass2":[{"kind":"points","head":"(3) **퍼티(putty)**의 정체","items":["바탕면의 요철, 흠집, 균열 또는 접합부를 메워 표면을 평활하게 만드는 재료예요.","수지, 안료, 첨가제 등을 섞어 만들어요.","필요한 성질: 시공이 쉽고, 접착력이 좋고, 경화(굳음) 후 연마가 잘 돼야 해요.","내부용과 외부용이 있어요. 외부용은 내수성, 내알칼리성, 내후성이 강화돼 있어요."]},{"kind":"points","head":"공사 순서에서의 자리","items":["**석고보드(Gypsum Board)**를 붙인 뒤, 칠하기 전에 해요. 오른쪽 위 사진이 석고보드 시공 후 퍼티 작업이에요.","칠의 층으로 보면 맨 아래 기초 작업인 **하도** 쪽 일이에요(p9 그림)."]},{"kind":"compare","head":"퍼티 ①~③","cols":["이름","몇 액형","특징과 쓰는 곳"],"rows":[["① 수성 탄성 퍼티","1액형","마른 뒤에도 탄성 유지. 미세 균열이나 움직임이 생길 부위의 보수, 면 정리"],["② **폴리에스테르 퍼티** (포리빠데)","2액형","경화가 빠르고 단단, 연마성 좋음. 금속, 목재 표면 보수와 형상 수정"],["③ **에폭시 퍼티**","2액형","경화수축이 적고 접착력, 내구성 우수. 바닥, 벽 결손부, 균열, 구조물 보수와 접착"]]},{"kind":"points","head":"**2액형 퍼티**란","items":["주재와 경화제를 섞어 쓰는 제품이에요.","주재는 몸통 재료, 경화제는 굳게 만드는 재료예요. 섞어야 단단해져요.","1액형은 섞지 않고 그대로 쓰는 것이에요. 수성 탄성 퍼티가 1액형이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"주재와 경화제를 혼합하여 사용하는 퍼티를 무엇이라 하는가?","choices":["1액형 퍼티","**2액형 퍼티**","수성 탄성 퍼티","천연 퍼티"],"a":1,"why":"**폴리에스테르 퍼티**와 **에폭시 퍼티**가 2액형이에요."},{"kind":"check","q":"현장에서 '포리빠데' 라고 부르는 것은?","choices":["수성 탄성 퍼티","**폴리에스테르 퍼티**","**에폭시 퍼티**","천연 퍼티"],"a":1,"why":"'빠데' 는 **퍼티(putty)** 전체, '포리빠데' 는 **폴리에스테르 퍼티**예요."},{"kind":"check","q":"경화수축이 적고 접착력과 내구성이 우수해 바닥, 벽의 결손부 보수에 쓰는 퍼티는?","choices":["**에폭시 퍼티**","수성 탄성 퍼티","**폴리에스테르 퍼티**","천연 퍼티"],"a":0,"why":"경화수축이 적은 것은 **에폭시 퍼티**, 경화가 빠르고 연마성이 좋은 것은 폴리에스테르예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["2액형은 폴리에스테르와 에폭시, 1액형은 수성 탄성 퍼티예요.","'빠데' 는 퍼티 전체, '포리빠데' 는 폴리에스테르 퍼티예요.","외부용 퍼티가 강화된 성질은 내수성, 내알칼리성, 내후성이에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.135,0.1412],"c":[0,0.0208,0.2,0.1732],"r":2.0529,"img":"img/L5/walk/p006_h.jpg"},"parts":[{"b":[0.02,0.23,0.57,0.225],"c":[0,0.214,0.627,0.257],"r":4.3372,"img":"img/L5/walk/p006_24_01.jpg","say":"(3) 퍼티 네 줄: 정의, 성질, 내부용과 외부용, 2액형의 뜻. 보라색 메모 '빠데'."},{"b":[0.02,0.51,0.63,0.085],"c":[0,0.4825,0.693,0.14],"r":8.8,"img":"img/L5/walk/p006_24_02.jpg","say":"① 수성 탄성 퍼티: 탄성 유지, 1액형."},{"b":[0.02,0.605,0.5,0.125],"c":[0,0.589,0.55,0.157],"r":6.2279,"img":"img/L5/walk/p006_24_03.jpg","say":"② 폴리에스테르 퍼티: 2액형, 금속과 목재 보수. 보라색 메모 '포리빠데'."},{"b":[0.02,0.745,0.47,0.125],"c":[0,0.729,0.517,0.157],"r":5.8542,"img":"img/L5/walk/p006_24_04.jpg","say":"③ 에폭시 퍼티: 2액형, 경화수축이 적음."},{"b":[0.75,0.18,0.215,0.33],"c":[0.738,0.1635,0.239,0.363],"r":1.1705,"img":"img/L5/walk/p006_24_05.jpg","say":"사진: 석고보드 시공 후 퍼티 작업하는 모습."},{"b":[0.59,0.62,0.38,0.285],"c":[0.571,0.604,0.418,0.317],"r":2.3442,"img":"img/L5/walk/p006_24_06.jpg","say":"사진: 큰 통(주제)과 작은 튜브로 된 2액형 퍼티 제품, 에폭시 퍼티 제품."}]}},{"p":7,"title":"일반 도료 (4) 바니쉬","terms":["varnish","도막","stain"],"pass1":[{"kind":"say","lines":["**바니쉬(varnish)**는 나무 무늬가 그대로 보이는 투명한 칠이에요.","나무 위에 투명한 보호막을 한 겹 씌운다고 생각하면 돼요.","다음 쪽 **스테인(stain)**과 짝으로 외워요."]}],"pass2":[{"kind":"points","head":"(4) **바니쉬(varnish)**의 정체","items":["목재의 무늬와 질감을 살리면서 표면을 보호하는 투명 도료예요.","수지와 용제 등이 주성분이고, 칠한 뒤 투명한 **도막**을 만들어요.","그 **도막**이 목재 표면의 내마모성, 내수성, 내오염성, 내구성을 높여요.","가구, 목재 마감재, 마루, 문, 몰딩에 널리 쓰고, 목재의 색과 무늬를 선명하게 보여 줘요."]},{"kind":"points","head":"종류와 칠하는 법","items":["제품에 따라 유성, 수성, 우레탄계, 아크릴계로 나뉘어요. 부위와 요구 성능에 맞게 골라요.","여러 번 얇게 칠하고, 칠 사이마다 충분히 말려요.","필요하면 연마해요. 그러면 더 매끄럽고 균일한 표면이 나와요."]},{"kind":"points","head":"사진에서 볼 것","items":["왼쪽 나무판 세 장: 무광, 반광, 유광 **바니쉬(varnish)**를 칠한 비교예요. 오른쪽으로 갈수록 반짝여요.","오른쪽: 바니쉬 제품 통 사진이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**바니쉬(varnish)**에 대한 설명으로 옳은 것은?","choices":["목재 무늬를 가리는 불투명 도료다","투명한 도막을 형성해 목재 표면을 보호한다","한 번에 두껍게 칠하는 것이 좋다","금속의 녹을 막는 하도용 도료다"],"a":1,"why":"투명 도막으로 보호해요. 여러 번 얇게 칠하고 사이사이 충분히 건조해요."},{"kind":"exam","src":"5강 문제풀이 (p53)","q":"목재 바니쉬칠 공정 순서를 보기에서 골라 나열하시오. (①착색 ②눈먹임 ③초벌칠 ④닦기, 마무리 ⑤정벌칠 ⑥바탕손질)","qko":"나무에 바니쉬를 칠하는 여섯 단계를 순서대로 줄 세우는 문제예요.","solve":["바탕을 먼저 다듬어요: ⑥ 바탕손질.","나뭇결의 작은 구멍을 메워요: ② 눈먹임.","색을 입혀요: ① 착색. (**스테인(stain)**이 하는 일)","두 번 칠해요: ③ 초벌칠 → ⑤ 정벌칠.","마지막: ④ 닦기, 마무리."],"answer":"⑥ → ② → ① → ③ → ⑤ → ④"},{"kind":"english","head":"서술 답안: 바니쉬의 정의","en":"바니쉬는 목재의 무늬와 질감을 살리면서 표면을 보호하기 위해 사용하는 투명 도료로, 도장 후 투명한 도막을 형성한다.","ko":"무늬를 살린다, 보호한다, 투명 도막. 세 낱말이 꼭 들어가야 해요.","tip":"바, 눈, 착, 초, 정, 닦 으로 칠 순서도 같이 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["p53 아래의 '바니쉬 도장의 일반적인 순서'(샌딩, 눈먹임, 2차 샌딩, 초벌 착색, 연마지 닦기, 정벌칠, 왁스칠)는 보기 순서와 단계 이름이 달라요. 시험 답은 보기 번호 순서를 써요.","바니쉬는 한 번에 두껍게가 아니라 여러 번 얇게 칠해요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.135,0.1915],"c":[0,0.0208,0.2,0.2235],"r":1.5909,"img":"img/L5/walk/p007_h.jpg"},"parts":[{"b":[0.02,0.235,0.42,0.075],"c":[0,0.2175,0.462,0.11],"r":7.4667,"img":"img/L5/walk/p007_23_01.jpg","say":"(4) 바니쉬 첫 줄: 무늬와 질감을 살리는 투명 도료."},{"b":[0.02,0.32,0.63,0.18],"c":[0,0.304,0.693,0.212],"r":5.8113,"img":"img/L5/walk/p007_23_02.jpg","say":"나머지 네 줄: 투명 도막, 쓰는 곳, 종류, 여러 번 얇게 칠하기."},{"b":[0.04,0.57,0.295,0.305],"c":[0.0252,0.554,0.3245,0.337],"r":1.7118,"img":"img/L5/walk/p007_23_03.jpg","say":"사진: 무광, 반광, 유광 바니쉬를 칠한 나무판."},{"b":[0.355,0.59,0.18,0.27],"c":[0.343,0.574,0.204,0.302],"r":1.2009,"img":"img/L5/walk/p007_23_04.jpg","say":"사진: 바니쉬 제품 통."}]}},{"p":8,"title":"일반 도료 (5) 스테인","terms":["stain","varnish","도막"],"pass1":[{"kind":"say","lines":["**스테인(stain)**은 나무에 스며들어 색만 입히는 착색재예요.","페인트처럼 덮지 않아서 나무 무늬가 그대로 보여요."]},{"kind":"compare","head":"바니쉬와 스테인","cols":["","**바니쉬(varnish)**","**스테인(stain)**"],"rows":[["하는 일","투명한 막으로 보호","색을 입힘"],["나무 무늬","선명하게 보임","그대로 드러남"]]}],"pass2":[{"kind":"points","head":"(5) **스테인(stain)**의 정체","items":["목재 표면에 색을 입히면서 목재 고유의 무늬와 질감은 그대로 드러나게 하는 착색재예요.","일반 페인트처럼 표면을 완전히 덮지 않아요. 목재 내부에 침투하거나 표면에 얇게 착색돼요.","그래서 목리(나뭇결 무늬)가 강조돼요.","목재 색을 균일하게 하거나 원하는 색조로 맞출 때 써요. 수성, 유성, 알코올계가 있어요."]},{"kind":"points","head":"공사 순서에서의 자리","items":["**스테인(stain)** 자체는 표면 보호 성능이 제한적이에요.","그래서 필요하면 그 위에 **바니쉬(varnish)**, 우레탄, 래커 같은 투명 마감재를 추가로 칠해요.","즉 순서는 스테인으로 색 입히기 → 투명 마감재로 **도막** 만들기예요."]},{"kind":"points","head":"사진에서 볼 것","items":["왼쪽: 여러 색 스테인을 칠한 나무 색 견본이에요.","오른쪽: 붓으로 나무판에 스테인을 바르는 모습이에요. 나뭇결이 비쳐 보여요.","슬라이드의 참고 영상 링크는 스테인 칠하는 법이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**스테인(stain)**에 대한 설명으로 옳지 않은 것은?","choices":["목재 무늬와 질감을 그대로 드러낸다","표면을 완전히 덮어 무늬를 가린다","표면 보호 성능이 제한적이다","수성, 유성, 알코올계 등이 있다"],"a":1,"why":"스테인은 덮는 것이 아니라 침투하거나 얇게 착색해요."},{"kind":"exam","src":"5강 문제풀이 (p53)","q":"다음을 맞는 것끼리 연결하시오. ①방청제 ②방부제 ③착색제 ④희석제 / (가)신너 (나)광명단 (다)크레오소트 (라)오일스테인","qko":"재료가 하는 일과 실제 재료 이름을 짝짓는 문제예요.","solve":["착색제는 색을 입히는 재료예요. 이 쪽의 **스테인(stain)**이 착색재예요. ③ → (라) 오일스테인.","방청제는 녹 방지예요. p14 의 **광명단(red lead)**이에요. ① → (나).","희석제는 묽히는 재료예요. p5 **유성 페인트(oil-based paint)**를 묽히는 신너예요. ④ → (가).","남은 방부제는 크레오소트예요. ② → (다)."],"answer":"①→(나), ②→(다), ③→(라), ④→(가)"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["스테인만 칠하면 보호가 약해요. 보호는 바니쉬 같은 투명 마감재의 몫이에요.","스테인은 '덮는' 것이 아니라 '스며드는' 것이에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.135,0.1915],"c":[0,0.0208,0.2,0.2235],"r":1.5909,"img":"img/L5/walk/p008_h.jpg"},"parts":[{"b":[0.02,0.235,0.48,0.075],"c":[0,0.2175,0.528,0.11],"r":8.5333,"img":"img/L5/walk/p008_23_01.jpg","say":"(5) 스테인 첫 줄: 색을 입히고 무늬와 질감은 그대로. 보라색 메모 '나무 무늬'."},{"b":[0.02,0.325,0.58,0.04],"c":[0,0.2806,0.638,0.1289],"r":8.7992,"img":"img/L5/walk/p008_23_02.jpg","say":"둘째 줄: 덮지 않고 침투하거나 얇게 착색해 목리를 강조."},{"b":[0.02,0.37,0.6,0.04],"c":[0,0.3233,0.66,0.1333],"r":8.8022,"img":"img/L5/walk/p008_23_03.jpg","say":"셋째 줄: 색을 균일하게, 수성, 유성, 알코올계."},{"b":[0.02,0.415,0.6,0.04],"c":[0,0.3683,0.66,0.1333],"r":8.8022,"img":"img/L5/walk/p008_23_04.jpg","say":"넷째 줄: 보호 성능이 제한적이라 투명 마감재를 추가로 도장."},{"b":[0.025,0.55,0.53,0.345],"c":[0,0.5328,0.583,0.3795],"r":2.7311,"img":"img/L5/walk/p008_23_05.jpg","say":"사진: 스테인 색 견본과 붓으로 바르는 모습."}]}},{"p":9,"title":"일반 도료 (6) 실러, 쵸킹, 하도, 중도, 상도","terms":["sealer","쵸킹","하도","중도","상도","putty"],"pass1":[{"kind":"say","lines":["**실러(sealer)**는 맨 처음 바르는 밑칠이에요. 바탕이 페인트를 너무 빨아들이지 않게 막아요.","칠은 세 층으로 올라가요. 아래부터 **하도**, **중도**, **상도**예요."]},{"kind":"analogy","head":"칠의 세 층은 화장 순서","scene":"화장은 베이스를 깔고, 색조를 올리고, 마무리로 고정해요. 칠도 똑같이 세 번 올려요.","map":[["베이스","**하도**: 기초 작업 (젯소, 프라이머, **퍼티(putty)**)"],["색조","**중도**: 페인트칠"],["마무리","**상도**: 마감, 유지관리, 코팅"]]}],"pass2":[{"kind":"points","head":"(6) **실러(sealer)**의 정체","items":["바탕면의 흡수성을 조절하고 상도 도료와의 부착성을 높이는 하도용 도료예요.","바탕면에 스며들거나 얇은 도막을 만들어 표면을 안정시켜요.","상도 도료가 지나치게 흡수되는 것을 줄여 균일하게 칠해지게 도와요.","종류: 콘크리트, 모르타르용 실러와 목재용 샌딩실러."]},{"kind":"points","head":"**쵸킹**이란","items":["도막 표면을 문지르면 가루 성분이 묻어 나오는 현상이에요.","칠한 수성페인트가 풍화로 시간이 지나며 깎여 나가고 안료 성분만 남는 현상이에요.","**쵸킹**이 생긴 구도막이나 흡수성이 큰 바탕면에는 **실러(sealer)**를 칠해 표면을 안정시켜요.","왼쪽 아래 사진 두 장이 손가락에 가루가 묻어 나온 모습이에요."]},{"kind":"compare","head":"[하도, 중도, 상도] 그림","cols":["층","하는 일"],"rows":[["3. **상도**","마감 및 유지관리, 코팅 작업"],["2. **중도**","페인트칠"],["1. **하도**","가장 먼저 기초 작업 (주로 젯소, 프라이머, 퍼티 작업)"],["표면","맨 아래 바탕"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"바탕면의 흡수성을 조절하고 상도와의 부착성을 높이는 하도용 도료는?","choices":["**실러(sealer)**","**바니쉬(varnish)**","**스테인(stain)**","**유성 페인트(oil-based paint)**"],"a":0,"why":"**실러(sealer)**는 **하도**용이에요. 상도 도료가 지나치게 흡수되는 것을 줄여요."},{"kind":"check","q":"도막 표면을 문질렀을 때 가루 성분이 묻어 나오는 현상은?","choices":["**쵸킹**","흐름","처짐","기포 자국"],"a":0,"why":"수성페인트가 풍화로 깎여 나가고 안료 성분만 남는 현상이에요. 흐름, 처짐은 p5 유성 페인트의 결함이에요."},{"kind":"exam","src":"기출 모양 연습문제","q":"도장의 세 층을 아래에서 위 순서로 쓰고, 각 층에서 하는 일을 쓰시오.","qko":"표면 위에 쌓는 칠 세 층의 이름과 역할을 묻는 문제예요.","solve":["맨 아래 **하도**: 가장 먼저 하는 기초 작업. 주로 젯소, 프라이머, 퍼티 작업.","가운데 **중도**: 페인트칠.","맨 위 **상도**: 마감 및 유지관리, 코팅 작업."],"answer":"하도(기초 작업: 젯소, 프라이머, 퍼티) → 중도(페인트칠) → 상도(마감, 유지관리, 코팅)"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["소제목은 '실라/ 실러', 사진 캡션은 '실라 페인트' 로 표기가 섞여 있어요. 같은 재료예요.","**실러(sealer)**는 상도가 아니라 **하도**용이에요.","**쵸킹**은 안료 성분만 남는 현상이에요. 수지가 남는다고 하면 틀려요."]}],"walk":{"head":null,"parts":[{"b":[0.02,0.235,0.47,0.075],"c":[0,0.2175,0.517,0.11],"r":8.3556,"img":"img/L5/walk/p009_23_01.jpg","say":"(6) 실라/ 실러 첫 줄: 흡수성 조절, 부착성 향상, 하도용 도료."},{"b":[0.02,0.325,0.64,0.13],"c":[0,0.309,0.704,0.162],"r":7.7257,"img":"img/L5/walk/p009_23_02.jpg","say":"둘째~넷째 줄: 표면 안정, 콘크리트와 목재용 실러, 쵸킹 바탕에 사용."},{"b":[0.02,0.47,0.5,0.12],"c":[0,0.454,0.55,0.152],"r":6.4327,"img":"img/L5/walk/p009_23_03.jpg","say":"* 쵸킹이란? 가루가 묻어 나오는 현상, 안료 성분만 남는 현상."},{"b":[0.025,0.61,0.54,0.355],"c":[0,0.5922,0.594,0.3905],"r":2.7042,"img":"img/L5/walk/p009_23_04.jpg","say":"사진: 벽을 문지른 손가락에 하얀 가루가 묻은 쵸킹 모습."},{"b":[0.64,0.035,0.34,0.25],"c":[0.623,0.019,0.374,0.282],"r":2.3578,"img":"img/L5/walk/p009_23_05.jpg","say":"오른쪽 위 그림: 표면 위에 1. 하도, 2. 중도, 3. 상도가 쌓여요."},{"b":[0.6,0.61,0.335,0.34],"c":[0.5832,0.593,0.3685,0.374],"r":1.7516,"img":"img/L5/walk/p009_23_06.jpg","say":"사진: 실라 페인트와 붓으로 바르는 모습."}]}},{"p":10,"title":"일반 도료 (7) 내열도료","terms":["내열도료","fire-proof paint","resin","pigment"],"pass1":[{"kind":"say","lines":["**내열도료**는 뜨거운 곳에 칠해도 버티는 페인트예요.","보일러, 굴뚝처럼 늘 뜨거운 쇠붙이에 써요."]},{"kind":"compare","head":"이름이 비슷한 두 도료","cols":["이름","한 줄 뜻"],"rows":[["**내열도료**","도료 자체가 높은 온도에 견딤"],["**내화도료(fire-proof paint)**","불이 났을 때 철골 온도가 늦게 오르게 해 구조체를 지킴"]]}],"pass2":[{"kind":"points","head":"(7) **내열도료**의 정체","items":["고온에 노출되는 부위에서 도막의 변색, 박리, 열화를 억제하고 바탕재를 보호하는 도료예요.","결합재는 내열성이 우수한 실리콘수지 등이에요. 이 도료의 **수지(resin)**예요.","제품에 따라 알루미늄 등 내열 안료를 섞어요. **안료(pigment)**가 열을 견디는 데도 쓰이는 예예요.","사용 가능한 온도는 제품마다 달라요. 수백 ℃ 고온에 견디는 제품도 있어요."]},{"kind":"points","head":"쓰는 곳","items":["보일러, 난방기기, 배관, 굴뚝, 배기설비, 산업용 가열장치.","모두 고온에 노출되는 금속 표면이에요. 그 표면의 보호와 부식 방지에 써요."]},{"kind":"points","head":"*참고 상자","items":["**내열도료** = 도료 자체가 높은 온도에 견딤.","**내화도료(fire-proof paint)** = 화재 시 철골 등의 온도 상승을 지연시켜 구조체를 보호함.","내화도료는 뒤 기능성 도료(p12)에서 자세히 나와요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"보일러, 굴뚝, 배관 등 고온에 노출되는 금속 표면에 쓰는 일반 도료는?","choices":["**내열도료**","**내화도료(fire-proof paint)**","**방염도료(fire resisting paint)**","**비닐 페인트**"],"a":0,"why":"도료 자체가 높은 온도에 견디는 것이 **내열도료**예요."},{"kind":"check","q":"**내열도료**의 결합재로 슬라이드에 적힌 수지는?","choices":["실리콘수지","알키드수지","비닐계 에멀션 수지","에폭시수지"],"a":0,"why":"알키드수지는 유성 페인트, 비닐계 에멀션 수지는 비닐 페인트, 에폭시수지는 에폭시 퍼티예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["내열은 '도료 자체' 가 견디고, 내화는 '불날 때 철골' 을 지켜요.","사진 속 제품 라벨 '고급형/600℃ 이하' 는 그 제품의 표시예요. 본문 기준은 '수백 ℃' 예요.","내열도료는 일반 도료 (7), 내화도료는 기능성 도료 (2) 로 분류가 달라요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.135,0.1915],"c":[0,0.0208,0.2,0.2235],"r":1.5909,"img":"img/L5/walk/p010_h.jpg"},"parts":[{"b":[0.02,0.235,0.53,0.075],"c":[0,0.2136,0.583,0.1178],"r":8.7983,"img":"img/L5/walk/p010_23_01.jpg","say":"(7) 내열 도료 첫 줄: 고온에서 변색, 박리, 열화 억제."},{"b":[0.02,0.325,0.61,0.13],"c":[0,0.309,0.671,0.162],"r":7.3635,"img":"img/L5/walk/p010_23_02.jpg","say":"둘째~넷째 줄: 실리콘수지, 알루미늄 안료, 수백 ℃, 보일러와 굴뚝 등."},{"b":[0.025,0.485,0.36,0.2],"c":[0.007,0.469,0.396,0.232],"r":3.0345,"img":"img/L5/walk/p010_23_03.jpg","say":"*참고 상자: 내열도료와 내화도료의 차이."},{"b":[0.41,0.485,0.195,0.455],"c":[0.398,0.4622,0.219,0.5005],"r":0.7779,"img":"img/L5/walk/p010_23_04.jpg","say":"사진: 내열도료 통. 라벨의 600℃ 이하는 이 제품의 표시예요."},{"b":[0.7,0.52,0.16,0.42],"c":[0.68,0.499,0.2,0.462],"r":0.7696,"img":"img/L5/walk/p010_23_05.jpg","say":"사진: 내화도료 통. 철골 그림이 그려져 있어요."}]}},{"p":11,"title":"기능성 도료 (1) 천연, 친환경 페인트","terms":["천연, 친환경 페인트","세라믹 수성도료","stain","putty","oil-based paint"],"pass1":[{"kind":"say","lines":["여기부터는 기능성 도료예요. 색 말고 특별한 일을 하나 더 하는 도료들이에요.","첫 번째 **천연, 친환경 페인트**는 몸에 해로운 성분을 줄인 페인트예요."]},{"kind":"points","head":"기능성 도료 일곱 가지 지도","items":["(1) **천연, 친환경 페인트**","(2) **내화도료(fire-proof paint)**, (3) **방염도료(fire resisting paint)**, (4) **방청도료(rust resisting paint)**","(5) **다채무늬 도료(multi color paint)**, (6) **본타일**, (7) **결로 방지 도료**"]}],"pass2":[{"kind":"points","head":"(1) **천연, 친환경 페인트**의 정의","items":["천연 또는 자연 유래 원료를 사용하거나,","일반 도료에 비해 VOC, 중금속 등 유해물질의 사용과 방출을 줄인 도료예요.","원료 예(보라색 메모): 식물성 오일, 천연수지, 광물성 안료 등."]},{"kind":"compare","head":"종류 네 가지","cols":["번호","이름","특징"],"rows":[["①","네추럴 천연 수성도료","자연 유래 원료가 주성분인 수성도료. 실내 벽, 천장. 저VOC, 저취, 자연스러운 무광택 질감"],["②","천연 **스테인(stain)**","식물성 오일, 천연수지로 목재에 색을 입히고 목리를 살림. 아이들 대상 가구, 인테리어"],["③","내, 외부용 천연 **퍼티(putty)**","황토, 점토, 광물질 원료. 요철, 균열을 메워 면을 고르게. 원료 고유의 색감, 질감"],["④","**세라믹 수성도료**","무기질 원료가 주원료. 난연성, 내구성. 제품에 따라 항균, 항곰팡이. 분말형은 현장에서 물과 혼합"]]},{"kind":"points","head":"VOC 다시 보기","items":["VOC 는 휘발성유기화합물이에요. p5 에서 **유성 페인트(oil-based paint)**가 수성보다 VOC 가 많다고 했죠.","**천연, 친환경 페인트**는 이 VOC 와 중금속을 줄인 쪽이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"아이들을 대상으로 하는 가구나 인테리어에 주로 많이 사용되는 친환경 도료는?","choices":["천연 **스테인(stain)**","**광명단(red lead)**","**징크 프라이머(Zinc Primer)**","**에폭시 퍼티**"],"a":0,"why":"천연 스테인은 식물성 오일, 천연수지로 목재에 색을 입혀요."},{"kind":"check","q":"무기질 원료가 주원료이고, 분말형 제품은 현장에서 물과 혼합해 쓰는 도료는?","choices":["**세라믹 수성도료**","네추럴 천연 수성도료","**비닐 페인트**","**내열도료**"],"a":0,"why":"**세라믹 수성도료**는 난연성, 내구성을 가지고 제품에 따라 항균, 항곰팡이 기능도 있어요."},{"kind":"english","head":"서술 답안: 천연, 친환경 페인트의 정의","en":"천연, 친환경 페인트는 천연 또는 자연 유래 원료를 사용하거나, 일반 도료에 비해 VOC, 중금속 등 유해물질의 사용과 방출을 줄인 도료이다.","ko":"원료 쪽 정의와 유해물질 쪽 정의, 두 갈래를 '거나' 로 이어요.","tip":"자연 원료, 또는 유해물질 줄이기. 종류는 수성도료, 스테인, 퍼티, 세라믹 넷."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["천연 퍼티의 원료는 황토, 점토, 광물질이에요. 세라믹 수성도료의 원료는 무기질 원료예요.","기능성 도료 (1)~(7) 순서: 친환경, 내화, 방염, 방청, 다채무늬, 본타일, 결로 방지."]}],"walk":{"head":{"b":[0.0092,0.0368,0.0968,0.0462],"c":[0,0.0208,0.2,0.0782],"r":4.5467,"img":"img/L5/walk/p011_h.jpg"},"parts":[{"b":[0.02,0.235,0.73,0.075],"c":[0,0.1914,0.803,0.1622],"r":8.8012,"img":"img/L5/walk/p011_23_01.jpg","say":"(1) 천연, 친환경 페인트의 정의. 위 보라색 메모는 원료 예."},{"b":[0.02,0.355,0.48,0.12],"c":[0,0.339,0.528,0.152],"r":6.1754,"img":"img/L5/walk/p011_23_02.jpg","say":"① 네추럴 천연 수성도료: 저VOC, 저취, 무광택 질감."},{"b":[0.02,0.485,0.56,0.12],"c":[0,0.469,0.616,0.152],"r":7.2047,"img":"img/L5/walk/p011_23_03.jpg","say":"② 천연 스테인: 목리를 살림, 아이들 가구."},{"b":[0.02,0.615,0.65,0.125],"c":[0,0.599,0.715,0.157],"r":8.0962,"img":"img/L5/walk/p011_23_04.jpg","say":"③ 내, 외부용 천연 퍼티: 황토, 점토, 광물질."},{"b":[0.02,0.755,0.5,0.17],"c":[0,0.739,0.55,0.202],"r":4.8405,"img":"img/L5/walk/p011_23_05.jpg","say":"④ 세라믹 수성도료: 무기질 원료, 분말형은 물과 혼합."},{"b":[0.735,0.085,0.225,0.87],"c":[0.6278,0.0415,0.3722,0.957],"r":0.6914,"img":"img/L5/walk/p011_23_06.jpg","say":"사진: 천연 스테인 제품과 색상표."}]}},{"p":12,"title":"기능성 도료 (2) 내화도료","terms":["fire-proof paint","하도","중도","상도","rust resisting paint","도막"],"pass1":[{"kind":"say","lines":["**내화도료(fire-proof paint)**는 불이 났을 때 철골 기둥을 지키는 페인트예요.","평소엔 보통 칠처럼 있다가, 불이 나면 부풀어 올라 두꺼운 방패가 돼요."]},{"kind":"analogy","head":"부풀어 오르는 방패","scene":"뜨거워지면 빵처럼 부풀어 구멍 많은 숯 층이 되고, 그 층이 열을 막아요.","map":[["부풀기","발포, 팽창"],["구멍 많은 숯 층","다공성의 단열 탄화층"],["지키는 대상","철골 기둥, 보"]]}],"pass2":[{"kind":"points","head":"(2) **내화도료(fire-proof paint)**의 정체","items":["화재 시 철골 등 구조재의 온도 상승을 지연시켜 구조물을 보호하는 기능성 도료예요.","평상시에는 일반 **도막**처럼 유지돼요.","화재로 고온에 노출되면 도막이 발포, 팽창해 다공성의 단열 탄화층을 만들어요.","이 층이 열이 철재에 전달되는 것을 지연시켜요."]},{"kind":"points","head":"쓰는 곳과 두께","items":["주로 철골 기둥, 보처럼 내화성능이 요구되는 구조부재에 써요.","요구 내화시간과 부재 조건에 따라 도막 두께와 시공 사양이 달라져요."]},{"kind":"compare","head":"그림: 철골에 칠하는 층 (안쪽부터)","cols":["순서","층","칠하는 것"],"rows":[["1","철골","표면처리"],["2","**하도**","방청도료"],["3","**중도**","내화도료"],["4","**상도**","마감도료"]]},{"kind":"points","head":"공사 순서에서의 자리","items":["철골 표면처리 → 녹을 막는 **방청도료(rust resisting paint)** → **내화도료(fire-proof paint)** → 마감도료 순서예요.","p9 의 세 층(**하도**, **중도**, **상도**)이 여기서도 그대로 쓰여요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"기출 모양 연습문제","q":"내화도료를 칠한 철골의 층을 철골에서 바깥쪽 순서로 쓰시오.","qko":"슬라이드 층 그림의 네 칸을 안쪽부터 읽는 문제예요.","solve":["맨 안쪽은 철골이에요. 표면처리를 먼저 해요.","**하도**에는 녹을 막는 방청도료를 칠해요.","**중도**가 바로 내화도료예요.","**상도**는 마감도료예요."],"answer":"철골(표면처리) → 하도(방청도료) → 중도(내화도료) → 상도(마감도료)"},{"kind":"check","q":"**내화도료(fire-proof paint)**가 화재 시 구조물을 보호하는 원리로 옳은 것은?","choices":["도막이 발포, 팽창해 다공성 단열 탄화층을 만든다","도막이 녹아 흘러내려 불을 끈다","해양생물의 부착을 막는다","가연성 재료의 착화를 촉진한다"],"a":0,"why":"탄화층이 열이 철재에 전달되는 것을 지연시켜요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["그림 라벨 '하도(방청도료)' 는 해상도가 낮아 '빙청' 처럼 보이지만 방청도료예요.","**내화도료(fire-proof paint)**는 철골(구조재)용, 다음 쪽 **방염도료(fire resisting paint)**는 합판, 목재(가연성 재료)용이에요.","도막 두께는 요구 내화시간과 부재 조건에 따라 달라져요. 정해진 숫자는 슬라이드에 없어요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.135,0.1915],"c":[0,0.0208,0.2,0.2235],"r":1.5909,"img":"img/L5/walk/p012_h.jpg"},"parts":[{"b":[0.02,0.235,0.8,0.175],"c":[0,0.219,0.88,0.207],"r":7.5577,"img":"img/L5/walk/p012_24_01.jpg","say":"(2) 내화도료 세 줄: 온도 상승 지연, 발포와 팽창으로 단열 탄화층, 철골 기둥과 보."},{"b":[0.015,0.48,0.335,0.285],"c":[0,0.464,0.3685,0.317],"r":2.0666,"img":"img/L5/walk/p012_24_02.jpg","say":"층 그림: 철골(표면처리), 하도(방청도료), 중도(내화도료), 상도(마감도료)."},{"b":[0.365,0.445,0.27,0.42],"c":[0.3515,0.424,0.297,0.462],"r":1.1429,"img":"img/L5/walk/p012_24_03.jpg","say":"사진: 철골 보에 내화도료를 뿜어 칠하는 모습."},{"b":[0.64,0.445,0.35,0.45],"c":[0.615,0.4225,0.385,0.495],"r":1.3827,"img":"img/L5/walk/p012_24_04.jpg","say":"사진: 고온 노출 전과 후. 오른쪽 기둥의 도막이 하얗게 부풀었어요."}]}},{"p":13,"title":"기능성 도료 (3) 방염도료와 방염성능기준","terms":["fire resisting paint","잔염시간","잔신시간","탄화면적","fire-proof paint"],"pass1":[{"kind":"say","lines":["**방염도료(fire resisting paint)**는 나무나 합판이 불에 잘 안 붙게 하는 페인트예요.","불이 붙더라도 불길이 천천히 번지게 해요."]},{"kind":"compare","head":"불과 관련된 두 도료","cols":["","**내화도료(fire-proof paint)**","**방염도료(fire resisting paint)**"],"rows":[["칠하는 곳","철골 기둥, 보","합판, 목재"],["하는 일","철골 온도가 늦게 오르게","불붙음과 불길 번짐을 늦춤"]]}],"pass2":[{"kind":"points","head":"(3) **방염도료(fire resisting paint)**의 정체","items":["합판, 목재 등 가연성 재료에 칠해 화재 때 착화와 화염의 확산을 지연시키는 기능성 도료예요.","가연성은 불에 잘 타는 성질, 착화는 불이 붙는 것이에요.","재료의 연소를 억제해 불길이 빠르게 번지는 것을 줄여요.","제품에 따라 투명 또는 유색, 수성 또는 용제형이 있어요."]},{"kind":"points","head":"법 기준","items":["방염대상물품은 「소방시설 설치 및 관리에 관한 법률」 및 같은 법 시행령의 방염성능기준에 맞아야 해요.","그 기준 숫자가 왼쪽 아래 상자에 있어요."]},{"kind":"compare","head":"*참고: 합판, 섬유판, 목재 등의 방염성능기준","cols":["항목","기준","뜻"],"rows":[["**잔염시간**","10초 이내","버너 불꽃을 제거한 뒤에도 불꽃을 내며 계속 타는 시간"],["**잔신시간**","30초 이내","불꽃은 없지만 붉게 타거나 연소가 계속되는 시간"],["**탄화면적**","50㎠ 이내","시험 후 불에 타서 탄화된 면적"],["탄화길이","20cm 이내","탄화된 부분의 최대 길이"]]},{"kind":"points","head":"사진에서 볼 것","items":["오른쪽 가운데: 방염 도료 미처리 나무판은 크게 그을렸어요.","오른쪽 아래: 발포 타입과 비발포 타입은 그을린 자리가 훨씬 작아요.","가운데는 방염도료 제품 통, 오른쪽 위는 불에 그을린 나무판 시험 사진이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"기출 모양 연습문제","q":"합판, 섬유판, 목재 등을 대상으로 한 방염성능기준 4가지를 수치와 함께 쓰시오.","qko":"방염 시험에서 통과해야 하는 숫자 네 개를 쓰는 문제예요.","solve":["불꽃이 남아 타는 시간: **잔염시간** 10초 이내.","불꽃 없이 붉게 타는 시간: **잔신시간** 30초 이내.","타서 숯이 된 넓이: **탄화면적** 50㎠ 이내.","타서 숯이 된 최대 길이: 탄화길이 20cm 이내."],"answer":"잔염시간 10초 이내, 잔신시간 30초 이내, 탄화면적 50㎠ 이내, 탄화길이 20cm 이내"},{"kind":"check","q":"방염성능기준에서 '불꽃은 없지만 붉게 타거나 연소가 계속되는 시간' 의 기준은?","choices":["10초 이내","20초 이내","30초 이내","50초 이내"],"a":2,"why":"**잔신시간** 30초 이내예요. 불꽃을 내며 타는 **잔염시간**은 10초 이내예요."},{"kind":"english","head":"서술 답안: 방염도료의 정의","en":"방염도료는 합판, 목재 등 가연성 재료에 도장하여 화재 발생 시 착화와 화염의 확산을 지연시키는 기능성 도료이다.","ko":"어디에(가연성 재료), 무엇을(착화와 화염 확산), 어떻게(지연) 세 칸으로 적어요.","tip":"숫자는 10초, 30초, 50, 20 순서로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["잔염(불꽃 염)은 10초, 잔신은 30초. 둘을 바꾸면 틀려요.","탄화면적은 ㎠(넓이), 탄화길이는 cm(길이). 단위도 같이 외워요.","'잔신시간' 은 슬라이드 표기예요. 다른 자료에서는 흔히 '잔진시간' 으로 써요(슬라이드 밖 내용). 시험에는 슬라이드 표기대로 나올 수 있어요."]}],"walk":{"head":null,"parts":[{"b":[0.02,0.235,0.62,0.22],"c":[0,0.219,0.682,0.252],"r":4.8113,"img":"img/L5/walk/p013_24_01.jpg","say":"(3) 방염도료 네 줄: 가연성 재료, 착화와 확산 지연, 종류, 소방 관련 법률."},{"b":[0.03,0.495,0.3,0.455],"c":[0.015,0.4723,0.33,0.5005],"r":1.1722,"img":"img/L5/walk/p013_24_02.jpg","say":"*참고 상자: 잔염 10초, 잔신 30초, 탄화면적 50㎠, 탄화길이 20cm, 모두 이내."},{"b":[0.36,0.47,0.25,0.445],"c":[0.3475,0.4477,0.275,0.4895],"r":0.9988,"img":"img/L5/walk/p013_24_03.jpg","say":"사진: 방염도료 제품 통."},{"b":[0.65,0.045,0.31,0.36],"c":[0.6345,0.027,0.341,0.396],"r":1.5309,"img":"img/L5/walk/p013_24_04.jpg","say":"사진: 불에 그을린 나무판 시험 모습."},{"b":[0.648,0.43,0.152,0.24],"c":[0.624,0.414,0.2,0.272],"r":1.3072,"img":"img/L5/walk/p013_24_05.jpg","say":"방염 도료 미처리: 크게 탔어요."},{"b":[0.648,0.685,0.31,0.27],"c":[0.6325,0.669,0.341,0.302],"r":2.0074,"img":"img/L5/walk/p013_24_06.jpg","say":"발포 타입, 비발포 타입: 그을린 자리가 작아요."}]}},{"p":14,"title":"기능성 도료 (4) 방청도료: 광명단, 징크 프라이머, 속건 방청 프라이머","terms":["rust resisting paint","red lead","Zinc Primer","속건 방청 프라이머","하도","방청안료"],"pass1":[{"kind":"say","lines":["**방청도료(rust resisting paint)**는 쇠에 녹이 슬지 않게 맨 먼저 바르는 칠이에요.","녹은 쇠가 물과 산소를 만나서 생겨요. 그 만남을 막는 막이에요."]},{"kind":"compare","head":"녹 막는 칠 세 가지","cols":["이름","한 줄 별명"],"rows":[["**광명단(red lead)**","전통적인 주황빛 녹 방지 칠"],["**징크 프라이머(Zinc Primer)**","아연이 든 녹 방지 밑칠"],["**속건 방청 프라이머**","빨리 마르는 녹 방지 밑칠"]]}],"pass2":[{"kind":"points","head":"(4) **방청도료(rust resisting paint)**의 정체와 자리","items":["철재 표면에 칠해 수분과 산소의 접촉을 줄이고 금속의 부식을 억제하는 하도용 도료예요.","쓰는 곳: 철골, 철문, 난간, 금속 프레임 등.","칠하기 전에 녹, 기름, 먼지 등을 제거하고 바탕면을 정리해야 해요.","순서: 바탕 정리 → **방청도료(rust resisting paint)**(**하도**) → 그 위에 중도, 상도."]},{"kind":"points","head":"① **광명단(red lead)** 방청도료","items":["광명단은 전통적으로 사산화삼납(Pb₃O₄, red lead)을 뜻해요.","철재 부식을 막는 **방청안료**로 써 왔어요.","광명단계 방청페인트는 주로 철재의 하도용이에요. 현장에서 '광명단 칠', '광명단 도장' 이라고 불러요.","색: 일반적으로 적갈색 또는 오렌지 계열 제품이 많아요."]},{"kind":"points","head":"② **징크 프라이머(Zinc Primer)**, ③ **속건 방청 프라이머**","items":["② 아연을 함유한 방청 프라이머예요. 철재 부식을 억제하는 하도용 도료예요.","아연 함량이 높은 징크리치 프라이머는 희생방식 작용으로 부식 방지 성능을 높여요. 철재와 아연도금 부위 보수에 써요.","③ 건조 시간을 단축해 다음 칠을 빨리 할 수 있게 만든 방청 하도예요.","재도장 가능 시간은 제품마다 달라서 제조사의 시방을 따라요."]},{"kind":"bg","src":"배경 지식","lines":["희생방식은 아연이 철보다 먼저 녹슬면서 철을 대신 지켜 주는 원리예요.","아연이 철 대신 희생한다고 해서 붙은 이름이에요. (슬라이드 밖 설명)"]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"5강 문제풀이 (p52)","q":"철재에 도장할 때에는 바탕에 (①광명단, ②내알칼리 페인트)을(를) 도포한다.","qko":"쇠 위에 맨 먼저 무엇을 바르는지 고르는 문제예요.","solve":["철재 바탕에는 녹을 막는 방청 하도가 필요해요.","이 쪽의 **광명단(red lead)**이 철재의 하도용 방청도료예요.","내알칼리 페인트는 콘크리트, 시멘트, 모르타르처럼 알칼리성 바탕용이에요(p52 설명)."],"answer":"① 광명단"},{"kind":"check","q":"**광명단(red lead)**이 전통적으로 의미하는 물질은?","choices":["사산화삼납(Pb₃O₄)","아연","실리콘수지","알키드수지"],"a":0,"why":"아연은 징크 프라이머, 실리콘수지는 내열도료, 알키드수지는 유성 페인트 쪽이에요."},{"kind":"check","q":"아연 함량이 높아 철재에 희생방식 작용을 하는 프라이머는?","choices":["징크리치 프라이머","**속건 방청 프라이머**","**광명단(red lead)**","**실러(sealer)**"],"a":0,"why":"**징크 프라이머(Zinc Primer)** 가운데 아연 함량이 높은 것이 징크리치 프라이머예요."},{"kind":"english","head":"서술 답안: 방청도료의 정의와 종류","en":"방청도료는 철재 표면에 도장하여 수분과 산소의 접촉을 줄이고 금속의 부식을 억제하는 하도용 도료로, 광명단 방청도료, 징크 프라이머, 속건 방청 프라이머가 있다.","ko":"정의 한 줄 + 종류 셋을 붙여 적어요.","tip":"광, 징, 속."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**방청도료(rust resisting paint)**는 상도가 아니라 **하도**용이에요.","방청(녹), 방염(불), 방오(해양생물)를 헷갈리지 마세요.","칠하기 전에 녹, 기름, 먼지를 먼저 없애요. 녹 위에 바로 칠한다고 하면 틀려요."]}],"walk":{"head":null,"parts":[{"b":[0.02,0.235,0.56,0.13],"c":[0,0.219,0.616,0.162],"r":6.7599,"img":"img/L5/walk/p014_24_01.jpg","say":"(4) 방청도료 두 줄: 수분과 산소 차단, 하도용, 칠 전 녹, 기름, 먼지 제거."},{"b":[0.02,0.375,0.65,0.175],"c":[0,0.359,0.715,0.207],"r":6.1406,"img":"img/L5/walk/p014_24_02.jpg","say":"① 광명단: 사산화삼납(Pb₃O₄, red lead), 광명단 칠, 적갈색 또는 오렌지 계열."},{"b":[0.02,0.555,0.7,0.13],"c":[0,0.539,0.77,0.162],"r":8.4499,"img":"img/L5/walk/p014_24_03.jpg","say":"② 징크 프라이머: 아연 함유, 징크리치는 희생방식 작용."},{"b":[0.02,0.7,0.45,0.125],"c":[0,0.684,0.495,0.157],"r":5.6051,"img":"img/L5/walk/p014_24_04.jpg","say":"③ 속건 방청 프라이머: 건조 시간 단축, 제조사 시방."},{"b":[0.745,0.03,0.22,0.53],"c":[0.733,0.0035,0.244,0.583],"r":0.744,"img":"img/L5/walk/p014_24_05.jpg","say":"사진: 철재에 롤러로 바르는 광명단과 주황빛 광명단 통."},{"b":[0.765,0.59,0.155,0.4],"c":[0.7425,0.56,0.2,0.44],"r":0.8081,"img":"img/L5/walk/p014_24_06.jpg","say":"사진: 스프레이형 징크 프라이머."}]}},{"p":15,"title":"기능성 도료 (5) 다채무늬 도료","terms":["multi color paint","하도","상도"],"pass1":[{"kind":"say","lines":["**다채무늬 도료(multi color paint)**는 여러 색 알갱이가 섞여 있는 페인트예요.","한 번 뿌리면 점박이 무늬가 저절로 생겨요."]},{"kind":"analogy","head":"초코칩 반죽","scene":"반죽에 여러 색 초콜릿 칩이 섞여 있으면 한 번 구워도 점박이 쿠키가 되죠.","map":[["반죽","도료"],["색색의 칩","서로 다른 색상의 입자나 플레이크"],["점박이 쿠키","여러 색이 섞인 장식 무늬"]]}],"pass2":[{"kind":"points","head":"(5) **다채무늬 도료(multi color paint)**의 정체","items":["서로 다른 색상의 입자나 플레이크가 도료 속에 섞여 있어요.","한 번의 시공으로 여러 색이 섞인 장식적인 무늬를 표현해요.","수성 제품은 물을 희석제로 써서 용제형보다 냄새와 화재 위험이 적고 작업성이 비교적 좋아요."]},{"kind":"points","head":"칠하는 방법","items":["**하도**는 붓이나 롤러 등으로 칠할 수 있어요.","무늬를 균일하게 내기 위해 **상도**는 주로 스프레이 방식으로 칠해요.","기계로 섞으면 입자가 부서지기 때문에 손으로 저어서 섞어요."]},{"kind":"steps","head":"시공 사진 순서","steps":["표면 정리","보양 작업 (주변을 덮어 보호)","뿜칠 작업 (스프레이로 뿌리기)","건조 후 코팅 작업"],"answer":"표면 정리 → 보양 → 뿜칠 → 건조 후 코팅"},{"kind":"points","head":"쓰는 곳과 효과","items":["주로 아파트 공용 복도 부분에 시공해요.","밝은 분위기는 유지하면서 오염이 잘 보이지 않는 효과가 있어요.","아래 BEFORE, AFTER 사진이 시공 전과 후의 복도 천장이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**다채무늬 도료(multi color paint)**를 기계가 아닌 손으로 저어서 섞는 이유는?","choices":["기계로 섞으면 입자가 부서지기 때문","기계로 섞으면 냄새가 나기 때문","손으로 섞어야 빨리 마르기 때문","기계로 섞으면 광택이 사라지기 때문"],"a":0,"why":"슬라이드 아래 셋째 줄 그대로예요."},{"kind":"check","q":"**다채무늬 도료(multi color paint)**의 상도를 주로 시공하는 방식은?","choices":["붓","롤러","스프레이","주걱"],"a":2,"why":"무늬를 균일하게 내려고 상도는 주로 스프레이로 해요. 하도는 붓이나 롤러예요."},{"kind":"exam","src":"기출 모양 연습문제","q":"다채무늬 도료의 시공 순서를 슬라이드 사진 순서대로 쓰시오.","qko":"사진 네 장 아래 캡션을 순서대로 쓰는 문제예요.","solve":["먼저 칠할 면을 정리해요: 표면 정리.","칠이 튀지 않게 주변을 덮어요: 보양 작업.","스프레이로 무늬 도료를 뿌려요: 뿜칠 작업.","마른 뒤 위에 코팅해요: 건조 후 코팅 작업."],"answer":"표면 정리 → 보양 작업 → 뿜칠 작업 → 건조 후 코팅 작업"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["하도는 붓이나 롤러, 상도는 스프레이예요. 반대로 쓰면 틀려요.","주로 시공하는 곳은 아파트 공용 복도예요. 오염이 잘 안 보이는 것이 장점이에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.0968,0.0362],"c":[0,0.0208,0.2,0.0682],"r":5.2134,"img":"img/L5/walk/p015_h.jpg"},"parts":[{"b":[0.02,0.235,0.7,0.175],"c":[0,0.219,0.77,0.207],"r":6.613,"img":"img/L5/walk/p015_24_01.jpg","say":"(5) 다채 무늬 도료 세 줄: 여러 색 입자, 하도는 붓이나 롤러와 상도는 스프레이, 수성 제품의 장점."},{"b":[0.705,0.075,0.285,0.28],"c":[0.6865,0.059,0.3135,0.312],"r":1.7863,"img":"img/L5/walk/p015_24_02.jpg","say":"사진: 계단실 벽과 점박이 무늬 확대."},{"b":[0.06,0.42,0.81,0.29],"c":[0.0195,0.404,0.891,0.322],"r":4.9193,"img":"img/L5/walk/p015_24_03.jpg","say":"시공 사진 네 단계: 표면 정리, 보양 작업, 뿜칠 작업, 건조 후 코팅 작업."},{"b":[0.06,0.71,0.385,0.255],"c":[0.0408,0.694,0.4235,0.287],"r":2.6233,"img":"img/L5/walk/p015_24_04.jpg","say":"BEFORE, AFTER: 시공 전 흰 천장과 시공 후 무늬 천장."},{"b":[0.46,0.775,0.32,0.13],"c":[0.444,0.759,0.352,0.162],"r":3.8628,"img":"img/L5/walk/p015_24_05.jpg","say":"아래 세 줄: 아파트 공용 복도, 오염이 잘 안 보임, 손으로 저어 섞음."}]}},{"p":16,"title":"기능성 도료 (6) 입체 무늬 도료, 본타일","terms":["본타일","하도","상도","multi color paint"],"pass1":[{"kind":"say","lines":["**본타일**은 벽에 오돌토돌한 입체 무늬를 만드는 페인트예요.","스프레이로 뿌려서 울퉁불퉁한 질감을 내요."]},{"kind":"compare","head":"무늬 도료 두 가지","cols":["이름","무늬"],"rows":[["**다채무늬 도료(multi color paint)**","여러 색이 섞인 점박이 무늬"],["**본타일**","요철이 있는 입체 무늬"]]}],"pass2":[{"kind":"points","head":"(6) 입체 무늬 도료 **본타일**의 정체","items":["콘크리트, 모르타르 등의 벽면에 스프레이 방식으로 요철이 있는 입체적인 무늬를 만드는 장식용 도료예요.","무늬의 크기와 형태를 조절할 수 있고 다양한 색상 표현이 가능해요.","제품에 따라 내수성, 내알칼리성, 내후성, 내구성 등을 가져요."]},{"kind":"steps","head":"**본타일** 시공 순서","steps":["**하도** (프라이머)","무늬형성도료","**상도** (아크릴계 등의 도료)"],"answer":"하도(프라이머) → 무늬형성도료 → 상도"},{"kind":"points","head":"사진에서 볼 것","items":["두 사진 모두 벽 표면에 잔잔한 요철이 보여요.","캡션: 건물 내부 벽체에 주로 시공."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"기출 모양 연습문제","q":"본타일의 일반적인 시공 순서를 쓰시오.","qko":"입체 무늬 도료를 세 층으로 올리는 순서를 묻는 문제예요.","solve":["맨 아래 **하도**: 프라이머.","가운데: 무늬를 만드는 무늬형성도료.","맨 위 **상도**: 아크릴계 등의 도료."],"answer":"하도(프라이머) → 무늬형성도료 → 상도"},{"kind":"check","q":"**본타일**에 대한 설명으로 옳지 않은 것은?","choices":["스프레이 방식으로 입체 무늬를 만든다","무늬의 크기와 형태를 조절할 수 있다","상도에는 주로 광명단을 쓴다","건물 내부 벽체에 주로 시공한다"],"a":2,"why":"상도에는 아크릴계 등의 도료를 써요. 광명단은 철재의 방청 하도예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["본타일의 가운데 층은 '무늬형성도료' 예요. 하도, 중도, 상도 세 층 구조는 p9 와 같아요.","본타일도 스프레이 방식이에요. 붓으로 무늬를 낸다고 하면 틀려요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1667,0.2312],"c":[0,0.0208,0.2,0.2632],"r":1.3509,"img":"img/L5/walk/p016_h.jpg"},"parts":[{"b":[0.02,0.27,0.6,0.045],"c":[0,0.2258,0.66,0.1333],"r":8.8022,"img":"img/L5/walk/p016_23_01.jpg","say":"첫 줄: 스프레이 방식으로 요철이 있는 입체 무늬를 만드는 장식용 도료."},{"b":[0.02,0.32,0.6,0.045],"c":[0,0.2758,0.66,0.1333],"r":8.8022,"img":"img/L5/walk/p016_23_02.jpg","say":"둘째 줄: 하도(프라이머) → 무늬형성도료 → 상도, 상도는 아크릴계 등."},{"b":[0.02,0.365,0.66,0.045],"c":[0,0.3142,0.726,0.1467],"r":8.798,"img":"img/L5/walk/p016_23_03.jpg","say":"셋째 줄: 무늬 크기, 형태 조절, 내수성, 내알칼리성, 내후성, 내구성."},{"b":[0.17,0.43,0.635,0.52],"c":[0.1383,0.404,0.6985,0.572],"r":2.1709,"img":"img/L5/walk/p016_23_04.jpg","say":"사진: 본타일을 칠한 벽 표면. 건물 내부 벽체에 주로 시공."}]}},{"p":17,"title":"기능성 도료 (7) 결로 방지 도료, 탄성코트와 바이오 세라믹 코트","terms":["결로 방지 도료","탄성코트","바이오 세라믹 코트"],"pass1":[{"kind":"say","lines":["**결로 방지 도료**는 벽과 천장에 물방울이 맺히는 것을 줄이는 페인트예요.","결로는 차가운 컵 겉에 물방울이 맺히는 것과 같은 현상이에요."]},{"kind":"analogy","head":"고무 막과 숨 쉬는 옷","scene":"**탄성코트**는 벽에 늘어나는 고무 막을 씌운 것, **바이오 세라믹 코트**는 작은 숨구멍이 많은 옷과 같아요.","map":[["고무 막","**탄성코트**: 늘어나서 금에 강함, 대신 습기가 갇힐 수 있음"],["숨 쉬는 옷","**바이오 세라믹 코트**: 수증기가 빠져나감"]]}],"pass2":[{"kind":"points","head":"(7) **결로 방지 도료**의 정체","items":["실내외 온도 차이로 벽, 천장 표면에 생기는 결로를 줄이는 기능성 도료예요.","단열성, 흡습성 같은 기능으로 표면 결로를 완화해요. 제품에 따라 항균, 항곰팡이 기능도 있어요.","쓰는 곳: 아파트, 지하공간, 욕실 주변처럼 결로와 곰팡이가 생기기 쉬운 벽, 천장."]},{"kind":"compare","head":"*참고: **탄성코트** VS **바이오 세라믹 코트**","cols":["","탄성코트","바이오 세라믹 코트"],"rows":[["재료","탄성수지 등으로 도막에 신축성 부여","세라믹, 광물질 등 미세 입자 함유"],["장점","미세 균열 대응성, 표면 보호 성능 우수","다공성 구조로 수분, 습기 조절. 수증기가 통과해 바탕 수분 배출을 도움"],["쓰는 곳, 기능","베란다, 발코니 콘크리트 벽. 제품에 따라 결로, 곰팡이 완화","제품에 따라 항균, 항곰팡이, 결로 완화"],["주의, 최근","바탕에 수분이 많거나 못 빠져나가면 부풀음, 박리, 터짐 하자","규조토 등 다공성 광물질로 흡, 방습을 강화한 제품"]]},{"kind":"points","head":"사진에서 볼 것","items":["오른쪽 위: **탄성코트** 하자 사진. 도막이 부풀고 들뜬 모습이에요.","오른쪽 아래: **바이오 세라믹 코트** 표면. 작은 알갱이가 박힌 질감이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**탄성코트**에서 부풀음, 박리, 터짐 하자가 생기는 원인은?","choices":["바탕면 수분이 많거나 외부로 빠져나가지 못할 때","도료를 손으로 저어 섞었을 때","수증기가 너무 잘 통과할 때","광명단을 하도로 칠했을 때"],"a":0,"why":"수분이 도막 안에 차면서 하자가 생겨요."},{"kind":"check","q":"다공성 구조로 수증기가 통과해 바탕면의 수분 배출을 돕는 도료는?","choices":["**바이오 세라믹 코트**","**탄성코트**","**유성 페인트(oil-based paint)**","**바니쉬(varnish)**"],"a":0,"why":"규조토 같은 다공성 광물질로 흡, 방습을 강화한 제품도 있어요."},{"kind":"english","head":"서술 답안: 탄성코트와 바이오 세라믹 코트 비교","en":"탄성코트는 도막에 신축성을 부여하여 미세 균열에 강하지만 수분이 빠져나가지 못하면 부풀음, 박리, 터짐이 생기고, 바이오 세라믹 코트는 다공성 구조로 수증기가 통과하여 바탕면의 수분 배출을 돕는다.","ko":"장점 하나, 약점 하나씩 짝으로 적어요.","tip":"탄성 = 늘어남, 갇힘. 바이오 세라믹 = 구멍, 통과."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["균열에 강한 것은 탄성코트, 수분 배출을 돕는 것은 바이오 세라믹 코트예요.","규조토는 바이오 세라믹 코트 쪽 재료예요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.135,0.1915],"c":[0,0.0208,0.2,0.2235],"r":1.5909,"img":"img/L5/walk/p017_h.jpg"},"parts":[{"b":[0.02,0.235,0.46,0.22],"c":[0,0.219,0.506,0.252],"r":3.5697,"img":"img/L5/walk/p017_23_01.jpg","say":"(7) 결로 방지 도료 세 줄: 정의, 단열성과 흡습성, 아파트와 지하공간과 욕실."},{"b":[0.03,0.545,0.57,0.16],"c":[0.0015,0.529,0.627,0.192],"r":5.8056,"img":"img/L5/walk/p017_23_02.jpg","say":"[탄성코트] 세 줄: 신축성, 베란다와 발코니, 수분이 갇히면 부풀음, 박리, 터짐."},{"b":[0.03,0.725,0.52,0.2],"c":[0.004,0.709,0.572,0.232],"r":4.3831,"img":"img/L5/walk/p017_23_03.jpg","say":"[바이오 세라믹 코트] 세 줄: 다공성, 수증기 통과, 규조토."},{"b":[0.615,0.325,0.365,0.265],"c":[0.5968,0.309,0.4015,0.297],"r":2.4033,"img":"img/L5/walk/p017_23_04.jpg","say":"사진: 탄성코트 하자. 천장과 벽의 도막이 부풀었어요."},{"b":[0.615,0.625,0.365,0.32],"c":[0.5968,0.609,0.4015,0.352],"r":2.0278,"img":"img/L5/walk/p017_23_05.jpg","say":"사진: 바이오 세라믹 코트 표면."}]}},{"p":18,"title":"도장의 조건 1) 페인트 보관 및 장소","terms":["도료","도장공사"],"pass1":[{"kind":"say","lines":["여기부터 6.2.2 도장의 조건이에요. 첫 번째는 페인트를 어디에 어떻게 두느냐예요.","페인트 창고는 특히 화재에 주의해야 해요. 그래서 불을 조심하는 규칙이 대부분이에요."]}],"pass2":[{"kind":"points","head":"1) 페인트 보관 및 장소 (앞 다섯 가지)","items":["페인트는 방화구조 또는 불연 구조로 한 전용 창고에 보관해요.","창고 출입문에는 잠금장치를 설치해요.","창고 안과 주변에 화기엄금 표시를 해요.","사용했던 페인트는 밀봉해서 새거나 엎지르지 않게 해요.","페인트 묻은 헝겊은 창고 안에 두지 말고 비닐봉지 등으로 밀봉해 처리해요."]},{"kind":"points","head":"1) 페인트 보관 및 장소 (뒤 네 가지)","items":["창고 내 환기를 충분히 하고 직사광선을 피해요.","소화기 및 소화용 모래를 비치해요.","**도료**는 오래 두거나 조건이 나쁘면 변질돼요. 제조사가 정한 보관조건과 유효기간을 확인해요.","유효기간이 지난 제품은 임의로 쓰지 않고 제조사 확인을 거쳐요."]},{"kind":"points","head":"공사 순서에서의 자리","items":["**도장공사**에 들어가기 전, 재료를 현장에 들여와 두는 단계의 규칙이에요.","다음 쪽부터는 습도, 바람과 비, 화학적 환경, 온도 같은 칠하는 조건이 이어져요."]},{"kind":"points","head":"사진에서 볼 것","items":["노루페인트 공장 사진 세 장이에요.","위: 출입제한, 촬영금지, 사내금연 표지판. 가운데: 뚜껑을 닫은 도료 드럼통. 아래: 드럼통 옆 소화기."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"페인트 보관 방법으로 옳지 않은 것은?","choices":["방화구조 또는 불연구조의 전용 창고에 보관한다","페인트가 묻은 헝겊은 창고 안에 모아 둔다","소화기 및 소화용 모래를 비치한다","창고 내 환기를 충분히 하고 직사광선을 피한다"],"a":1,"why":"헝겊은 창고 안에 두면 안 되고 비닐봉지 등으로 밀봉해 처리해요."},{"kind":"check","q":"유효기간이 지난 도료의 처리로 옳은 것은?","choices":["임의로 사용하지 않고 제조사의 확인을 거친다","신너로 묽혀 사용한다","바로 사용한다","하도에만 사용한다"],"a":0,"why":"슬라이드 마지막 줄 그대로예요."},{"kind":"english","head":"서술 답안: 페인트 보관 수칙","en":"페인트는 방화구조 또는 불연구조의 전용 창고에 보관하고, 출입문에 잠금장치를 설치하며, 화기엄금 표시, 충분한 환기와 직사광선 차단, 소화기와 소화용 모래 비치를 하고, 페인트 묻은 헝겊은 비닐봉지로 밀봉하여 처리한다.","ko":"창고, 문, 표시, 환기, 소화, 헝겊 순서로 하나씩 늘어놓아요.","tip":"창고, 자물쇠, 화기엄금, 밀봉, 헝겊, 환기, 소화기, 유효기간."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["헝겊은 창고 '안' 에 두지 않아요. 비닐봉지에 밀봉해 따로 처리해요.","슬라이드의 '밀봉하여 세거나 엎지르지' 는 '새거나' 의 오타로 보여요.","직사광선은 피하고 환기는 충분히. 둘 다 한 줄에 같이 나와요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.0968,0.0412],"c":[0,0.0208,0.2,0.0732],"r":4.8573,"img":"img/L5/walk/p018_h.jpg"},"parts":[{"b":[0.02,0.235,0.42,0.135],"c":[0,0.219,0.462,0.167],"r":4.9182,"img":"img/L5/walk/p018_24_01.jpg","say":"첫 세 줄: 방화구조 또는 불연구조 전용 창고, 잠금장치, 화기엄금 표시."},{"b":[0.02,0.375,0.52,0.09],"c":[0,0.359,0.572,0.122],"r":8.3352,"img":"img/L5/walk/p018_24_02.jpg","say":"넷째, 다섯째 줄: 쓰던 페인트 밀봉, 헝겊은 창고 밖에서 비닐봉지로 밀봉."},{"b":[0.02,0.465,0.31,0.09],"c":[0.0045,0.449,0.341,0.122],"r":4.969,"img":"img/L5/walk/p018_24_03.jpg","say":"여섯째, 일곱째 줄: 환기와 직사광선 차단, 소화기와 소화용 모래."},{"b":[0.02,0.56,0.68,0.09],"c":[0,0.5294,0.748,0.1511],"r":8.8006,"img":"img/L5/walk/p018_24_04.jpg","say":"마지막 두 줄: 보관조건과 유효기간 확인, 지난 제품은 제조사 확인."},{"b":[0.735,0.08,0.23,0.86],"c":[0.6321,0.037,0.3679,0.946],"r":0.6914,"img":"img/L5/walk/p018_24_05.jpg","say":"사진: 노루페인트 공장의 표지판, 드럼통, 소화기."}]}},{"p":19,"title":"도장의 조건 2~5: 습도, 바람과 비, 화학적 환경, 온도","terms":["도장공사","도료","도막","water-based paint","dry spray","solvent"],"pass1":[{"kind":"say","lines":["앞 쪽의 페인트 보관에 이어, 이번 쪽은 칠하는 날의 날씨와 환경 이야기예요.","**도장공사**는 화장과 같아요. 땀이 줄줄 나는 날엔 화장이 잘 안 먹죠.","너무 습하거나, 바람이 세거나, 비가 오거나, 벽이 더러우면 칠이 망가져요."]},{"kind":"points","head":"칠을 망치는 네 가지 환경","items":["습도: 너무 습하면 잘 안 말라요.","바람과 비, 눈: 바람은 너무 빨리 말리고, 비와 눈은 물을 남겨요.","화학적 환경: 바탕이 더러우면 먼저 씻어요.","온도: 제품이 정한 범위 안에서만 칠해요."]}],"pass2":[{"kind":"points","head":"2) 습도: 너무 높으면 안 말라요","items":["습도가 너무 높으면 **도료**의 건조가 늦어지거나 **도막**에 수분이 응축돼요.","그 결과 백화, 광택 저하, 부착력 저하 같은 결함이 생길 수 있어요.","특히 **수성 페인트(water-based paint)** 같은 수성도료는 물이 늦게 날아가 건조시간이 길어져요.","**도막**은 **도료**가 마르면서 표면에 생기는 얇은 막이에요."]},{"kind":"points","head":"3) 바람 및 강우, 강설","items":["옥외 도장 때 바람이 세면 **도료**가 지나치게 빨리 마르거나 먼지, 이물질이 **도막**에 붙어요.","그래서 도막 불균일, 오염, **건조분무(dry spray)** 같은 문제가 생길 수 있어요.","**건조분무(dry spray)**는 도료 입자가 칠할 면에 닿기 전에 말라 거칠게 마감되는 현상이에요.","비, 눈, 진눈깨비가 오면 바탕면과 도막에 수분이 남아 부착력 저하, 박리, 얼룩, 도막 성능 저하가 생겨요. 그래서 도장하지 않아요."]},{"kind":"compare","head":"4) 화학적 환경과 5) 온도","cols":["상황","슬라이드 내용"],"rows":[["화학물질, 염분, 기름, 먼지로 오염된 환경","도장 전 바탕면의 오염물을 충분히 제거해야 해요"],["도장면이 오염된 경우","물이나 적절한 **용제(solvent)**로 세척 → 완전히 건조 → 도장"],["기온이나 바탕면 온도가 너무 낮거나 높음","건조, 경화와 부착성에 영향 → 제품에서 정한 적정 시공온도 범위에서 도장"]]},{"kind":"bg","src":"배경 지식","lines":["백화는 도막 표면이 하얗게 뿌옇게 변하는 결함을 말해요.","**용제(solvent)**는 원래 도료를 묽게 하는 액체예요. 여기서는 기름때 같은 오염을 씻는 데 써요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"습도가 너무 높을 때 생기는 결함으로 19쪽 습도 항목에 적힌 것이 아닌 것은?","choices":["백화","광택 저하","부착력 저하","**건조분무(dry spray)**"],"a":3,"why":"**건조분무(dry spray)**는 바람이 세서 도료가 너무 빨리 마를 때 생기는 문제로, 3) 바람 항목에 있어요."},{"kind":"check","q":"도장면이 기름 등으로 오염되었을 때 슬라이드의 처리 방법은?","choices":["그 위에 바로 덧칠한다","물이나 적절한 **용제(solvent)**로 세척하고 완전히 건조시킨 뒤 도장한다","퍼티로 덮고 도장한다","젖은 채로 빨리 도장한다"],"a":1,"why":"세척 → 완전히 건조 → 도장 순서예요. 젖은 채로 칠하면 부착력이 떨어져요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["습도가 높으면 늦게 마르고, 바람이 세면 너무 빨리 말라요. 방향이 반대예요.","이 쪽의 온도 항목에는 숫자가 없어요. 숫자는 20쪽(영하), 33쪽(5℃ 이하)에 나와요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.135,0.1435],"c":[0,0.0208,0.2,0.1755],"r":2.026,"img":"img/L5/walk/p019_h.jpg"},"parts":[{"b":[0.021,0.184,0.643,0.136],"c":[0,0.168,0.7073,0.168],"r":7.4847,"img":"img/L5/walk/p019_24_01.jpg","say":"2) 습도: 너무 높으면 건조가 늦고 도막에 수분이 응축돼요. 수성도료는 특히 주의."},{"b":[0.021,0.349,0.814,0.14],"c":[0,0.3285,0.8954,0.1809],"r":8.7995,"img":"img/L5/walk/p019_24_02.jpg","say":"3) 바람 및 강우, 강설: 강풍은 도막 불균일, 오염, 건조분무. 비, 눈엔 도장하지 않아요."},{"b":[0.021,0.518,0.521,0.136],"c":[0,0.502,0.5731,0.168],"r":6.0646,"img":"img/L5/walk/p019_24_03.jpg","say":"4) 화학적 환경: 오염물을 충분히 제거하고, 세척 후 완전히 건조시켜 칠해요."},{"b":[0.021,0.685,0.739,0.091],"c":[0,0.6484,0.8129,0.1642],"r":8.8012,"img":"img/L5/walk/p019_24_04.jpg","say":"5) 온도: 제품에서 정한 적정 시공온도 범위에서 도장. 이 쪽에는 숫자가 없어요."}]}},{"p":20,"title":"칠을 해서는 안 되는 경우 3가지","terms":["도장공사","도료","도막"],"pass1":[{"kind":"say","lines":["19쪽이 날씨가 칠에 주는 영향이었다면, 이 쪽은 '이럴 땐 칠하지 마' 목록이에요.","추울 때, 습할 때, 비바람과 먼지가 많을 때, 옆 작업이 방해할 때예요.","아래 사진들은 칠이 잘못되면 생기는 모습을 보여 줘요."]}],"pass2":[{"kind":"steps","head":"※ 다음과 같은 경우에는 칠을 해서는 안 된다","steps":["1) 칠하는 장소의 기온이 영하 또는 영하에 가깝거나, 습도가 85% 초과하거나, 환기가 충분하지 못해 칠의 건조가 힘들 때","2) 강설우, 강풍, 칠할 장소의 바닥에 먼지 등이 많아서 물방울, 들뜨기, 흙 및 먼지 등이 칠 막에 붙기 쉬운 경우","3) 주위의 다른 작업으로 칠 작업에 지장이 있거나 칠 막이 손상될 우려가 있을 때"],"answer":"날씨와 환기(1) → 비바람과 먼지(2) → 다른 작업(3), 세 묶음이에요."},{"kind":"points","head":"숫자와 낱말","items":["숫자는 하나예요. 습도 **85% 초과**. 이 쪽은 '초과' 라고 적혀 있어요.","기온은 숫자 없이 '영하 또는 영하에 가깝거나' 예요.","강설우는 눈과 비, 강풍은 센 바람이에요.","칠 막 = **도막**. **도료**가 마르며 생긴 얇은 막이에요."]},{"kind":"points","head":"공사 순서에서의 자리","items":["**도장공사**는 현장 순서 '가설 → 철거 → 경량철골 → 마감' 의 마감 자리예요.","이 세 가지는 퍼티, 하도, 중도, 상도 어느 칠을 하든 매번 확인해요.","3)은 같은 현장에서 함께 진행되는 다른 작업 때문에 칠이 상할 수 있다는 뜻이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"기출 모양 연습문제","q":"도장공사에서 칠을 해서는 안 되는 경우 3가지를 쓰시오.","qko":"칠하면 안 되는 날씨와 현장 상황 세 가지를 묻는 목록형 서술이에요.","solve":["첫째 묶음은 날씨와 환기예요. 영하 또는 영하에 가까운 기온, 습도 85% 초과, 환기 부족.","둘째 묶음은 비바람과 먼지예요. 강설우, 강풍, 바닥 먼지로 칠 막에 물방울, 흙, 먼지가 붙기 쉬울 때.","셋째는 주위의 다른 작업으로 칠 작업에 지장이 있거나 칠 막이 손상될 우려가 있을 때예요.","습도는 이 쪽 표기대로 '초과' 로 써요."],"answer":"① 기온이 영하(근처)이거나 습도 85% 초과, 환기 불충분으로 건조가 힘들 때 ② 강설우, 강풍, 바닥 먼지로 칠 막에 물방울, 흙, 먼지가 붙기 쉬울 때 ③ 주위 다른 작업으로 지장이 있거나 칠 막 손상 우려가 있을 때"},{"kind":"check","q":"20쪽에 적힌 '칠을 해서는 안 되는' 습도 기준은?","choices":["75% 초과","80% 이상","85% 초과","90% 이상"],"a":2,"why":"20쪽은 '습도가 85% 초과' 예요. 33쪽과 53쪽은 '85% 이상' 이라 표기가 달라요."},{"kind":"warn","head":"습도 기준이 쪽마다 달라요","items":["20쪽(이 쪽)은 습도 **85% 초과**예요.","33쪽 방청 도장은 '상대습도 85% **이상** 또는 기온 5℃ 이하' 예요. 문제풀이 53쪽 답도 '85% 이상' 이에요.","습도가 딱 85%면, '초과' 기준으로는 칠할 수 있고 '이상' 기준으로는 피해야 해요. 경계가 달라요.","시험에서는 문제에 쓰인 말을 따르고, 이 쪽 내용을 그대로 물으면 '초과' 로 쓰세요."]},{"kind":"english","head":"단답 답안: 칠하면 안 되는 기온과 습도","en":"칠하는 장소의 기온이 영하 또는 영하에 가깝거나 습도가 85%를 초과할 때는 칠을 해서는 안 된다.","ko":"20쪽 표기 그대로 '초과'.","tip":"영하, 85, 초과 세 낱말을 한 문장에 넣으세요."}],"walk":{"head":{"b":[0.0092,0.0368,0.3446,0.2272],"c":[0,0.0208,0.3791,0.2592],"r":2.6001,"img":"img/L5/walk/p020_h.jpg"},"parts":[{"b":[0.079,0.266,0.65,0.178],"c":[0.0465,0.25,0.715,0.21],"r":6.0529,"img":"img/L5/walk/p020_23_01.jpg","say":"※ 칠을 해서는 안 되는 경우 1)~3). 1)에 '습도가 85% 초과' 가 있어요."},{"b":[0.074,0.546,0.274,0.321],"c":[0.0603,0.53,0.3014,0.3531],"r":1.5175,"img":"img/L5/walk/p020_23_02.jpg","say":"사진 1: 모서리 쪽 칠이 들떠 벗겨진 모습으로 보여요."},{"b":[0.354,0.546,0.271,0.321],"c":[0.3404,0.53,0.2981,0.3531],"r":1.5009,"img":"img/L5/walk/p020_23_03.jpg","say":"사진 2: 벽면 칠이 고르지 않고 얼룩진 모습으로 보여요."},{"b":[0.631,0.546,0.293,0.321],"c":[0.6163,0.53,0.3223,0.3531],"r":1.6227,"img":"img/L5/walk/p020_23_04.jpg","say":"사진 3: 칠 막 표면에 물방울처럼 부푼 자국이 생긴 모습으로 보여요."}]}},{"p":21,"title":"도장의 분류: 기준 7가지, 분체도장과 소부건조","terms":["분체도장","소부건조","하도","중도","상도","도료","도막"],"pass1":[{"kind":"say","lines":["같은 칠도 어떤 기준으로 보느냐에 따라 이름이 달라져요.","무슨 도료로, 어떻게, 어디에, 몇 번째 층, 얼마나 반짝, 무슨 용도, 어떻게 말리는지예요.","그중 **분체도장**과 **소부건조** 두 낱말에 슬라이드가 설명을 달아 두었어요."]}],"pass2":[{"kind":"compare","head":"도장의 분류 7가지 기준","cols":["기준","예"],"rows":[["도료의 종류","래커도장, 멜라민도장, 우레탄도장, 에폭시도장 등"],["도장 방법","붓도장, 롤러도장, 분무도장, 정전도장, **분체도장** 등"],["바탕재","목재도장, 금속도장, 미장면도장 등"],["공정","**하도**(프라이머), **중도**, **상도** 도장"],["마감 상태","무광도장, 반광도장, 유광도장 등"],["용도","건축도장, 실내건축도장, 선박도장, 자동차도장 등"],["건조, 경화 방법","자연건조, 강제건조, **소부건조** 등"]]},{"kind":"points","head":"보라색 메모 두 개","items":["**분체도장**: 분말(가루) 상태의 **도료**를 금속 표면에 정전기로 붙인 뒤 가열해 **도막**을 만드는 도장 방식이에요.","**소부건조**: 칠한 재료를 가열로에서 일정 온도로 가열해 **도막**을 빠르고 단단하게 굳히는 건조 방식이에요.","오른쪽 사진이 **분체도장**이에요. 건에서 나온 연두색 가루가 금속판에 붙고 있어요."]},{"kind":"points","head":"공정 분류 = 칠의 층","items":["**하도**는 맨 아래 기초 칠(프라이머), **중도**는 가운데 칠, **상도**는 맨 위 마감 칠이에요.","화장으로 치면 베이스, 색조, 마무리예요. 26쪽부터 나오는 공정이 이 순서로 쌓여요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**분체도장**은 7가지 분류 기준 중 어디에 속하나?","choices":["도료의 종류","도장 방법","건조, 경화 방법","마감 상태"],"a":1,"why":"붓도장, 롤러도장, 분무도장, 정전도장과 함께 '도장 방법에 따른 분류' 줄에 있어요."},{"kind":"check","q":"도장한 재료를 가열로에서 가열해 도막을 빠르고 단단하게 굳히는 건조 방식은?","choices":["자연건조","강제건조","**소부건조**","**분체도장**"],"a":2,"why":"**소부건조**는 '건조, 경화 방법에 따른 분류' 의 하나예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**분체도장**은 '도장 방법' 칸, **소부건조**는 '건조, 경화 방법' 칸이에요. 둘 다 열을 쓰지만 칸이 달라요.","공정 분류의 '**하도**(프라이머)' 처럼 하도를 프라이머라고도 불러요."]},{"kind":"english","head":"서술 답안: 도장의 분류 기준","en":"도장은 도료의 종류, 도장 방법, 바탕재, 공정, 마감 상태, 용도, 건조 및 경화 방법에 따라 분류한다.","ko":"기준 7개를 빠짐없이.","tip":"'도, 방, 바, 공, 마, 용, 건' 첫 글자 일곱 개로 외우세요."}],"walk":{"head":{"b":[0.0092,0.0368,0.135,0.1435],"c":[0,0.0208,0.2,0.1755],"r":2.026,"img":"img/L5/walk/p021_h.jpg"},"parts":[{"b":[0.021,0.197,0.386,0.311],"c":[0.0017,0.181,0.4246,0.343],"r":2.2007,"img":"img/L5/walk/p021_23_01.jpg","say":"분류 기준 7줄: 도료 종류, 도장 방법, 바탕재, 공정, 마감 상태, 용도, 건조, 경화 방법."},{"b":[0.4,0.246,0.414,0.028],"c":[0.3793,0.205,0.4554,0.11],"r":7.36,"img":"img/L5/walk/p021_23_02.jpg","say":"보라색 메모: 분체도장 정의. 도장 방법 줄 옆에 붙어 있어요."},{"b":[0.286,0.513,0.4,0.028],"c":[0.266,0.472,0.44,0.11],"r":7.1111,"img":"img/L5/walk/p021_23_03.jpg","say":"보라색 메모: 소부건조 정의. 건조, 경화 방법 줄 아래에 있어요."},{"b":[0.75,0.286,0.239,0.383],"c":[0.737,0.2668,0.263,0.4213],"r":1.1098,"img":"img/L5/walk/p021_23_04.jpg","say":"사진: 분체도장. 가루 도료를 금속판에 뿜어 붙이는 모습이에요."}]}},{"p":22,"title":"도장용 공구 1: 붓, 폼브러시, 롤러 브러쉬","terms":["foam brush","롤러 브러쉬","varnish","water-based paint","oil-based paint","도막"],"pass1":[{"kind":"say","lines":["이제부터 칠하는 도구 여섯 가지를 차례로 봐요. 첫 쪽은 붓과 롤러예요.","좁은 곳은 붓, 매끈하게는 스펀지 붓, 넓은 벽은 굴리는 **롤러 브러쉬**예요."]},{"kind":"compare","head":"넓이로 고르기","cols":["도구","언제"],"rows":[["붓","좁은 곳, 세밀한 곳"],["**폼브러시(foam brush)**","붓 자국 없이 매끈하게"],["**롤러 브러쉬**","벽, 천장처럼 넓은 면"]]}],"pass2":[{"kind":"points","head":"6.3.1 붓","items":["붓은 천연모, 또는 나일론, 폴리에스터 같은 합성섬유로 만들어요. 도료 종류와 도장면에 맞는 붓을 골라요.","좋은 붓: 털이 부드럽고 정렬이 잘 되어 있고, 털 빠짐이 적고, 탄력이 적절한 것.","천연모는 주로 **유성 페인트(oil-based paint)** 같은 유성도료나 **바니쉬(varnish)**에 써요.","합성모는 **수성 페인트(water-based paint)** 같은 수성도료를 비롯해 다양한 도료에 써요."]},{"kind":"points","head":"**폼브러시(foam brush)**","items":["스펀지 형태의 도장 공구예요.","붓 자국을 줄이고 매끄러운 **도막**을 만들 때 써요.","수성, 유성 도료와 **바니쉬(varnish)** 모두에 쓸 수 있어요."]},{"kind":"points","head":"6.3.2 **롤러 브러쉬**","items":["원통형 롤러 표면에 천이나 합성섬유를 붙인 공구예요. 도료를 묻혀 굴려요.","넓은 면을 빠르고 균일하게 칠해요. 벽, 천장에 알맞아요.","롤러 털의 길이와 재질에 따라 **도막** 두께와 표면 질감이 달라져요.","26쪽 수성페인트 공정의 하도, 중도, 최종 도장이 모두 롤러 작업이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"천연모 붓을 주로 쓰는 도료는?","choices":["수성도료","유성도료나 **바니쉬(varnish)**","분체도료","방청도료만"],"a":1,"why":"천연모 = 유성도료, 바니쉬. 합성모 = 수성도료를 비롯한 다양한 도료예요."},{"kind":"check","q":"붓 자국을 줄이고 매끄러운 도막을 만들 때 쓰는 스펀지 형태의 공구는?","choices":["**롤러 브러쉬**","**폼브러시(foam brush)**","**주걱(spatula)**","**샌더(sander)**"],"a":1,"why":"스펀지 형태 = **폼브러시(foam brush)**예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["천연모 = 유성, 바니쉬 / 합성모 = 수성. 짝을 바꿔 내는 보기가 함정이에요.","슬라이드 표기가 6.3.2 제목은 '롤러 브러쉬', 26쪽 공정은 '롤러 브러시' 로 섞여 있어요. 같은 공구예요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1221,0.1392],"c":[0,0.0208,0.2,0.1712],"r":2.0768,"img":"img/L5/walk/p022_h.jpg"},"parts":[{"b":[0.021,0.178,0.771,0.184],"c":[0,0.162,0.8481,0.216],"r":6.9802,"img":"img/L5/walk/p022_23_01.jpg","say":"6.3.1 붓: 천연모(유성, 바니쉬)와 합성모(수성), 그리고 폼브러시."},{"b":[0.021,0.404,0.671,0.129],"c":[0,0.388,0.7381,0.161],"r":8.1502,"img":"img/L5/walk/p022_23_02.jpg","say":"6.3.2 롤러 브러쉬: 굴려서 넓은 면을 빠르고 균일하게."},{"b":[0.027,0.584,0.2,0.313],"c":[0.015,0.568,0.224,0.345],"r":1.1543,"img":"img/L5/walk/p022_23_03.jpg","say":"붓(칠솔) 사진."},{"b":[0.233,0.584,0.359,0.313],"c":[0.215,0.568,0.3949,0.345],"r":2.0349,"img":"img/L5/walk/p022_23_04.jpg","say":"롤러브러쉬 사진 두 장: 손으로 굴리기, 긴 손잡이로 천장 쪽 칠하기."},{"b":[0.614,0.584,0.229,0.313],"c":[0.602,0.568,0.253,0.345],"r":1.3037,"img":"img/L5/walk/p022_23_05.jpg","say":"폼브러시 사진: 스펀지 머리에 나무 손잡이."}]}},{"p":23,"title":"도장용 공구 2: 정판(퍼티판)과 주걱(헤라)","terms":["정판","spatula","putty"],"pass1":[{"kind":"say","lines":["퍼티 작업에 쓰는 도구 한 쌍이에요.","**정판**은 반죽을 덜어 놓는 접시, **주걱(spatula)**은 그 반죽을 벽에 펴 바르는 칼이에요.","**퍼티(putty)**는 벽의 패인 곳을 메우는 반죽, 화장의 컨실러 같은 재료예요."]}],"pass2":[{"kind":"compare","head":"**정판**과 **주걱(spatula)**","cols":["구분","**정판**(퍼티판)","**주걱(spatula)**(헤라)"],"rows":[["하는 일","퍼티나 컴파운드를 덜어 놓고 섞거나 작업 중 받침판으로 써요","**퍼티(putty)**를 바탕면에 바르고 메우거나 평활하게 펴요"],["재질","목재, 금속, 플라스틱 등","금속, 플라스틱, 고무 등 다양한 재질과 크기"]]},{"kind":"points","head":"공사 순서에서의 자리","items":["**퍼티(putty)** 작업은 칠을 올리기 전, 바탕을 고르는 단계예요.","26쪽 공정에서 퍼티는 하도 전에도, 하도와 중도 사이에도 반복돼요. 그때마다 이 두 도구를 써요.","현장에서는 주걱을 '헤라' 라고 많이 불러요. 슬라이드 제목에도 함께 적혀 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"퍼티나 컴파운드를 덜어 놓고 혼합하거나 작업 중 받침판으로 쓰는 공구는?","choices":["**주걱(spatula)**","**정판**","**샌더(sander)**","**폴리셔(polisher)**"],"a":1,"why":"받침판 = **정판**(퍼티판). 펴 바르는 쪽이 **주걱(spatula)**이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**정판** = 받침판(덜어 놓기), **주걱(spatula)** = 펴 바르기. 역할을 바꾼 보기가 함정이에요.","다른 이름: 주걱은 헤라, 정판은 퍼티판이에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.2538,0.1392],"c":[0,0.0208,0.2792,0.1712],"r":2.8993,"img":"img/L5/walk/p023_h.jpg"},"parts":[{"b":[0.021,0.178,0.686,0.091],"c":[0,0.1473,0.7546,0.1525],"r":8.7968,"img":"img/L5/walk/p023_22_01.jpg","say":"본문 두 줄: 정판은 덜어 놓는 받침판, 주걱(헤라)은 펴 바르는 공구."},{"b":[0.125,0.368,0.179,0.218],"c":[0.113,0.352,0.203,0.25],"r":1.4436,"img":"img/L5/walk/p023_22_02.jpg","say":"정판(퍼티판) 실물. 손잡이가 달린 받침판이에요."},{"b":[0.091,0.65,0.26,0.231],"c":[0.078,0.634,0.286,0.263],"r":1.9332,"img":"img/L5/walk/p023_22_03.jpg","say":"정판을 손에 받쳐 든 모습이에요."},{"b":[0.393,0.372,0.261,0.466],"c":[0.38,0.3487,0.2871,0.5126],"r":0.9957,"img":"img/L5/walk/p023_22_04.jpg","say":"주걱으로 받침판 위 퍼티를 뜨는 모습이에요."},{"b":[0.663,0.372,0.262,0.468],"c":[0.6499,0.3486,0.2882,0.5148],"r":0.9953,"img":"img/L5/walk/p023_22_05.jpg","say":"넓은 주걱(헤라)으로 퍼티를 덜어 내는 모습이에요."}]}},{"p":24,"title":"도장용 공구 3: 스프레이 건, 에어와 에어리스","terms":["spray gun","에어 스프레이","에어리스 스프레이","dry spray","도료"],"pass1":[{"kind":"say","lines":["**스프레이 건(spray gun)**은 페인트를 아주 작은 알갱이로 뿜어 칠하는 도구예요.","공기로 잘게 쪼개 뿜는 **에어 스프레이**, 도료를 세게 눌러 뿜는 **에어리스 스프레이**가 있어요."]},{"kind":"compare","head":"한 줄로 구별","cols":["방식","한 줄"],"rows":[["**에어 스프레이**","공기로 잘게 쪼갬 → 마감이 섬세함"],["**에어리스 스프레이**","도료 자체를 고압으로 뿜음 → 빠르고 넓게 칠함"]]}],"pass2":[{"kind":"points","head":"6.3.4 **스프레이 건(spray gun)**","items":["**도료**를 미세한 입자로 분사해 칠하는 공구예요. 넓은 면을 균일하고 매끄럽게 마감해요.","일반적인 **에어 스프레이** 건은 컴프레서가 보내는 압축공기로 도료를 미립화(아주 잘게 쪼갬)해 뿜어요.","노즐 구경은 도료의 점도와 도장 목적에 따라 골라요.","미세한 마감에는 작은 구경, 점도가 높거나 하도 작업에는 비교적 큰 구경을 써요."]},{"kind":"compare","head":"**에어 스프레이**와 **에어리스 스프레이**","cols":["구분","**에어 스프레이**","**에어리스 스프레이**"],"rows":[["원리","압축공기로 노즐에서 도료를 미세한 입자로 분사","압축공기 없이 도료 자체에 높은 압력을 가해 작은 노즐로 미립화"],["장점","입자가 미세해 균일하고 매끄러운 마감","고점도 도료도 분사, 한 번에 많은 양, 넓은 면적을 빠르게"],["약점, 주의","비산되는 도료가 많아 재료 손실이 큼, **건조분무(dry spray)** 주의","정밀하고 섬세한 마감보다 생산성이 필요한 작업에 유리"]]},{"kind":"points","head":"**건조분무(dry spray)**","items":["분사거리나 공기압이 알맞지 않으면 도료 입자가 칠할 면에 닿기 전에 말라요.","그래서 거칠게 마감돼요. 이 쪽은 '드라이 스프레이(dry spray)' 로 적었어요.","19쪽에서 바람이 셀 때 생긴다던 **건조분무(dry spray)**와 같은 현상이에요."]},{"kind":"bg","src":"배경 지식","lines":["비산은 날려 흩어진다는 뜻이에요. 벽에 안 붙고 공중으로 날아간 도료는 버려져요.","점도는 끈적한 정도예요. 꿀처럼 진하면 고점도예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"압축공기를 쓰지 않고 도료 자체에 높은 압력을 가해 분사하는 방식은?","choices":["**에어 스프레이**","**에어리스 스프레이**","**분체도장**","**롤러 브러쉬**"],"a":1,"why":"공기가 없는(less) 방식 = **에어리스 스프레이**예요."},{"kind":"check","q":"점도가 높은 도료나 하도 작업에 쓰는 노즐 구경은?","choices":["작은 구경","비교적 큰 구경","구경과 상관없음","노즐을 쓰지 않음"],"a":1,"why":"미세한 마감은 작은 구경, 고점도나 하도는 비교적 큰 구경이에요."},{"kind":"check","q":"슬라이드에서 **건조분무(dry spray)** 현상이 생길 수 있다고 적힌 방식은?","choices":["**에어 스프레이**","**에어리스 스프레이**","붓 도장","주걱 도장"],"a":0,"why":"에어 스프레이 칸의 셋째 줄: 분사거리나 공기압이 알맞지 않으면 드라이 스프레이가 생겨요."},{"kind":"english","head":"서술 답안: 에어와 에어리스 비교","en":"에어 스프레이는 압축공기로 도료를 미세하게 분사해 마감이 섬세하지만 재료 손실이 크고, 에어리스 스프레이는 도료 자체에 고압을 가해 분사하므로 고점도 도료도 가능하고 넓은 면적을 빠르게 칠할 수 있다.","ko":"에어 = 섬세, 손실 큼. 에어리스 = 빠르고 넓게, 고점도 가능.","tip":"리스(less)는 '없다' 는 뜻이에요. 공기가 없으니 도료를 직접 눌러 뿜어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.198,0.1512],"c":[0,0.0208,0.222,0.1832],"r":2.1543,"img":"img/L5/walk/p024_h.jpg"},"parts":[{"b":[0.021,0.19,0.75,0.129],"c":[0,0.1712,0.825,0.1667],"r":8.7982,"img":"img/L5/walk/p024_24_01.jpg","say":"본문 세 줄: 미세한 입자로 분사, 압축공기로 미립화, 노즐 구경 고르기."},{"b":[0.029,0.334,0.546,0.383],"c":[0.0017,0.3149,0.6006,0.4213],"r":2.5344,"img":"img/L5/walk/p024_24_02.jpg","say":"현장 사진 세 장: 에어 스프레이 / 에어리스 스프레이로 칠하는 모습."},{"b":[0.604,0.327,0.379,0.348],"c":[0.5831,0.3096,0.4169,0.3828],"r":1.9361,"img":"img/L5/walk/p024_24_03.jpg","say":"스프레이 건 실물 사진. 위나 아래에 도료 통이 달려 있어요."},{"b":[0.016,0.742,0.324,0.217],"c":[0,0.726,0.3564,0.249],"r":2.5446,"img":"img/L5/walk/p024_24_04.jpg","say":"* 에어 스프레이: 압축공기, 섬세한 마감, 재료 손실, 드라이 스프레이."},{"b":[0.349,0.746,0.266,0.221],"c":[0.3357,0.73,0.2926,0.253],"r":2.056,"img":"img/L5/walk/p024_24_05.jpg","say":"* 에어리스 스프레이: 도료 자체에 고압, 고점도 가능, 생산성."},{"b":[0.624,0.793,0.359,0.108],"c":[0.6051,0.777,0.3949,0.14],"r":5.0146,"img":"img/L5/walk/p024_24_06.jpg","say":"요약 상자: 에어 = 공기로 잘게 쪼갬 → 섬세. 에어리스 = 고압으로 뿜음 → 빠르고 넓게."}]}},{"p":25,"title":"도장용 공구 4: 샌더와 폴리셔","terms":["sander","polisher","샌딩","putty"],"pass1":[{"kind":"say","lines":["갈아서 평평하게 하는 **샌더(sander)**, 문질러 반짝이게 하는 **폴리셔(polisher)**예요.","화장으로 치면 샌더는 다듬기, 폴리셔는 마지막 광 내기예요."]}],"pass2":[{"kind":"points","head":"6.3.5 **샌더(sander)**","items":["초벌 퍼티 작업이나 중벌 칠을 한 뒤 면을 편편하게 하려고 연마하는 공구예요.","샌드페이퍼(사포)를 고정하고 전동모터로 움직여 면 갈이를 해요.","샌더로 가는 작업을 **샌딩**이라고 해요. 26쪽 공정에서 **퍼티(putty)** 다음에 늘 따라와요."]},{"kind":"points","head":"6.3.6 **폴리셔(polisher)**","items":["도장면이나 마감면에 광택을 내고 표면을 매끄럽게 다듬는 전동공구예요.","전동모터로 회전하는 패드에 펠트, 양모, 스펀지 같은 연마 패드를 붙여 써요.","제품에 따라 샌드페이퍼 같은 연마재를 붙여 가벼운 연마 작업도 해요.","보라색 메모: 인조 대리석 시공의 마무리에도 써요."]},{"kind":"compare","head":"도장용 공구 정리 (22~25쪽)","cols":["공구","하는 일"],"rows":[["붓, **폼브러시(foam brush)**","좁은 곳, 붓 자국 없이 매끈하게"],["**롤러 브러쉬**","굴려서 넓은 면을 빠르고 균일하게"],["**정판**","퍼티를 덜어 놓는 받침판"],["**주걱(spatula)**","퍼티를 펴 바르고 메우기"],["**스프레이 건(spray gun)**","미세한 입자로 뿜어 칠하기"],["**샌더(sander)**","면을 편편하게 갈기"],["**폴리셔(polisher)**","광택 내고 매끄럽게 다듬기"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"도장면의 광택을 내고 인조 대리석 시공 마무리에도 쓰는 공구는?","choices":["**샌더(sander)**","**폴리셔(polisher)**","**스프레이 건(spray gun)**","**정판**"],"a":1,"why":"광택 = **폴리셔(polisher)**. 보라색 메모에 인조 대리석 마무리가 적혀 있어요."},{"kind":"check","q":"초벌 퍼티 작업이나 중벌 칠 뒤 면을 편편하게 연마하는 공구는?","choices":["**샌더(sander)**","**폴리셔(polisher)**","**롤러 브러쉬**","**주걱(spatula)**"],"a":0,"why":"샌드페이퍼를 고정해 전동으로 면 갈이를 하는 **샌더(sander)**예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**샌더(sander)** = 평평하게 갈기, **폴리셔(polisher)** = 광택. 폴리셔도 연마재를 붙이면 가벼운 연마를 해서 헷갈려요.","도장용 공구 단원은 6.3.1~6.3.6 여섯 칸이에요."]},{"kind":"english","head":"단답 답안: 도장용 공구","en":"도장용 공구에는 붓(폼브러시), 롤러 브러쉬, 정판과 주걱(헤라), 스프레이 건, 샌더, 폴리셔가 있다.","ko":"6.3.1~6.3.6 순서 그대로.","tip":"칠하는 도구(붓, 롤러, 스프레이) + 퍼티 도구(정판, 주걱) + 가는 도구(샌더, 폴리셔)로 묶어 외우세요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1221,0.1033],"c":[0,0.0208,0.2,0.1353],"r":2.6279,"img":"img/L5/walk/p025_h.jpg"},"parts":[{"b":[0.021,0.146,0.482,0.127],"c":[0,0.13,0.5302,0.159],"r":5.9282,"img":"img/L5/walk/p025_23_01.jpg","say":"6.3.5 샌더: 초벌 퍼티, 중벌 칠 뒤 면을 편편하게 연마."},{"b":[0.036,0.282,0.414,0.241],"c":[0.0153,0.266,0.4554,0.273],"r":2.9656,"img":"img/L5/walk/p025_23_02.jpg","say":"샌더 사진: 샌드페이퍼를 붙이는 바닥판이 보여요."},{"b":[0.021,0.536,0.443,0.178],"c":[0,0.52,0.4873,0.21],"r":4.1253,"img":"img/L5/walk/p025_23_03.jpg","say":"6.3.6 폴리셔: 광택, 연마 패드(펠트, 양모, 스펀지), 인조 대리석 마무리 메모."},{"b":[0.427,0.726,0.53,0.231],"c":[0.4005,0.71,0.583,0.263],"r":3.9409,"img":"img/L5/walk/p025_23_04.jpg","say":"폴리셔 사진 세 대: 둥근 회전 패드가 달려 있어요."}]}},{"p":26,"title":"도장의 공정: 수성페인트 9단계, 비닐페인트 9단계","terms":["water-based paint","비닐 페인트","putty","샌딩","하도","중도","상도","보양","조인트 테이프","롤러 브러쉬"],"pass1":[{"kind":"analogy","head":"도장 = 화장","scene":"화장할 때 세수하고, 옷에 안 묻게 가운을 두르고, 잡티를 가리고, 다듬은 뒤 색을 올리죠. 칠도 똑같아요.","map":[["세수","바탕면 정리"],["가운 두르기","**보양**"],["컨실러","**퍼티(putty)**"],["다듬기","**샌딩**"],["베이스, 색조, 마무리","**하도**, **중도**, **상도**"]]},{"kind":"say","lines":["이 쪽은 칠하는 순서표예요. 왼쪽은 **수성 페인트(water-based paint)**, 오른쪽은 **비닐 페인트**예요.","둘 다 아홉 단계지만, 결국 '메우고 갈고' 를 반복하다가 칠을 올려요."]}],"pass2":[{"kind":"say","lines":["현장 순서 '가설 → 철거 → 경량철골 → 마감' 에서 칠은 마감 자리예요.","3강의 경량철골 벽체와 천장에 석고보드를 다 붙인 다음 시작해요."]},{"kind":"points","head":"6.4 공정의 뼈대","items":["먼저 바탕면의 오염, 요철, 균열을 정리하고, 도료가 다른 곳에 묻지 않게 **보양**한 뒤 작업해요.","**보양**은 2강에서 배운 대로 마감재가 다치거나 더러워지지 않게 덮는 임시 보호예요.","바탕재와 도료 종류에 따라 **퍼티(putty)**, **샌딩**, **하도**, **중도**, **상도**의 순서와 횟수는 달라질 수 있어요.","보라색 메모 1: 바탕면이 고르지 않으면 위에 아무리 잘 칠해도 다 티가 나요.","보라색 메모 2: **보양**을 소홀히 하면 일을 두 번 하게 될 수 있어요(재료비, 인건비, 공사일수 증가)."]},{"kind":"steps","head":"6.4.1 **수성 페인트(water-based paint)** 9단계","steps":["1) 도장 대상 면에 1차 **퍼티(putty)**","2) 샌더기로 면을 고르는 1차 **샌딩**","3) 2차 퍼티","4) 2차 샌딩","5) **롤러 브러쉬**로 **하도**","6) 요철 부위 퍼티 + 면 고르기 샌딩","7) 롤러 브러쉬로 **중도**","8) 요철 부위 2차 퍼티 + 면 고르기 샌딩","9) 롤러 브러쉬로 최종 마무리 도장"],"answer":"퍼티와 샌딩이 짝으로 네 번 나오고, 사이사이 하도 → 중도 → 최종 도장(모두 롤러)이 끼어요."},{"kind":"steps","head":"6.4.2 **비닐 페인트** 9단계","steps":["1) 석고보드의 면과 이음부 정리","2) 이음매에 **조인트 테이프** 붙이기","3) 조인트 테이프 위 1차 퍼티 → 건조 후 샌딩","4) 필요에 따라 2차 퍼티, 샌딩","5) 전체 면 퍼티 → 샌딩으로 평활하게","6) 필요 시 프라이머 또는 **하도**","7) 1차 비닐페인트 도장","8) 면 상태 확인, 필요한 부분 보수","9) 2차 마감용 비닐페인트 도장"],"answer":"석고보드에서 시작해요. 3강의 **줄퍼티**(이음매) → **올퍼티**(전체 면)가 3~5단계예요."},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"5강 문제풀이 p52","q":"일반적인 도장공사의 순서를 [보기]에서 골라 차례대로 쓰시오. (① 왁스먹임 ② 고름질 및 퍼티 ③ 초벌칠 ④ 물갈기 또는 연마작업 ⑤ 중벌칠 ⑥ 정벌칠)","qko":"메우고, 갈고, 세 번 칠하고, 왁스로 끝내는 순서를 묻는 문제예요.","solve":["이 쪽 공정처럼 먼저 바탕을 **퍼티(putty)**로 메워요. → ② 고름질 및 퍼티","메운 곳을 갈아 평평하게 해요(**샌딩**). → ④ 물갈기 또는 연마작업","칠은 아래에서 위로 초벌 → 중벌 → 정벌이에요. → ③ → ⑤ → ⑥","마지막에 왁스를 먹여요. → ①"],"answer":"② → ④ → ③ → ⑤ → ⑥ → ①"},{"kind":"check","q":"**수성 페인트(water-based paint)** 9단계에서 5단계 **하도**에 쓰는 공구는?","choices":["붓","**롤러 브러쉬**","**스프레이 건(spray gun)**","**주걱(spatula)**"],"a":1,"why":"'롤러 브러시를 이용하여 하도작업' 이에요. 중도(7단계), 최종 도장(9단계)도 롤러예요."},{"kind":"check","q":"**비닐 페인트** 9단계의 2단계는?","choices":["1차 비닐페인트 도장","이음매에 **조인트 테이프** 붙이기","프라이머 시공","전체 면 퍼티"],"a":1,"why":"1) 석고보드 면과 이음부 정리 → 2) 조인트 테이프 → 3) 테이프 위 1차 퍼티 순서예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**수성 페인트(water-based paint)**는 '1차 퍼티' 로, **비닐 페인트**는 '석고보드 면과 이음부 정리' 로 시작해요.","**보양**을 소홀히 하면 재료비, 인건비, 공사일수가 늘어요. 이유를 묻는 서술에 그대로 쓰세요.","슬라이드 표기: 22쪽은 '롤러 브러쉬', 이 쪽은 '롤러 브러시'. 같은 공구예요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1221,0.0882],"c":[0,0.0208,0.2,0.1202],"r":2.958,"img":"img/L5/walk/p026_h.jpg"},"parts":[{"b":[0.021,0.127,0.789,0.109],"c":[0,0.0938,0.8679,0.1753],"r":8.8017,"img":"img/L5/walk/p026_24_01.jpg","say":"6.4 첫 두 줄: 바탕면 정리, 보양, 순서와 횟수는 달라질 수 있음. 위에 보라색 메모 두 개."},{"b":[0.025,0.282,0.325,0.462],"c":[0.0087,0.2589,0.3575,0.5082],"r":1.2506,"img":"img/L5/walk/p026_24_02.jpg","say":"6.4.1 수성페인트 9단계: 퍼티, 샌딩 반복 사이에 하도, 중도, 최종 도장(롤러)."},{"b":[0.457,0.282,0.354,0.462],"c":[0.4393,0.2589,0.3894,0.5082],"r":1.3622,"img":"img/L5/walk/p026_24_03.jpg","say":"6.4.2 비닐페인트 9단계: 석고보드 정리, 조인트 테이프부터 시작해요."}]}},{"p":27,"title":"비닐페인트 천장 시공 과정 1: 청소부터 등 위치 먹줄까지","terms":["비닐 페인트","조인트 테이프","줄퍼티","올퍼티","putty"],"pass1":[{"kind":"say","lines":["사진으로 보는 천장 칠하기예요. 27~29쪽 세 쪽에 걸쳐 순서대로 이어져요.","이 쪽은 칠하기 전 준비예요. 청소하고, 이음매를 메우고, 전체를 메우고, 등 자리를 표시해요."]}],"pass2":[{"kind":"steps","head":"사진 캡션 순서 (1~7)","steps":["1. 먼지 청소","2. 줄눈 퍼티 메우기","3. 망사테이프 붙이기","4. 망사테이프 위 퍼티 바르기","5. 점, 줄 퍼티 작업","6. 전면 퍼티 작업","7. 등 위치 먹줄 작업"],"answer":"청소 → 이음매(줄눈, 테이프, 테이프 위 퍼티) → 점, 줄 퍼티 → 전면 퍼티 → 먹줄."},{"kind":"points","head":"26쪽 **비닐 페인트** 9단계와 짝짓기","items":["망사테이프는 그물 모양의 **조인트 테이프**예요. 35쪽에서 다시 나와요.","2~4번이 비닐페인트 2, 3단계(조인트 테이프, 테이프 위 1차 **퍼티(putty)**)예요.","5번 점, 줄 퍼티는 3강의 **줄퍼티**와 이어져요. 사진 속 흰 점과 흰 줄이 메운 자리로 보여요.","6번 전면 퍼티가 비닐페인트 5단계(전체 면 퍼티)이고, 3강의 **올퍼티**예요.","7번 먹줄은 등을 달 위치를 천장에 표시하는 선이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"천장 시공 사진 순서에서 '전면 퍼티 작업' 바로 앞 단계는?","choices":["먼지 청소","점, 줄 퍼티 작업","등 위치 먹줄 작업","망사테이프 붙이기"],"a":1,"why":"부분(점, 줄) 퍼티를 먼저 하고 전체 면(전면) 퍼티를 해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["점, 줄 퍼티(부분) → 전면 퍼티(전체). **줄퍼티** → **올퍼티** 순서와 같아요.","등 위치 먹줄은 퍼티가 다 끝난 다음이에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.5965,0.1584],"c":[0,0.0208,0.6562,0.1904],"r":6.127,"img":"img/L5/walk/p027_h.jpg"},"parts":[{"b":[0.07,0.201,0.262,0.419],"c":[0.0569,0.18,0.2882,0.4609],"r":1.1116,"img":"img/L5/walk/p027_22_01.jpg","say":"1. 먼지 청소: 바닥을 쓸고 있어요."},{"b":[0.343,0.201,0.171,0.419],"c":[0.3285,0.18,0.2,0.4609],"r":0.7714,"img":"img/L5/walk/p027_22_02.jpg","say":"2. 줄눈 퍼티 메우기: 보드 이음매 틈을 퍼티로 메워요."},{"b":[0.525,0.201,0.363,0.419],"c":[0.5069,0.18,0.3993,0.4609],"r":1.5402,"img":"img/L5/walk/p027_22_03.jpg","say":"3, 4. 망사테이프 붙이기 → 망사테이프 위 퍼티 바르기."},{"b":[0.07,0.626,0.274,0.336],"c":[0.0563,0.6092,0.3014,0.3696],"r":1.4497,"img":"img/L5/walk/p027_22_04.jpg","say":"5. 점, 줄 퍼티 작업: 천장에 흰 점과 흰 줄이 보여요."},{"b":[0.349,0.626,0.255,0.336],"c":[0.3362,0.6092,0.2805,0.3696],"r":1.3492,"img":"img/L5/walk/p027_22_05.jpg","say":"6. 전면 퍼티 작업: 천장 전체를 퍼티로 덮어 가요."},{"b":[0.615,0.626,0.268,0.336],"c":[0.6016,0.6092,0.2948,0.3696],"r":1.418,"img":"img/L5/walk/p027_22_06.jpg","say":"7. 등 위치 먹줄 작업."}]}},{"p":28,"title":"비닐페인트 천장 시공 과정 2: 등 위치 타공과 보양","terms":["보양","비닐 페인트"],"pass1":[{"kind":"say","lines":["등 자리에 구멍을 뚫고, 칠이 튀면 안 되는 곳을 꽁꽁 싸매는 단계예요.","화장 전에 가운을 두르듯 벽, 바닥, 등에 비닐을 씌워요. 이게 **보양**이에요."]}],"pass2":[{"kind":"steps","head":"사진 캡션 순서 (8~13)","steps":["8. 등 위치 타공 (등 사이즈보다 작게)","9. 등 위치 타공 확대사진","10. 마감재 만나는 부분 종이테이프 붙이기","11. 벽, 바닥에 비닐 **보양**","12. 부착물 비닐커버 작업","13. 매입등 비닐 커버 씌우기"],"answer":"구멍 뚫기 → 종이테이프 → 비닐 보양 → 부착물, 매입등 커버."},{"kind":"points","head":"볼 것","items":["타공은 구멍을 뚫는다는 뜻이에요. 등 사이즈보다 **작게** 뚫어요. 캡션에 강조 표시가 있어요.","종이테이프는 칠할 천장과 다른 마감재(벽의 나무 마감)가 만나는 선에 붙여요.","**보양**은 2강에서 배운 임시 보호예요. 여기서는 비닐로 벽, 바닥, 부착물, 매입등을 덮어요.","매입등은 천장 안에 묻어서 다는 등이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"천장 등 위치를 타공할 때 구멍 크기는?","choices":["등 사이즈보다 크게","등 사이즈와 같게","등 사이즈보다 작게","크기 상관없음"],"a":2,"why":"캡션에 '등 위치 타공 (등 사이즈보다 작게)' 라고 적혀 있어요."},{"kind":"check","q":"칠이 다른 곳에 묻지 않도록 벽, 바닥, 부착물을 비닐로 덮는 작업은?","choices":["타공","**보양**","**샌딩**","먹줄"],"a":1,"why":"**보양**이에요. 26쪽 메모처럼 소홀히 하면 일을 두 번 해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**보양**은 칠하기 '전' 이에요. 스프레이(29쪽)보다 먼저예요.","타공은 '등 사이즈보다 작게'. 크게라고 바꾼 보기가 함정이에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.2086,0.1582],"c":[0,0.0208,0.2326,0.1902],"r":2.1741,"img":"img/L5/walk/p028_h.jpg"},"parts":[{"b":[0.09,0.197,0.274,0.354],"c":[0.0763,0.1793,0.3014,0.3894],"r":1.376,"img":"img/L5/walk/p028_22_01.jpg","say":"8. 등 위치 타공(등 사이즈보다 작게)."},{"b":[0.368,0.197,0.266,0.354],"c":[0.3547,0.1793,0.2926,0.3894],"r":1.3358,"img":"img/L5/walk/p028_22_02.jpg","say":"9. 등 위치 타공 확대사진: 큰 구멍 하나와 작은 구멍들."},{"b":[0.637,0.197,0.277,0.354],"c":[0.6232,0.1793,0.3047,0.3894],"r":1.3911,"img":"img/L5/walk/p028_22_03.jpg","say":"10. 마감재 만나는 부분 종이테이프 붙이기."},{"b":[0.09,0.576,0.131,0.363],"c":[0.0555,0.5578,0.2,0.3993],"r":0.8904,"img":"img/L5/walk/p028_22_04.jpg","say":"11. 벽, 바닥에 비닐 보양."},{"b":[0.269,0.576,0.284,0.363],"c":[0.2548,0.5578,0.3124,0.3993],"r":1.3909,"img":"img/L5/walk/p028_22_05.jpg","say":"12. 부착물 비닐커버 작업."},{"b":[0.601,0.576,0.285,0.363],"c":[0.5867,0.5578,0.3135,0.3993],"r":1.3958,"img":"img/L5/walk/p028_22_06.jpg","say":"13. 매입등 비닐 커버 씌우기."}]}},{"p":29,"title":"비닐페인트 천장 시공 과정 3: 스프레이, 보수, 완성","terms":["spray gun","비닐 페인트","putty","보양"],"pass1":[{"kind":"say","lines":["드디어 칠해요. 스프레이로 뿜고, 오목한 곳을 찾아 다시 메우고, 한 번 더 뿜어 끝내요.","한 번에 끝내지 않고 '칠 → 보수 → 다시 칠' 로 마무리하는 게 핵심이에요."]}],"pass2":[{"kind":"steps","head":"사진 캡션 순서 (14~18)","steps":["14. 페인트 스프레이 작업","15. 천장 페인트 완료-1, 완료-2","16. 오목한 곳 퍼티 보수","17. 재 페인트 스프레이 보수 후 완료","18. 페인트 작업 완성","(참고) 매입등 커버 비닐 참고 사진"],"answer":"스프레이 → 완료 → 오목한 곳 보수 → 재 스프레이 → 완성."},{"kind":"points","head":"볼 것","items":["14번은 **스프레이 건(spray gun)**으로 천장에 칠을 뿜는 모습이에요.","15번 사진에서 벽과 나무 마감이 비닐로 덮여 있어요. 28쪽 **보양** 덕분이에요.","16번: 칠하고 나서 오목한 곳이 보이면 **퍼티(putty)**로 보수해요. 26쪽 **비닐 페인트** 8단계(면 확인, 보수)예요.","17번: 보수한 곳을 다시 스프레이로 칠해요. 26쪽 9단계(2차 마감용 비닐페인트)에 해당해요."]},{"kind":"compare","head":"천장 사진 순서 한눈에 (27~29쪽)","cols":["묶음","사진"],"rows":[["준비 (27쪽)","먼지 청소 → 줄눈 퍼티 → 망사테이프 → 테이프 위 퍼티 → 점, 줄 퍼티 → 전면 퍼티 → 등 위치 먹줄"],["구멍과 보양 (28쪽)","등 위치 타공 → 종이테이프 → 벽, 바닥 비닐 보양 → 부착물, 매입등 비닐 커버"],["칠과 보수 (29쪽)","스프레이 → 완료 → 오목한 곳 퍼티 보수 → 재 스프레이 → 완성"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"첫 스프레이 뒤 오목한 곳이 보이면 사진 순서상 무엇을 하나?","choices":["그대로 완성","퍼티 보수 후 재 스프레이","비닐 보양을 처음부터 다시","등 위치 먹줄"],"a":1,"why":"16. 오목한 곳 퍼티 보수 → 17. 재 페인트 스프레이 보수 후 완료 순서예요."},{"kind":"check","q":"천장 시공 사진 순서로 옳은 것은?","choices":["보양 → 전면 퍼티 → 스프레이","전면 퍼티 → 등 위치 타공 → 보양 → 스프레이","스프레이 → 보양 → 퍼티","등 위치 타공 → 먼지 청소 → 퍼티"],"a":1,"why":"준비(퍼티) → 구멍과 보양 → 칠과 보수 순서예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["이 사진들의 칠은 스프레이로 했어요. 26쪽 수성페인트 9단계는 롤러예요. 공정마다 공구가 다를 수 있어요.","완성 전에 보수가 한 번 더 들어가요. '스프레이 → 바로 완성' 은 틀린 순서예요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.2086,0.1512],"c":[0,0.0208,0.2326,0.1832],"r":2.2572,"img":"img/L5/walk/p029_h.jpg"},"parts":[{"b":[0.112,0.193,0.144,0.406],"c":[0.084,0.1727,0.2,0.4466],"r":0.7961,"img":"img/L5/walk/p029_23_01.jpg","say":"14. 페인트 스프레이 작업."},{"b":[0.299,0.19,0.328,0.409],"c":[0.2826,0.1695,0.3608,0.4499],"r":1.4257,"img":"img/L5/walk/p029_23_02.jpg","say":"15. 천장 페인트 완료-1, 완료-2: 벽은 비닐로 덮여 있어요."},{"b":[0.671,0.19,0.224,0.409],"c":[0.659,0.1695,0.248,0.4499],"r":0.98,"img":"img/L5/walk/p029_23_03.jpg","say":"16. 오목한 곳 퍼티 보수."},{"b":[0.089,0.615,0.276,0.357],"c":[0.0752,0.5971,0.3036,0.3927],"r":1.3744,"img":"img/L5/walk/p029_23_04.jpg","say":"17. 재 페인트 스프레이 보수 후 완료."},{"b":[0.373,0.615,0.276,0.357],"c":[0.3592,0.5971,0.3036,0.3927],"r":1.3744,"img":"img/L5/walk/p029_23_05.jpg","say":"18. 페인트 작업 완성."},{"b":[0.657,0.615,0.274,0.357],"c":[0.6433,0.5971,0.3014,0.3927],"r":1.3645,"img":"img/L5/walk/p029_23_06.jpg","say":"참고: 매입등 커버 비닐."}]}},{"p":30,"title":"도장의 공정: 아크릴 페인트 6단계와 특징","terms":["아크릴 페인트","putty","샌딩","하도","도막"],"pass1":[{"kind":"say","lines":["**아크릴 페인트**는 잘 안 더러워지고 물에 강한 칠이에요.","그래서 걸레받이처럼 자주 더러워지는 곳에 써요. 단계는 여섯 개로 짧아요."]}],"pass2":[{"kind":"steps","head":"6.4.3 **아크릴 페인트** 6단계","steps":["1) **퍼티(putty)** 작업 후 면을 고르는 **샌딩**","2) 2차 퍼티 후 샌딩","3) 필요 시 **하도**","4) 아크릴 페인트 1회 칠","5) 요철 부위 퍼티, 샌딩","6) 최종 도장"],"answer":"퍼티, 샌딩 두 번 → (하도) → 1회 칠 → 보수 → 최종 도장."},{"kind":"points","head":"[아크릴 페인트의 특징]","items":["내오염성(때가 잘 안 탐)과 내수성(물에 강함)이 우수한 제품은 걸레받이 등 오염이 잦은 실내 부위에 써요.","내구성이 좋아 도장 상태를 비교적 오래 유지해요.","재도장할 때는 기존 **도막**을 깨끗이 정리하고, 필요하면 연마나 프라이머 처리를 한 뒤 칠해요.","걸레받이는 벽 맨 아래, 바닥과 만나는 띠 부분이에요. 사진에 계단 벽과 걸레받이가 보여요."]},{"kind":"compare","head":"단계 수 비교 (26, 30쪽)","cols":["도료","단계","시작"],"rows":[["**수성 페인트(water-based paint)**","9","1차 퍼티"],["**비닐 페인트**","9","석고보드 면과 이음부 정리"],["**아크릴 페인트**","6","퍼티 후 샌딩"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"걸레받이처럼 오염이 잦은 실내 부위에 쓴다고 슬라이드에 적힌 페인트는?","choices":["**비닐 페인트**","**아크릴 페인트**","**방청도료(rust resisting paint)**","**바니쉬(varnish)**"],"a":1,"why":"내오염성과 내수성이 우수한 **아크릴 페인트** 제품이에요."},{"kind":"check","q":"**아크릴 페인트** 공정은 몇 단계인가?","choices":["6단계","8단계","9단계","5단계"],"a":0,"why":"수성 9, 비닐 9, 아크릴 6, 철재면 위 컬러 도장 8이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["아크릴 4단계는 '아크릴 페인트를 1회 칠' 이에요. 그 뒤 보수(5)를 하고 최종 도장(6)을 해요.","재도장 때 기존 **도막**을 그냥 두고 덧칠하지 않아요. 정리, 연마 또는 프라이머 처리 후 칠해요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1332,0.1512],"c":[0,0.0208,0.2,0.1832],"r":1.9408,"img":"img/L5/walk/p030_h.jpg"},"parts":[{"b":[0.021,0.19,0.282,0.274],"c":[0.0069,0.174,0.3102,0.306],"r":1.8022,"img":"img/L5/walk/p030_23_01.jpg","say":"6.4.3 아크릴 페인트 6단계."},{"b":[0.4,0.201,0.496,0.188],"c":[0.3752,0.185,0.5456,0.22],"r":4.4089,"img":"img/L5/walk/p030_23_02.jpg","say":"[아크릴 페인트의 특징] 세 줄: 내오염성, 내수성, 걸레받이, 내구성, 재도장."},{"b":[0.057,0.523,0.864,0.401],"c":[0.0138,0.503,0.9504,0.4411],"r":3.8304,"img":"img/L5/walk/p030_23_03.jpg","say":"사진: 계단 벽과 걸레받이 부분을 칠하는 모습이에요."}]}},{"p":31,"title":"도장의 공정: 철재면 위 컬러 도장 8단계","terms":["방청 프라이머","폴리에스테르 퍼티","서페이서","oil-based paint","샌딩","하도"],"pass1":[{"kind":"say","lines":["쇠로 된 면에 색을 칠하는 순서예요.","녹을 닦고, 밑칠을 하고, 흠을 메우고, 갈고, 칠하고, 한 번 더 칠해요."]}],"pass2":[{"kind":"steps","head":"6.4.4 철재면 위 컬러 도장 8단계","steps":["1) 녹, 기름, 먼지를 제거하고 바탕면 정리","2) 바탕재에 맞는 프라이머 도장 (일반 철재 = **방청 프라이머**, 갈바, 아연도금강판 = 상도 부착성을 높이는 전용 프라이머)","3) 요철, 흠집에 **폴리에스테르 퍼티**","4) 퍼티가 경화되면 **샌딩**으로 평활하게","5) 필요하면 **서페이서** 또는 중도용 프라이머 → 다시 샌딩","6) **유성 페인트(oil-based paint)**를 균일하게 도장","7) 도막 확인, 필요하면 부분 퍼티, 샌딩으로 수정","8) 충분히 건조 후 유성 페인트 재도장으로 색상과 도막을 균일하게 마감"],"answer":"정리 → 프라이머 → 폴리에스테르 퍼티 → 샌딩 → 서페이서 → 유성 → 수정 → 재도장."},{"kind":"points","head":"용어 풀기","items":["**방청 프라이머**: 일반 철재에 칠하는 녹 막는 밑칠(**하도**)이에요.","**폴리에스테르 퍼티**: 금속, 목재 보수에 쓰는 2액형 퍼티, 현장 말로 '포리빠데' 예요. 경화가 빠르고 단단해요.","**서페이서**: 미세한 흠집, 샌딩 자국, 요철을 메워 표면을 평활하게 만드는 중도용 도료예요(보라색 메모).","**유성 페인트(oil-based paint)**는 6단계와 8단계, 두 번 칠해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"기출 모양 연습문제","q":"철재면 위 컬러 도장의 순서를 [보기]에서 골라 나열하시오. (① 유성페인트 도장 ② 프라이머 도장 ③ 녹, 기름, 먼지 제거 ④ 폴리에스테르 퍼티 ⑤ 서페이서 도장 후 샌딩 ⑥ 퍼티 경화 후 샌딩)","qko":"쇠 위에 색을 칠하는 여섯 동작의 순서를 묻는 문제예요.","solve":["무엇을 칠하든 바탕 정리가 먼저예요. → ③","철재는 밑칠(**하도**)인 프라이머를 먼저 올려요. → ②","흠집을 **폴리에스테르 퍼티**로 메우고, 굳으면 갈아요. → ④ → ⑥","**서페이서**로 잔 흠을 한 번 더 메우고 갈아요. → ⑤","마지막에 **유성 페인트(oil-based paint)**를 칠해요. → ①"],"answer":"③ → ② → ④ → ⑥ → ⑤ → ①"},{"kind":"check","q":"일반 철재 위 컬러 도장의 2단계에 쓰는 프라이머는?","choices":["**방청 프라이머**","**만능 프라이머**","**실러(sealer)**","**서페이서**"],"a":0,"why":"일반 철재는 **방청 프라이머**, 갈바, 아연도금강판은 상도 부착성을 높이는 전용 프라이머예요."},{"kind":"check","q":"미세한 흠집, 샌딩 자국, 요철을 메워 표면을 평활하게 만드는 중도용 도료는?","choices":["**방청 프라이머**","**서페이서**","**폴리퍼티**","**바니쉬(varnish)**"],"a":1,"why":"5단계 옆 보라색 메모가 **서페이서**의 정의예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["글의 순서는 프라이머(2) → 퍼티(3)예요. 32쪽 사진은 퍼티 사진이 먼저 나오니 헷갈리지 마세요.","하도용 = **방청 프라이머**, 중도용 = **서페이서**. 층이 달라요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1611,0.1512],"c":[0,0.0208,0.2,0.1832],"r":1.9408,"img":"img/L5/walk/p031_h.jpg"},"parts":[{"b":[0.021,0.19,0.314,0.041],"c":[0.0053,0.1555,0.3454,0.11],"r":5.5822,"img":"img/L5/walk/p031_22_01.jpg","say":"1) 녹, 기름, 먼지 제거, 바탕면 정리."},{"b":[0.021,0.236,0.821,0.043],"c":[0,0.1663,0.9031,0.1825],"r":8.7973,"img":"img/L5/walk/p031_22_02.jpg","say":"2) 프라이머: 일반 철재는 방청 프라이머, 갈바, 아연도금강판은 전용 프라이머."},{"b":[0.021,0.286,0.321,0.085],"c":[0.0049,0.27,0.3531,0.117],"r":5.3652,"img":"img/L5/walk/p031_22_03.jpg","say":"3) 폴리에스테르 퍼티 → 4) 경화 후 샌딩."},{"b":[0.021,0.365,0.368,0.056],"c":[0.0026,0.338,0.4048,0.11],"r":6.5422,"img":"img/L5/walk/p031_22_04.jpg","say":"5) 서페이서 또는 중도용 프라이머 → 샌딩. 위 보라색 메모가 서페이서 정의예요."},{"b":[0.021,0.426,0.414,0.135],"c":[0.0003,0.41,0.4554,0.167],"r":4.8479,"img":"img/L5/walk/p031_22_05.jpg","say":"6) 유성페인트 → 7) 부분 수정 → 8) 건조 후 재도장."}]}},{"p":32,"title":"철재면 위 컬러 도장 사진과 만능 프라이머","terms":["폴리에스테르 퍼티","만능 프라이머","방청 프라이머","상도"],"pass1":[{"kind":"say","lines":["31쪽 순서를 실제 가게 출입구 철재 틀에서 본 사진이에요.","회색 퍼티 → 밑칠 → 색 칠 순서로 틀이 깨끗해져요.","아래 '참고' 상자의 **만능 프라이머**는 이름과 달리 녹을 막지는 못해요."]}],"pass2":[{"kind":"points","head":"사진 캡션","items":["1번: 갈바 위 **폴리에스테르 퍼티** 작업. 틀 표면에 회색 퍼티 자국이 보여요.","2번: 프라이머 작업. 문짝에 얇은 밑칠이 칠해져 있어요.","3번: 컬러 **상도** 도장 작업. 맨 위 마감 색을 올려요.","4번: 캡션은 없어요. 칠이 끝난 출입구 모습으로 보여요."]},{"kind":"points","head":"*참고 **만능 프라이머**","items":["갈바, 알루미늄, 아연도금강판 등의 표면에 얇게 칠해 다음 도료의 부착성을 높이는 하도제예요.","방청을 위한 도료는 **아니에요**.","31쪽 2단계에서 갈바, 아연도금강판에는 부착성용 전용 프라이머를 쓴다고 했어요. 같은 목적이에요."]},{"kind":"compare","head":"프라이머 두 가지","cols":["구분","**방청 프라이머**","**만능 프라이머**"],"rows":[["바탕","일반 철재","갈바, 알루미늄, 아연도금강판 등"],["목적","녹 방지(방청)","후속 도료의 부착성 높이기"],["방청 기능","있음","없음(방청용 아님)"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**만능 프라이머**에 대한 설명으로 옳지 않은 것은?","choices":["갈바, 알루미늄, 아연도금강판 표면에 얇게 칠한다","후속 도료의 부착성을 높인다","하도제이다","녹을 막는 방청 도료이다"],"a":3,"why":"슬라이드에 '방청을 위한 도료는 아니다' 라고 적혀 있어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**만능 프라이머** = 부착성, **방청 프라이머** = 녹 방지. '만능' 이라는 이름 때문에 방청도 된다고 착각하기 쉬워요.","사진 순서(퍼티 → 프라이머 → 상도)와 31쪽 글 순서(프라이머 → 퍼티 → 샌딩 → 서페이서 또는 중도용 프라이머)가 달라 보여요.","31쪽 글에는 퍼티 뒤에도 중도용 프라이머가 있어요. 순서 문제는 31쪽 글을 따르세요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1611,0.1515],"c":[0,0.0208,0.2,0.1835],"r":1.9376,"img":"img/L5/walk/p032_h.jpg"},"parts":[{"b":[0.038,0.237,0.221,0.56],"c":[0.026,0.209,0.245,0.616],"r":0.7071,"img":"img/L5/walk/p032_23_01.jpg","say":"1. 갈바 위 폴리에스테르 퍼티 작업."},{"b":[0.27,0.237,0.223,0.56],"c":[0.258,0.209,0.247,0.616],"r":0.7128,"img":"img/L5/walk/p032_23_02.jpg","say":"2. 프라이머 작업."},{"b":[0.503,0.237,0.222,0.56],"c":[0.491,0.209,0.246,0.616],"r":0.71,"img":"img/L5/walk/p032_23_03.jpg","say":"3. 컬러 상도 도장 작업."},{"b":[0.725,0.237,0.222,0.524],"c":[0.713,0.2108,0.246,0.5764],"r":0.7587,"img":"img/L5/walk/p032_23_04.jpg","say":"4. 캡션 없는 사진: 칠을 마친 출입구로 보여요."},{"b":[0.275,0.803,0.311,0.113],"c":[0.2594,0.787,0.3421,0.145],"r":4.1943,"img":"img/L5/walk/p032_23_05.jpg","say":"*참고 만능 프라이머: 부착성용 하도제, 방청용 아님."}]}},{"p":33,"title":"도장의 공정: 방청 도장 주의 사항 9가지","terms":["rust resisting paint","용접슬래그","pigment","도막","하도","상도"],"pass1":[{"kind":"say","lines":["녹을 막는 칠, **방청도료(rust resisting paint)**를 칠할 때 지킬 것 아홉 가지예요.","깨끗이 닦고, 잘 젓고, 시간 지키고, 날씨 보고, 함부로 섞지 않기예요."]}],"pass2":[{"kind":"steps","head":"6.4.5 방청 도장 1~5","steps":["1) 피도면(칠할 면)의 녹, **용접슬래그**, 쇳가루, 유분, 먼지를 충분히 제거하고 바탕면 정리","2) 보수도장 때 기존 도막의 들뜨거나 박리된 부분, 부착력이 약한 부분은 제거, 건전한 구도막은 표면을 연마해 신도막과 부착성 확보","3) **안료(pigment)**가 침전되어 있을 수 있으니 사용 전에 충분히 교반(저어 섞기)","4) 1회 도장 후 제조사가 정한 재도장 가능 시간과 건조, 경화시간을 지켜 다음 도장","5) 도료는 화기와 직사광선을 피해 제조사 지정 온도와 조건으로 보관"],"answer":"닦기 → 낡은 막 정리 → 젓기 → 시간 지키기 → 보관."},{"kind":"steps","head":"6.4.5 방청 도장 6~9","steps":["6) 비, 눈이 오거나 바탕면에 수분이 있거나, 온도, 습도가 제품 도장 조건을 벗어나면 작업하지 않음. 일반적으로 상대습도 85% 이상 또는 기온 5℃ 이하에서는 도장을 피하고 제품 시방을 따름","7) 구도막 위 보수도장은 기존 도막과 신도료의 적합성, 부착성을 확인한 뒤 시공","8) 제조사가 허용하지 않은 다른 도료나 희석제와 임의로 혼합하지 않음","9) 작업 완료 후 노출된 피부는 깨끗이 씻음"],"answer":"날씨(85% 이상, 5℃ 이하) → 구도막 확인 → 혼합 금지 → 피부 씻기."},{"kind":"points","head":"용어와 사진","items":["**용접슬래그**: 용접할 때 생기는 찌꺼기예요. 보라색 메모에 '용접똥' 이라고도 한다고 적혀 있어요.","구도막은 예전에 칠한 **도막**, 신도막은 새로 칠할 도막이에요.","사진 캡션: 피도면 정리 → 방청도료 도장하기(건조하며 2~3회) → 필요한 경우 방청도료 완전히 건조 후 에나멜 등으로 **상도** 도장.","**방청도료(rust resisting paint)**는 **하도**예요. 그 위 마감은 에나멜 같은 상도로 올려요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"5강 문제풀이 p53","q":"도장공사에서 기후에 따른 공사 중지 조건 3가지를 쓰시오.","qko":"너무 춥거나, 너무 덥거나, 너무 습할 때의 숫자를 묻는 문제예요.","solve":["이 쪽 6)에 '상대습도 85% 이상 또는 기온 5℃ 이하' 가 있어요.","문제풀이 53쪽 답은 여기에 '온도 35℃ 이상' 을 하나 더 붙였어요. 35℃는 53쪽에만 있어요.","그래서 답은 온도 두 개(낮을 때, 높을 때)와 습도 하나예요."],"answer":"① 온도 5℃ 이하 ② 온도 35℃ 이상 ③ 습도 85% 이상"},{"kind":"check","q":"방청도료 사진 캡션에 적힌 칠 횟수는?","choices":["1회","건조하며 2~3회","5회 이상","횟수 제한 없음"],"a":1,"why":"'방청도료 도장하기 (건조하며 2~3회)' 예요."},{"kind":"check","q":"방청도료를 사용 전에 충분히 교반하는 이유는?","choices":["색을 바꾸려고","**안료(pigment)**가 침전되어 있을 수 있어서","희석제를 섞으려고","건조를 늦추려고"],"a":1,"why":"가라앉은 **안료(pigment)**를 고르게 섞어 균일한 상태로 만들려고 해요. 희석제 임의 혼합은 오히려 금지예요."},{"kind":"warn","head":"습도 기준: 20쪽과 33쪽이 달라요","items":["33쪽(이 쪽): 상대습도 85% **이상** 또는 기온 5℃ **이하**에서는 도장을 피해요.","20쪽: 습도가 85% **초과**하면 칠을 해서는 안 된다고 적혀 있어요.","습도가 딱 85%면 20쪽 기준으로는 칠할 수 있고, 33쪽 기준으로는 피해야 해요. 경계가 달라요.","시험은 묻는 쪽의 표기를 따르세요. 공사 중지 조건(53쪽)은 '85% 이상' 이에요."]}],"walk":{"head":null,"parts":[{"b":[0.021,0.175,0.73,0.107],"c":[0,0.1474,0.803,0.1622],"r":8.8012,"img":"img/L5/walk/p033_23_01.jpg","say":"1) 바탕면 정리(용접슬래그 = 용접똥 메모), 2) 보수도장 때 구도막 처리."},{"b":[0.021,0.286,0.487,0.133],"c":[0,0.27,0.5357,0.165],"r":5.7719,"img":"img/L5/walk/p033_23_02.jpg","say":"3) 충분히 교반, 4) 재도장 가능 시간 준수, 5) 화기, 직사광선 피해 보관."},{"b":[0.021,0.425,0.593,0.088],"c":[0,0.4031,0.6523,0.1318],"r":8.7985,"img":"img/L5/walk/p033_23_03.jpg","say":"6) 날씨 조건: 상대습도 85% 이상 또는 기온 5℃ 이하에서는 도장을 피해요."},{"b":[0.021,0.518,0.479,0.132],"c":[0,0.502,0.5269,0.164],"r":5.7117,"img":"img/L5/walk/p033_23_04.jpg","say":"7) 구도막 적합성 확인, 8) 임의 혼합 금지, 9) 피부 씻기."},{"b":[0.754,0.025,0.243,0.628],"c":[0.7313,0,0.2687,0.6908],"r":0.6915,"img":"img/L5/walk/p033_23_05.jpg","say":"사진: 피도면 정리 → 방청도료 도장하기(건조하며 2~3회)."},{"b":[0.721,0.654,0.275,0.341],"c":[0.6975,0.6249,0.3025,0.3751],"r":1.4337,"img":"img/L5/walk/p033_23_06.jpg","say":"사진: 필요하면 완전히 건조 후 에나멜 등으로 상도 도장."}]}},{"p":34,"title":"바탕도장: 일반 순서와 바탕면 네 가지","terms":["바탕도장","조인트 테이프","조인트 퍼티","올퍼티","sealer","서페이서","방청 프라이머","용접슬래그","초벌도장","재벌도장","비닐 페인트","oil-based paint","상도","샌딩"],"pass1":[{"kind":"say","lines":["**바탕도장**은 마지막 칠이 잘 붙고 매끈하게 나오도록 먼저 하는 밑작업이에요.","화장으로 치면 베이스를 잘 깔아야 색조가 예쁘게 먹는 것과 같아요.","바탕이 석고보드냐, MDF냐, 미장면이냐, 쇠냐에 따라 방법이 조금씩 달라요."]}],"pass2":[{"kind":"points","head":"6.5.1 **바탕도장**의 뜻","items":["최종 도장의 부착성, 평활도, 마감 품질을 높이려고 먼저 하는 선행 작업이에요.","최종 도장의 품질을 좌우하는 중요한 공정이에요.","바탕면 종류에 따라 작업 방법이 달라져요."]},{"kind":"steps","head":"일반 순서","steps":["1. 오염물 제거","2. 결함부 보수","3. 퍼티 및 **샌딩**","4. 프라이머 또는 **실러(sealer)** 도장","5. **상도** 도장"],"answer":"닦고, 고치고, 메우고 갈고, 밑칠하고, 마감 칠."},{"kind":"compare","head":"바탕면별 방법","cols":["바탕면","방법"],"rows":[["석고보드면","이음부에 **조인트 테이프**와 **조인트 퍼티**, 필요하면 **올퍼티**와 샌딩으로 평활하게"],["MDF면","이음부와 요철을 퍼티로 보수, 샌딩 → 마감도료에 맞는 프라이머나 **서페이서**"],["미장, 모르타르면","균열과 요철 보수, 먼지와 이물질 제거 → **실러(sealer)** 또는 프라이머"],["철재면","녹, 유분, **용접슬래그** 제거 → **방청 프라이머** → 필요하면 퍼티와 샌딩"]]},{"kind":"points","head":"바탕 뒤의 마감과 두 갈래","items":["바탕처리가 끝나면 VP도장(**비닐 페인트**), **유성 페인트(oil-based paint)**, 래커도장, 다채무늬도장 등 설계에 따른 최종 마감도장을 해요.","**초벌도장**: 녹을 방지하거나 불순물을 제거하는 칠이에요.","**재벌도장**: 마무리 칠을 하려고 칠할 면을 평활하게 만드는 칠이에요.","**실러(sealer)**는 바탕의 흡수성을 조절하고 윗칠의 부착성을 높이는 하도용 도료예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**바탕도장**의 일반 순서로 옳은 것은?","choices":["퍼티 및 샌딩 → 오염물 제거 → 결함부 보수 → 프라이머 → 상도","오염물 제거 → 결함부 보수 → 퍼티 및 샌딩 → 프라이머 또는 실러 → 상도","프라이머 → 오염물 제거 → 퍼티 → 상도 → 샌딩","결함부 보수 → 상도 → 퍼티 → 프라이머"],"a":1,"why":"닦고(오염물), 고치고(결함부), 메우고 갈고(퍼티, 샌딩), 밑칠(프라이머, 실러), 마감(상도)이에요."},{"kind":"check","q":"MDF면 바탕도장에서 퍼티, 샌딩 뒤에 쓰는 것은?","choices":["**방청 프라이머**","마감도료에 맞는 프라이머나 **서페이서**","**조인트 테이프**만","**용접슬래그**"],"a":1,"why":"철재면이 **방청 프라이머**, 미장면이 **실러(sealer)** 또는 프라이머, MDF면이 프라이머나 **서페이서**예요."},{"kind":"check","q":"마무리 칠을 위해 칠할 면을 평활하게 하는 바탕도장은?","choices":["**초벌도장**","**재벌도장**","**상도**","**분체도장**"],"a":1,"why":"**초벌도장**은 녹 방지, 불순물 제거. **재벌도장**은 면을 평활하게 해요."},{"kind":"english","head":"서술 답안: 바탕도장의 일반 순서","en":"바탕도장은 일반적으로 오염물 제거, 결함부 보수, 퍼티 및 샌딩, 프라이머 또는 실러 도장, 상도 도장의 순서로 진행한다.","ko":"다섯 단계, 순서 그대로.","tip":"'닦, 고, 메, 밑, 마' 다섯 글자로 외우세요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**초벌도장** = 녹 방지, 불순물 제거. **재벌도장** = 면을 평활하게. 짝을 바꾼 보기가 함정이에요.","철재면은 **방청 프라이머**, 미장, 모르타르면은 **실러(sealer)** 또는 프라이머, MDF면은 프라이머나 **서페이서**예요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.151,0.1515],"c":[0,0.0208,0.2,0.1835],"r":1.9376,"img":"img/L5/walk/p034_h.jpg"},"parts":[{"b":[0.021,0.193,0.693,0.041],"c":[0,0.1365,0.7623,0.154],"r":8.8,"img":"img/L5/walk/p034_24_01.jpg","say":"첫 줄: 바탕도장은 최종 도장의 품질을 좌우하는 선행 작업."},{"b":[0.021,0.239,0.807,0.041],"c":[0,0.1698,0.8877,0.1793],"r":8.8016,"img":"img/L5/walk/p034_24_02.jpg","say":"일반 순서: 오염물 제거 → 결함부 보수 → 퍼티 및 샌딩 → 프라이머 또는 실러 → 상도."},{"b":[0.021,0.287,0.621,0.178],"c":[0,0.271,0.6831,0.21],"r":5.7829,"img":"img/L5/walk/p034_24_03.jpg","say":"바탕면 네 가지: 석고보드면, MDF면, 미장, 모르타르면, 철재면."},{"b":[0.021,0.472,0.7,0.089],"c":[0,0.4387,0.77,0.1556],"r":8.7975,"img":"img/L5/walk/p034_24_04.jpg","say":"최종 마감도장 종류, 그리고 초벌도장과 재벌도장."},{"b":[0.026,0.581,0.639,0.386],"c":[0,0.5617,0.7029,0.4246],"r":2.943,"img":"img/L5/walk/p034_24_05.jpg","say":"사진: 석고보드 바탕 도장(조인트 퍼티), MDF 바탕 도장(조인트 퍼티)."}]}},{"p":35,"title":"바탕 만들기 1: 조인트 테이프와 테이퍼드 보드","terms":["조인트 테이프","Tapered Edge Board","바탕도장","조인트 퍼티"],"pass1":[{"kind":"say","lines":["석고보드 두 장이 만나는 이음매는 금이 가기 쉬워요.","그래서 이음매에 그물 같은 **조인트 테이프**를 붙여 붕대처럼 잡아 줘요.","가장자리가 얇게 깎인 **테이퍼드 보드(Tapered Edge Board)**를 쓰면 이음부 처리가 쉬워요."]}],"pass2":[{"kind":"points","head":"6.5.2 바탕 만들기 1) 조인트 테이프 붙이기","items":["벽체나 천장에 석고보드 취부(붙여 고정하는 작업)가 끝나면 이음부에 **조인트 테이프**를 시공해요.","이음부 처리가 쉽도록 가장자리를 얇게 가공한 **테이퍼드 보드(Tapered Edge Board)**를 많이 써요. '테파드' 라고도 적혀 있어요.","**조인트 테이프**는 이음부를 보강해 이음선을 감추고 균열 발생을 줄이려고 써요."]},{"kind":"points","head":"그림 속 숫자와 모양","items":["가운데 테이프 제품 그림: 폭 3.5cm, 총길이 90m 라고 적혀 있어요.","왼쪽 사진: 그물(망사) 모양 테이프와, 금 간 벽에 붙인 사용 예시예요.","오른쪽 위 그림: 석고보드 가장자리를 확대하면 끝이 얇게 깎여 있어요. 이것이 **테이퍼드 보드(Tapered Edge Board)**예요.","오른쪽 아래 사진: 이음매에 테이프를 붙이며 헤라로 누르는 모습이에요."]},{"kind":"points","head":"공사 순서에서의 자리","items":["3강 경량철골 벽체에 석고보드를 붙인 직후, **바탕도장**의 첫 작업이에요.","순서: 석고보드 취부 → **조인트 테이프** → **조인트 퍼티**(36쪽) → 전체 면 퍼티 → 칠.","26쪽 비닐페인트 2단계, 27쪽 사진의 망사테이프 붙이기가 바로 이 작업이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"이음부 처리가 쉽도록 가장자리를 얇게 가공한 석고보드는?","choices":["**테이퍼드 보드(Tapered Edge Board)**","MDF","합판","SGP 패널"],"a":0,"why":"슬라이드 표기는 '테이퍼드 보드(또는 테파드, Tapered Edge Board)' 예요."},{"kind":"check","q":"**조인트 테이프**를 쓰는 이유로 슬라이드에 적힌 것은?","choices":["광택을 내려고","이음부를 보강해 이음선을 감추고 균열 발생을 줄이려고","녹을 막으려고","도료를 묽게 하려고"],"a":1,"why":"보강, 이음선 감추기, 균열 줄이기 세 가지예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["3.5cm, 90m 는 사진 속 한 제품의 표기예요. 모든 조인트 테이프의 규격이라고 단정하지 마세요.","테이프는 석고보드 취부(붙이기)가 끝난 '다음' 이에요. 퍼티보다 먼저예요."]}],"walk":{"head":null,"parts":[{"b":[0.021,0.197,0.675,0.174],"c":[0,0.181,0.7425,0.206],"r":6.4078,"img":"img/L5/walk/p035_23_01.jpg","say":"본문 세 줄: 취부 후 이음부에 조인트 테이프, 테이퍼드 보드, 쓰는 이유."},{"b":[0.661,0.019,0.207,0.339],"c":[0.649,0.002,0.231,0.3729],"r":1.1013,"img":"img/L5/walk/p035_23_02.jpg","say":"테이퍼드 보드 확대 그림: 가장자리가 얇게 깎여 있어요."},{"b":[0.026,0.396,0.376,0.236],"c":[0.0072,0.38,0.4136,0.268],"r":2.7436,"img":"img/L5/walk/p035_23_03.jpg","say":"망사형 조인트 테이프와 사용 예시."},{"b":[0.427,0.412,0.224,0.216],"c":[0.415,0.396,0.248,0.248],"r":1.7778,"img":"img/L5/walk/p035_23_04.jpg","say":"테이프 제품 그림: 폭 3.5cm, 총길이 90m."},{"b":[0.697,0.391,0.264,0.487],"c":[0.6838,0.3667,0.2904,0.5357],"r":0.9637,"img":"img/L5/walk/p035_23_05.jpg","say":"이음매에 테이프를 붙이며 헤라로 누르는 모습."}]}},{"p":36,"title":"바탕 만들기 2: 조인트 퍼티와 샌딩","terms":["조인트 퍼티","폴리퍼티","조인트 테이프","spatula","sander","올퍼티","줄퍼티","샌딩"],"pass1":[{"kind":"say","lines":["테이프를 붙였으면 그 위에 반죽(퍼티)을 발라 이음매를 감춰요.","못 자리도 메우고, 마르면 갈아서 평평하게 해요. 3강의 **줄퍼티**가 이 작업이에요."]}],"pass2":[{"kind":"steps","head":"2) 조인트 퍼티와 샌딩 (슬라이드 일곱 줄)","steps":["1. **조인트 테이프**를 석고보드, 합판 또는 MDF 이음매에 붙이고, 그 위에 헤라(**주걱(spatula)**)로 퍼티를 발라요.","2. 타카핀이나 나사못이 들어간 자리에도 퍼티를 해야 해요.","3. 조인트 퍼티 연마가 끝나면 도배작업 면 또는 전체 면에 퍼티 작업을 2차로 해요.","4. 이음매에 일반 퍼티 대신 고무질 성격이 있는 **폴리퍼티**를 바르면 이음매 터짐을 예방할 수 있어요.","5. 조인트 퍼티가 끝나면 샌더기로 이음매와 타카 자리 퍼티를 1차 연마해요.","6. 금속 이음매에는 일반퍼티와 폴리퍼티를 할 수 있어요.","7. 도어와 도어 프레임도 퍼티 후 샌딩해요."],"answer":"실제 흐름: 테이프 → **조인트 퍼티**(못 자리 포함) → 1차 연마 → 2차 퍼티(전체 면)."},{"kind":"points","head":"용어 풀기","items":["**조인트 퍼티**: 조인트 테이프 위 이음매에 헤라로 바르는 퍼티예요. 3강의 1차 **줄퍼티**와 같은 일이에요.","2차로 전체 면에 하는 퍼티가 3강의 **올퍼티**예요. 다음 쪽에서 이어져요.","**폴리퍼티**: 고무질 성격이 있어 이음매가 터지는 것을 막아 줘요.","1차 연마는 **샌더(sander)**로 하는 **샌딩**이에요."]},{"kind":"bg","src":"배경 지식","lines":["타카핀은 타카라는 공구로 쏘아 박는 가는 핀 못이에요.","연마는 갈아서 매끈하게 한다는 뜻이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"석고보드, 합판, MDF 이음매에 일반 퍼티 대신 바르면 이음매 터짐을 예방하는 것은?","choices":["**폴리퍼티**","**폴리에스테르 퍼티**","**서페이서**","**실러(sealer)**"],"a":0,"why":"고무질 성격이 내포된 **폴리퍼티**예요. 이름이 비슷한 **폴리에스테르 퍼티**(31쪽, 철재면 흠집)와 헷갈리지 마세요."},{"kind":"check","q":"조인트 퍼티 단계에서 이음매 말고도 퍼티를 해야 하는 곳은?","choices":["타카핀이나 나사못이 들어간 자리","천장 등 구멍 안쪽","창문 유리","바닥 타일"],"a":0,"why":"'타카핀 또는 나사못이 들어간 자리에도 퍼티를 하여야 한다' 예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**조인트 퍼티** = 이음부 중심(1차), 전체 면 퍼티 = 2차(**올퍼티**). 순서를 뒤집지 마세요.","**폴리퍼티**(고무질, 이음매 터짐 예방)와 **폴리에스테르 퍼티**(2액형, 철재면 흠집)는 다른 재료예요."]},{"kind":"english","head":"단답 답안: 폴리퍼티","en":"폴리퍼티는 고무질 성격이 내포된 퍼티로, 석고보드, 합판, MDF의 이음매에 일반 퍼티 대신 바르면 이음매의 터짐을 예방할 수 있다.","ko":"고무질 → 늘어나니까 안 터짐.","tip":"'고무질', '터짐 예방' 두 낱말을 꼭 넣으세요."}],"walk":{"head":{"b":[0.0092,0.0368,0.4454,0.1972],"c":[0,0.0208,0.49,0.2292],"r":3.8007,"img":"img/L5/walk/p036_h.jpg"},"parts":[{"b":[0.021,0.236,0.532,0.091],"c":[0,0.22,0.5852,0.123],"r":8.4582,"img":"img/L5/walk/p036_23_01.jpg","say":"첫 두 줄: 테이프 위에 헤라로 퍼티, 타카핀, 나사못 자리도 퍼티."},{"b":[0.021,0.332,0.629,0.094],"c":[0,0.3091,0.6919,0.1398],"r":8.7986,"img":"img/L5/walk/p036_23_02.jpg","say":"2차 퍼티(전체 면), 폴리퍼티로 이음매 터짐 예방."},{"b":[0.021,0.429,0.543,0.132],"c":[0,0.413,0.5973,0.164],"r":6.4748,"img":"img/L5/walk/p036_23_03.jpg","say":"샌더기로 1차 연마, 금속 이음매, 도어와 도어 프레임."},{"b":[0.493,0.533,0.307,0.061],"c":[0.4776,0.5085,0.3377,0.11],"r":5.4578,"img":"img/L5/walk/p036_23_04.jpg","say":"줄퍼티 시공 방법 영상 링크."},{"b":[0.034,0.602,0.764,0.338],"c":[0,0.5851,0.8404,0.3718],"r":4.0184,"img":"img/L5/walk/p036_23_05.jpg","say":"사진: 이음매 퍼티와 벽, 천장 이음매의 흰 줄, 헤라 작업 모습."}]}},{"p":37,"title":"올퍼티와 샌딩 작업: 벽 전체를 매끈하게","terms":["올퍼티","조인트 퍼티","putty","Gypsum Board","줄퍼티","비닐 페인트"],"pass1":[{"kind":"say","lines":["**석고보드(Gypsum Board)** 이음매를 메운 다음, 이번에는 벽 **전체**를 발라요.","이 작업이 **올퍼티** 예요.","화장으로 치면 얼굴 전체에 컨실러를 고르게 펴 바르는 단계예요."]},{"kind":"compare","head":"한 줄로 구별해요","cols":["이름","어디를 바르나"],"rows":[["**조인트 퍼티**","이음매만 줄처럼"],["**올퍼티**","벽 전체를 쫙"]]}],"pass2":[{"kind":"points","head":"올퍼티는 무엇이고 언제 하나요","items":["**조인트 퍼티** 와 샌딩이 끝난 **뒤** 에 해요. 앞 쪽 순서의 다음 칸이에요.","**올퍼티** 는 **석고보드(Gypsum Board)** 전체 면을 고르게 만드는 작업이에요.","목적: 미세한 요철과 이음부 흔적을 감추고 평활한 도장면을 만들기.","**퍼티(putty)** 가 충분히 마르면 샌딩해서 표면을 평활하게 정리해요.","샌딩은 사포로 표면을 갈아 매끈하게 다듬는 일이에요."]},{"kind":"points","head":"어떤 마감 앞에서 하나요","items":["VP도장, 컬러 래커처럼 매끄럽고 균일한 표면이 필요한 마감에 주로 해요.","VP도장은 **비닐 페인트** 로 칠하는 도장의 현장 이름이에요.","얇고 매끈한 칠일수록 바탕의 작은 흠이 그대로 비쳐서 **올퍼티** 가 필요해요."]},{"kind":"compare","head":"슬라이드 상자 그대로 외우기","cols":["구분","하는 일","3강에서 부른 이름"],"rows":[["**조인트 퍼티**","이음부 중심 보수","1차 **줄퍼티**"],["**올퍼티**","전체 면 평활화","2차 **올퍼티**"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"석고보드 전체 면을 고르게 만들어 미세한 요철과 이음부 흔적을 감추는 작업은?","choices":["조인트 테이프 붙이기","조인트 퍼티","올퍼티","잔손보기"],"a":2,"why":"**올퍼티** 는 전체 면 평활화예요. **조인트 퍼티**(3강의 **줄퍼티**)는 이음부 중심 보수라서 범위가 좁아요. VP도장(**비닐 페인트**) 같은 매끈한 마감 전에 해요."},{"kind":"english","head":"답안에 쓸 문장: 올퍼티","en":"올퍼티는 조인트 퍼티와 샌딩이 끝난 뒤 석고보드 전체 면에 퍼티를 발라, 미세한 요철과 이음부 흔적을 감추고 평활한 도장면을 만드는 작업이다.","ko":"순서(조인트 퍼티 뒤), 범위(전체 면), 목적(평활한 도장면) 세 가지를 넣어요.","tip":"올(all) = 전체, 조인트(joint) = 이음매. 영어 뜻으로 범위를 떠올려요."}],"walk":{"head":{"b":[0.0092,0.0368,0.151,0.1996],"c":[0,0.0208,0.2,0.2316],"r":1.5352,"img":"img/L5/walk/p037_h.jpg"},"parts":[{"b":[0.027,0.241,0.484,0.036],"c":[0.0028,0.204,0.5324,0.11],"r":8.6044,"img":"img/L5/walk/p037_23_01.jpg","say":"조인트 퍼티와 샌딩이 끝난 뒤 석고보드 전체 면에 올퍼티를 한다는 첫 줄이에요."},{"b":[0.027,0.381,0.486,0.038],"c":[0.0027,0.345,0.5346,0.11],"r":8.64,"img":"img/L5/walk/p037_23_02.jpg","say":"VP도장, 컬러 래커 등 매끄럽고 균일한 표면이 필요한 마감에 주로 적용해요."},{"b":[0.606,0.275,0.172,0.103],"c":[0.592,0.259,0.2,0.135],"r":2.6337,"img":"img/L5/walk/p037_23_03.jpg","say":"요약 상자. 조인트퍼티 = 이음부 중심 보수, 올퍼티 = 전체 면 평활화."},{"b":[0.018,0.497,0.481,0.35],"c":[0,0.4795,0.5291,0.385],"r":2.4432,"img":"img/L5/walk/p037_23_04.jpg","say":"투퍼티 작업 모습. 이음매와 나사 자리에만 회색 퍼티가 군데군데 보여요."},{"b":[0.559,0.497,0.416,0.35],"c":[0.5382,0.4795,0.4576,0.385],"r":2.113,"img":"img/L5/walk/p037_23_05.jpg","say":"올퍼티 작업 모습. 벽과 천장 전체를 퍼티로 덮어 가고 있어요."}]}},{"p":38,"title":"바탕 및 마감 도장 작업: 보양부터 잔손보기까지","terms":["마스킹","보양","하도","중도","상도","도막","잔손보기"],"pass1":[{"kind":"say","lines":["바탕이 매끈해졌으니 이제 진짜 색을 칠해요.","칠하기 전에 주변을 덮고, 아래층부터 차례로 칠하고, 마지막에 꼼꼼히 다시 봐요."]},{"kind":"analogy","head":"화장 순서와 같아요","scene":"화장할 때 옷에 안 묻게 가운을 두르고, 베이스, 색조, 마무리 순서로 바른 뒤 거울을 보며 고쳐요.","map":[["가운 두르기","**마스킹** 과 **보양**"],["베이스","**하도**"],["색조","**중도**"],["마무리","**상도**"],["거울 보고 고치기","**잔손보기**"]]}],"pass2":[{"kind":"steps","head":"바탕 및 마감 도장 작업의 순서","steps":["1 샌딩이 끝나면 **마스킹** 과 **보양** 을 해요. 도료가 다른 마감재에 묻거나 번지지 않게요.","2 바탕면 상태와 도료 종류에 따라 프라이머 또는 **하도** 를 칠해요.","3 그 위에 **중도** 와 **상도** 를 칠해요.","4 접합부, 틈새는 코킹재나 실란트로 처리해요.","5 도장이 부족하거나 고르지 않은 곳은 같은 도료로 보수해요.","6 **도막** 의 색상, 얼룩, 흐름, 누락 부위를 확인하고 **잔손보기** 와 보수작업으로 끝내요."],"answer":"보양 → 하도 → 중도, 상도 → 코킹, 보수 → 잔손보기"},{"kind":"points","head":"이 쪽의 용어 풀이","items":["**마스킹**: 칠하면 안 되는 곳에 테이프나 종이를 붙여 가리는 일.","**보양**: 기존 시설, 완성된 마감재가 상하거나 더러워지지 않게 임시로 덮는 일. 2강 가설공사의 말이에요.","**도막**: 도료가 마르며 표면에 생기는 얇은 막.","**잔손보기**: 최종 칠 뒤 빠진 곳, 얼룩을 찾아 손보는 마무리."]},{"kind":"bg","src":"배경 지식","lines":["코킹재, 실란트는 틈에 짜 넣어 굳히는 말랑한 메움 재료예요.","도료는 얇은 막이라 벌어진 틈을 못 메우니, 틈은 이런 재료로 따로 막아요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"도장면 샌딩 뒤, 도료가 다른 마감재에 묻거나 번지는 것을 막으려고 하는 작업은?","choices":["잔손보기","마스킹과 보양","올퍼티","코킹"],"a":1,"why":"**마스킹** 과 **보양** 은 칠하기 **전** 에 주변을 가리고 덮는 일이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**보양** 은 칠하기 전, **잔손보기** 는 다 칠한 뒤예요.","틈새는 도료가 아니라 코킹재나 실란트로 처리해요. 도장이 부족한 곳만 같은 도료로 보수해요.","칠 순서는 **하도** → **중도** → **상도**. 아래층부터 위층으로 올라가요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1554,0.1996],"c":[0,0.0208,0.2,0.2316],"r":1.5352,"img":"img/L5/walk/p038_h.jpg"},"parts":[{"b":[0.027,0.241,0.569,0.036],"c":[0,0.1958,0.6259,0.1265],"r":8.7961,"img":"img/L5/walk/p038_23_01.jpg","say":"샌딩이 끝나면 마스킹과 보양 작업. 도료가 묻거나 번지는 것을 막아요."},{"b":[0.027,0.289,0.493,0.034],"c":[0.0024,0.251,0.5423,0.11],"r":8.7644,"img":"img/L5/walk/p038_23_02.jpg","say":"프라이머 또는 하도 도장을 한 뒤 중도 및 상도 도장을 해요."},{"b":[0.027,0.335,0.726,0.036],"c":[0,0.2723,0.7986,0.1613],"r":8.8018,"img":"img/L5/walk/p038_23_03.jpg","say":"틈새는 코킹재나 실란트, 부족한 곳은 같은 도료로 보수해요."},{"b":[0.027,0.382,0.58,0.037],"c":[0,0.3361,0.638,0.1289],"r":8.7992,"img":"img/L5/walk/p038_23_04.jpg","say":"색상, 얼룩, 흐름, 누락 부위를 확인하고 잔손보기로 끝내요."},{"b":[0.028,0.48,0.219,0.39],"c":[0.016,0.4605,0.243,0.429],"r":1.007,"img":"img/L5/walk/p038_23_05.jpg","say":"계단 난간 등 보양한 모습. 난간과 계단을 비닐로 덮었어요."},{"b":[0.253,0.48,0.727,0.39],"c":[0.2003,0.4605,0.7997,0.429],"r":3.314,"img":"img/L5/walk/p038_23_06.jpg","say":"스프레이와 롤러로 마감 도장하는 모습이에요."}]}},{"p":39,"title":"도장용 용구별 마감도장: 붓, 롤러, 스프레이, 주걱","terms":["롤러 브러쉬","에어 스프레이","spatula","정판","안티스터코 도장","잔손보기","올퍼티","water-based paint"],"pass1":[{"kind":"say","lines":["칠하는 도구가 네 가지예요. 붓, 롤러, 스프레이, 주걱.","좁은 곳은 붓, 넓은 곳은 롤러, 아주 매끈하게는 스프레이, 무늬를 내려면 주걱이에요."]},{"kind":"compare","head":"도구 네 개 한눈에","cols":["도구","언제 쓰나"],"rows":[["붓","좁고 세밀한 곳"],["**롤러 브러쉬**","넓은 벽과 천장"],["**에어 스프레이**","매끈한 고급 마감"],["**주걱(spatula)**","펴 바르며 무늬 내기"]]}],"pass2":[{"kind":"compare","head":"용구별 마감도장 자세히","cols":["용구","쓰는 곳","특징"],"rows":[["붓 도장","좁은 면적, 모서리, 몰딩, 보수도장","최종 도장 뒤 **잔손보기** 에 써요. 아주 부분적인 도장."],["**롤러 브러쉬** 도장","벽, 천장 같은 넓은 면적","빠르고 균일하게. 주로 **수성 페인트(water-based paint)**."],["**에어 스프레이** 도장","미려한 마감이 필요할 때","도장 면이 평활하고 매끄러운 질감. 뿜칠이라고도 해요."],["**주걱(spatula)** 에 의한 도장","도장재를 직접 펴 바르거나 무늬 형성","주걱이나 헤라 사용. 대표가 **안티스터코 도장**."]]},{"kind":"steps","head":"안티스터코 도장의 순서","steps":["1 **올퍼티** 작업으로 면을 정리해요.","2 **정판** 에 도장재를 얹어요. 정판은 퍼티를 덜어 놓는 받침판이에요.","3 **주걱(spatula)** 으로 패턴을 만들면서 마감해요."],"answer":"올퍼티로 면 정리 → 정판에 도장재 → 주걱으로 패턴"},{"kind":"points","head":"슬라이드의 보충 설명","items":["**에어 스프레이** 는 압축공기로 도료를 잘게 쪼개 뿜는 방식이에요.","보라색 글씨: 뿜칠이라고도 한다. 외벽은 대기환경 오염으로 금지되어 있다.","오른쪽 사진은 **안티스터코 도장** 으로 마감한 벽이에요. 은은한 얼룩 무늬가 보여요.","공사 순서로는 바탕 만들기와 하도가 끝난 뒤, 마지막 마감 칠에 쓰는 도구 이야기예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"최종 도장 뒤 잔손보기처럼 아주 부분적인 도장에 주로 쓰는 용구는?","choices":["붓","롤러 브러쉬","에어 스프레이","주걱"],"a":0,"why":"붓은 좁은 면적, 모서리, 몰딩, 보수도장 같은 세밀한 작업용이에요. **잔손보기** 에 써요."},{"kind":"check","q":"올퍼티로 면을 정리한 뒤 주걱으로 패턴을 만들며 마감하는 대표적인 도장은?","choices":["분체도장","안티스터코 도장","다채무늬 도장","롤러 도장"],"a":1,"why":"**주걱(spatula)** 에 의한 도장의 대표가 **안티스터코 도장** 이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["본문은 '**안티스터코 도장**', 영상 링크 제목은 '안티코 스타코' 로 표기가 달라요. 본문 표기를 기준으로 외워요.","슬라이드 제목은 '롤러 브러시 도장', 용어집 표기는 '**롤러 브러쉬**' 예요. 같은 도구예요.","**에어 스프레이** = 뿜칠. 외벽은 대기환경 오염으로 금지예요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.8958,0.1582],"c":[0,0.0208,0.9853,0.1902],"r":9.2095,"img":"img/L5/walk/p039_h.jpg"},"parts":[{"b":[0.027,0.197,0.566,0.123],"c":[0,0.181,0.6226,0.155],"r":7.1409,"img":"img/L5/walk/p039_23_01.jpg","say":"붓 도장. 세밀한 작업, 최종 도장 뒤 잔손보기 작업에 써요."},{"b":[0.027,0.336,0.505,0.08],"c":[0.0018,0.3199,0.5555,0.1122],"r":8.8017,"img":"img/L5/walk/p039_23_02.jpg","say":"롤러 브러시 도장. 넓은 면적을 빠르고 균일하게, 주로 수성페인트."},{"b":[0.027,0.429,0.516,0.079],"c":[0.0012,0.4112,0.5676,0.1147],"r":8.7974,"img":"img/L5/walk/p039_23_03.jpg","say":"에어 스프레이 도장과 보라색 보충 설명(뿜칠, 외벽 금지)이에요."},{"b":[0.027,0.523,0.509,0.175],"c":[0.0015,0.507,0.5599,0.207],"r":4.8086,"img":"img/L5/walk/p039_23_04.jpg","say":"주걱에 의한 도장. 대표가 안티스터코 도장이에요."},{"b":[0.695,0.223,0.285,0.745],"c":[0.6781,0.1805,0.3187,0.8195],"r":0.6914,"img":"img/L5/walk/p039_23_05.jpg","say":"안티스터코 도장으로 마감한 벽 사진이에요."}]}},{"p":40,"title":"칠 공정과 견본품: 칠하기 전에 미리 칠해 보기","terms":["칠 견본","도장공사"],"pass1":[{"kind":"say","lines":["본 칠을 하기 전에 작은 판에 미리 칠해 보는 것이 **칠 견본** 이에요.","옷을 사기 전에 입어 보는 것과 같아요.","**도장공사** 의 기타 사항 첫 번째 이야기예요."]}],"pass2":[{"kind":"points","head":"칠 공정과 견본품 4가지","items":["1) 페인트 도장 작업은 실제로 시공하기에 앞서 견본 작업이 필요해요.","2) 바탕면의 재질, 크기에 따라 색이 달라 보일 수 있어요.","3) **칠 견본** 을 작업해 빛깔과 광택 등을 확인하는 것이 좋아요.","4) **칠 견본** 은 변색되지 않게 보존해 둬요."]},{"kind":"points","head":"공사 순서의 자리","items":["**칠 견본** 은 본 도장보다 먼저예요. 색과 광택을 정한 뒤 본 칠에 들어가요.","사진 캡션: 특히 프랜차이즈 브랜드 인테리어 시, 도장 샘플 작업은 매우 중요한 과정이에요.","보존해 둔 견본은 나중에 칠한 색이 맞는지 비교하는 기준이 돼요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"칠 견본에 대한 설명으로 틀린 것은?","choices":["실제 시공에 앞서 견본 작업을 한다","바탕면의 재질, 크기에 따라 색이 달라 보일 수 있다","빛깔과 광택 등을 확인한다","확인이 끝나면 칠 견본은 바로 버린다"],"a":3,"why":"**칠 견본** 은 변색되지 않게 보존해 둬요."}],"walk":{"head":{"b":[0.0092,0.0368,0.2474,0.0602],"c":[0,0.0208,0.2722,0.0922],"r":5.2485,"img":"img/L5/walk/p040_h.jpg"},"parts":[{"b":[0.027,0.197,0.339,0.174],"c":[0.0101,0.181,0.3729,0.206],"r":3.2181,"img":"img/L5/walk/p040_22_01.jpg","say":"칠 공정과 견본품 4가지 문장이에요."},{"b":[0.635,0.099,0.236,0.279],"c":[0.623,0.083,0.26,0.311],"r":1.4862,"img":"img/L5/walk/p040_22_02.jpg","say":"색상 견본 부채. 색을 고를 때 펼쳐 보는 색표예요."},{"b":[0.061,0.462,0.868,0.363],"c":[0.0176,0.4438,0.9548,0.3993],"r":4.251,"img":"img/L5/walk/p040_22_03.jpg","say":"판에 미리 칠해 본 도장 샘플 사진이에요."},{"b":[0.075,0.835,0.369,0.037],"c":[0.0566,0.7985,0.4059,0.11],"r":6.56,"img":"img/L5/walk/p040_22_04.jpg","say":"프랜차이즈 브랜드 인테리어 시 도장 샘플 작업이 매우 중요하다는 캡션이에요."}]}},{"p":41,"title":"우리나라에서 많이 쓰는 페인트 브랜드","terms":["도료"],"pass1":[{"kind":"say","lines":["우리나라에서 많이 쓰는 페인트 브랜드를 소개하는 쪽이에요.","**도료** 를 고를 때 현장에서 자주 듣는 이름들이에요."]}],"pass2":[{"kind":"points","head":"브랜드 목록","items":["1) 벤자민 무어","2) 던 에드워드","3) 그 외 국내 브랜드: 노루 페인트, 삼화 페인트, KCC, 제비표 페인트","가운데 캔 사진에는 'Interior Low Sheen Paint' 라고 적혀 있어요. 실내용 저광 **도료** 라는 뜻이에요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":{"b":[0.0092,0.0368,0.2758,0.1515],"c":[0,0.0208,0.3034,0.1835],"r":2.9394,"img":"img/L5/walk/p041_h.jpg"},"parts":[{"b":[0.104,0.241,0.279,0.615],"c":[0.09,0.2102,0.3069,0.6765],"r":0.8065,"img":"img/L5/walk/p041_21_01.jpg","say":"벤자민 무어 로고와 매장 사진이에요."},{"b":[0.409,0.241,0.229,0.615],"c":[0.392,0.2102,0.2631,0.6765],"r":0.6914,"img":"img/L5/walk/p041_21_02.jpg","say":"던 에드워드 로고와 SUPREMA Interior Low Sheen Paint 캔 사진이에요."},{"b":[0.675,0.241,0.174,0.607],"c":[0.6322,0.2107,0.2597,0.6677],"r":0.6915,"img":"img/L5/walk/p041_21_03.jpg","say":"그 외 국내 브랜드: 노루, 삼화, KCC, 제비표(JEVISCO)예요."}]}},{"p":42,"title":"에그쉘 광: 계란 껍질 정도의 은은한 광택","terms":["eggshell","광도"],"pass1":[{"kind":"say","lines":["**에그쉘 광(eggshell)** 은 계란 껍질처럼 은은하게 반짝이는 정도예요.","너무 번쩍이지도, 아주 칙칙하지도 않은 중간이에요.","집 안 벽에 가장 많이 쓰는 광택이에요."]}],"pass2":[{"kind":"points","head":"에그쉘 광의 뜻","items":["말 그대로 계란 껍질 정도의 광택을 뜻해요.","은은한 광택으로 고급스럽게 마감돼서 홈 인테리어용 페인트로 가장 많이 이용되는 **광도** 예요.","**광도** 는 도장면이 반짝이는 정도예요. 무광부터 유광까지 나눠요.","사진은 위에서부터 무광, 저광, 반광, 유광 순서로 칠한 판이에요."]},{"kind":"compare","head":"5-2 의 광도표(p5) 다시 보기","cols":["광도","광택","쓰는 곳"],"rows":[["무광(FLAT)","~5%","벽체, 천장"],["벨벳광(VELVET)","5~9%","침실"],["계란광(반무광, EGGSHELL)","10~15%","벽체, 거실, 아이방"],["저광(LOW SHEEN)","20~25%","주방"],["반광(SEMI-GLOSS)","40~50%","주방, 욕실, 방문, 몰딩, 가구"],["유광(고광, GLOSS)","70~80%","싱크대, 방문, 문틀"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"홈 인테리어용 페인트로 가장 많이 이용되는, 계란 껍질 정도의 은은한 광택은?","choices":["무광","에그쉘 광","반광","유광"],"a":1,"why":"**에그쉘 광(eggshell)** 이에요. 은은한 광택으로 고급스럽게 마감돼요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["이 쪽은 '저광 정도의 광택을 에그쉘 광이라고 한다' 고 해요.","그런데 p5 광도표는 계란광(반무광, EGGSHELL) 10~15% 와 저광(LOW SHEEN) 20~25% 를 다른 칸으로 둬요.","두 쪽이 서로 맞지 않으니 둘 다 알아 두세요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1904,0.1515],"c":[0,0.0208,0.2144,0.1835],"r":2.0771,"img":"img/L5/walk/p042_h.jpg"},"parts":[{"b":[0.027,0.209,0.459,0.08],"c":[0.004,0.193,0.5049,0.112],"r":8.0143,"img":"img/L5/walk/p042_22_01.jpg","say":"계란 껍질 정도의 광택, 홈 인테리어용으로 가장 많이 쓰는 광도라는 두 줄이에요."},{"b":[0.037,0.315,0.485,0.622],"c":[0.0127,0.2839,0.5335,0.6842],"r":1.3862,"img":"img/L5/walk/p042_22_02.jpg","say":"무광, 저광, 반광, 유광을 나란히 칠해 비교한 사진이에요."},{"b":[0.599,0.497,0.107,0.063],"c":[0.5525,0.4735,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p042_22_03.jpg","say":"저광 정도의 광택을 에그쉘 광이라고 한다는 화살표 설명이에요."}]}},{"p":43,"title":"[문제풀이] 1. 총론: 턴키, 감리자, 도급, 공사비 구성","terms":["Turn-key","construction supervisor","일식도급","분할도급","공동도급","직접공사비","간접공사비","순공사비","현장경비","공사원가","일반관리비"],"pass1":[{"kind":"say","lines":["여기서부터 11쪽은 1강부터 5강까지의 복습 문제예요.","문제 모양이 그대로 시험 모양의 본보기예요.","첫 쪽은 1. 총론. 공사 한 건의 사람, 방식, 돈 이야기예요."]},{"kind":"say","lines":["주문 1 기억나요? 사람 → 방식 → 입찰 → 계획 → 관리 → 준공.","**감리자(construction supervisor)** 는 사람, **턴키(Turn-key)** 와 도급은 방식, 공사비 표는 계획이에요."]}],"pass2":[{"kind":"points","head":"문제 1), 2): 정의 쓰기","items":["**턴키(Turn-key)**: 프로젝트의 모든 요소를 도급자가 일괄 처리하여 주문자에게 인도하는 도급계약 방식.","열쇠(key)만 돌리면(turn) 바로 쓸 수 있게 넘겨 준다는 뜻이에요.","**감리자(construction supervisor)**: 설계자가 작성한 설계도면에 맞게 공사가 적법하게 시행되는지 관리 감독하는 자.","공사 게임에 비유하면 심사위원이에요."]},{"kind":"compare","head":"문제 3): 도급 방식 빈칸","cols":["빈칸","설명","답"],"rows":[["①","한 공사 전부를 도급자에게 맡겨 공사 일체를 시행","**일식도급**"],["②","공사를 공종별로 나누어 따로 도급계약","**분할도급**"],["③","2개 이상 시공사에게 도급해 기술, 자본, 위험 부담을 분산","**공동도급**"]]},{"kind":"steps","head":"문제 4): 공사비 구성표를 안에서 밖으로","steps":["1 맨 안쪽 **직접공사비** = 재료비 + 노무비 + 외주비 + 경비","2 **직접공사비** + ④ **간접공사비** → **순공사비**","3 **순공사비** + ③ **현장경비** → **공사원가**","4 **공사원가** + ② **일반관리비** + ① 이윤 → 공사비"],"answer":"① 이윤 ② 일반관리비 ③ 현장경비 ④ 간접공사비"},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"기출 모양 연습문제","q":"공사비 구성을 나타낸 표의 빈칸 ①~④ 를 채우시오. (공사비 ⊃ 공사원가 ⊃ 순공사비 ⊃ 직접공사비)","qko":"공사비 양파의 껍질 이름을 안에서부터 채우는 문제예요.","solve":["직접공사비 바로 바깥, 순공사비 안의 빈칸 ④ 는 **간접공사비**.","순공사비 바깥, 공사원가 안의 빈칸 ③ 은 **현장경비**.","공사원가 바깥, 공사비 안의 빈칸 ② 는 **일반관리비**.","맨 바깥 마지막에 붙는 ① 은 이윤."],"answer":"① 이윤 ② 일반관리비 ③ 현장경비 ④ 간접공사비"},{"kind":"english","head":"답안에 쓸 문장: 턴키","en":"턴키 도급계약제도는 프로젝트의 모든 요소를 도급자가 일괄 처리하여 주문자에게 인도하는 도급계약 방식이다.","ko":"핵심어는 '모든 요소', '일괄 처리', '인도' 세 개예요.","tip":"열쇠를 돌려(turn key) 바로 쓰게 넘겨 준다고 떠올려요."},{"kind":"english","head":"답안에 쓸 문장: 감리자","en":"공사 감리자는 설계자가 작성한 설계도면에 맞게 공사가 적법하게 시행되는지 관리 감독하는 자이다.","ko":"'설계도면에 맞게', '적법하게', '관리 감독' 을 빠뜨리지 않아요.","tip":"감리자 = 심사위원. 도면이라는 채점표를 들고 지켜봐요."},{"kind":"check","q":"공사를 공종별로 나누어 따로 도급계약을 맺는 방식은?","choices":["일식도급","분할도급","공동도급","턴키"],"a":1,"why":"나누어(분할) 맺으니 **분할도급** 이에요. 전부 맡기면 **일식도급**, 여러 회사가 함께면 **공동도급**."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["이 표에는 총원가 칸이 따로 없어요. 2강 주문 3 으로는 **공사원가** + **일반관리비** = 총원가, 여기에 이윤을 더해요.","주문 3: 재노외경 → 간접 → 현장 → 일반 → 이윤. 안에서 밖으로, 현장에서 본사로 멀어져요.","**현장경비** 는 현장, **일반관리비** 는 본사. 자리를 바꿔 쓰지 않아요."]}],"walk":{"head":{"b":[0.002,0.0137,0.1761,0.1403],"c":[0,0,0.2001,0.1723],"r":2.0646,"img":"img/L5/walk/p043_h.jpg"},"parts":[{"b":[0.039,0.203,0.424,0.093],"c":[0.0178,0.187,0.4664,0.125],"r":6.6332,"img":"img/L5/walk/p043_23_01.jpg","say":"문제 1) 턴키의 답. 도급자가 일괄 처리하여 주문자에게 인도."},{"b":[0.039,0.393,0.383,0.096],"c":[0.0199,0.377,0.4213,0.128],"r":5.8514,"img":"img/L5/walk/p043_23_02.jpg","say":"문제 2) 감리자의 답. 설계도면대로 적법하게 시행되는지 관리 감독하는 자."},{"b":[0.039,0.581,0.409,0.306],"c":[0.0186,0.565,0.4499,0.338],"r":2.3663,"img":"img/L5/walk/p043_23_03.jpg","say":"문제 3) 빈칸과 답. 일식도급, 분할도급, 공동도급."},{"b":[0.58,0.263,0.313,0.273],"c":[0.5643,0.247,0.3443,0.305],"r":2.0068,"img":"img/L5/walk/p043_23_04.jpg","say":"문제 4) 공사비 구성표. 안쪽 직접공사비부터 바깥 공사비까지."},{"b":[0.58,0.561,0.313,0.055],"c":[0.5643,0.5335,0.3443,0.11],"r":5.5644,"img":"img/L5/walk/p043_23_05.jpg","say":"표 빈칸의 답. 이윤, 일반 관리비, 현장경비, 간접공사비."}]}},{"p":44,"title":"[문제풀이] 2. 가설공사: 강관틀비계, 강관비계 기준, 쌍줄비계 면적","terms":["가설공사","비계","강관틀비계","조립식 비계","가새","강관비계","띠장","장선","쌍줄비계","이격거리"],"pass1":[{"kind":"say","lines":["2. **가설공사** 복습이에요. **비계**, 즉 높은 곳 작업용 임시 발판 이야기예요.","이 쪽에는 복습 문제 가운데 하나뿐인 계산 문제, **쌍줄비계** 면적 구하기가 나와요."]},{"kind":"analogy","head":"쌍줄비계 = 건물에 두른 두 겹 울타리","scene":"건물 둘레에 울타리를 두 줄로 두른다고 생각해요. 울타리는 벽에서 조금 떨어져 있어서 건물 둘레보다 조금 더 길어요.","map":[["두 줄 울타리","**쌍줄비계**"],["벽과 울타리 사이 틈","**이격거리**"],["울타리 높이","H (건물 높이)"],["울타리 넓이","비계 면적"]]}],"pass2":[{"kind":"points","head":"문제 1): 강관틀비계의 중요부품 3가지","items":["답: ① 수평틀 ② 세로틀 ③ 교차가세","**강관틀비계** 는 실내 시공에서 틀을 간단히 조립해 쓰는 비계예요.","2강 p78 **조립식 비계**(이동 틀비계) 부속품에도 세로틀, 수평틀(띠장틀), 교차 가세가 있어요.","교차가세는 X자로 걸어 흔들림을 잡아요. 2강의 **가새** 와 같은 일을 하는 부재예요."]},{"kind":"compare","head":"문제 2): 강관파이프비계 설치 기준 (2강 p73 강관비계)","cols":["항목","기준"],"rows":[["기둥 간격, **띠장** 방향","1.85m 이하"],["기둥 간격, **장선** 방향","1.5m 이하"],["**띠장** 의 간격","2m 이하"],["기둥과 기둥 사이 적재하중","400kg 이하"]]},{"kind":"points","head":"쌍줄비계 면적 공식 (*실건기 표시)","items":["**쌍줄비계**: 건물 주위에 2겹으로 비계를 만드는 것.","**이격거리** 는 0.9m(90cm)예요.","면적 = (건물 둘레 길이 + 0.9 × 8) × H = (건물 둘레 길이 + 7.2) × H","H 는 건물 높이, 건물 둘레 길이 = 2(a + b)예요."]},{"kind":"steps","head":"왜 0.9m가 8개일까요","steps":["1 비계는 벽에서 0.9m 떨어져서 건물을 둘러요.","2 그래서 비계의 한 변은 건물 한 변보다 양 끝에서 0.9m씩 길어져요.","3 변이 4개, 끝이 2개씩이니 0.9m가 4 × 2 = 8개예요.","4 슬라이드 그림의 모서리 번호 ①~⑧ 이 바로 그 8개예요."],"answer":"비계 둘레 = 2(a + b) + 0.9 × 8 = 2(a + b) + 7.2"},{"kind":"steps","head":"예제: a = 10m, b = 6m, H = 9m","steps":["1 건물 둘레 길이 = 2(10 + 6) = 32m","2 비계 둘레 = 32 + 7.2 = 39.2m","3 면적 = 39.2 × 9 = 352.8"],"answer":"352.8㎡ (단위 꼭 적기)"},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"기출 모양 연습문제","q":"강관파이프비계 설치 기준: 기둥 간격 띠장 방향 (①)m 이하, 장선 방향 (②)m 이하, 띠장 간격 (③)m 이하, 기둥 사이 적재하중 (④)kg 이하.","qko":"강관비계의 숫자 네 개를 채우는 빈칸 문제예요.","solve":["**띠장** 방향(앞에서 본 긴 가로 방향) 기둥 간격은 1.85m 이하.","**장선** 방향(두께 방향) 기둥 간격은 1.5m 이하.","**띠장** 사이 높이 간격은 2m 이하.","기둥과 기둥 사이 적재하중은 400kg 이하."],"answer":"① 1.85 ② 1.5 ③ 2 ④ 400"},{"kind":"check","q":"쌍줄비계 면적 공식에서 건물 둘레 길이에 더하는 값은?","choices":["0.9","1.8","3.6","7.2"],"a":3,"why":"**이격거리** 0.9m가 8개라서 0.9 × 8 = 7.2 를 더해요."},{"kind":"english","head":"답안 쓰는 규칙","en":"쌍줄비계 면적 A = H × {2(a + b) + 0.9 × 8}, 답에는 단위 ㎡ 를 적고, 1,000 단위마다 콤마를 찍는다.","ko":"답이 딱 안 떨어지면 소수점 셋째 자리에서 반올림해 둘째 자리까지 적어요.","tip":"단위, 콤마, 반올림. 세 가지를 마지막에 꼭 점검해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**강관틀비계** 부품 이름은 2강 **조립식 비계** 부속품(세로틀, 수평틀, 교차 가세)과 같아요.","슬라이드 '소수점 셋째 짜리' 는 '자리' 의 오타예요.","'교차가세' 는 흔히 '교차가새' 로 쓰는 부품 이름이에요(슬라이드 밖 내용).","글은 이격거리를 '2겹 사이의 거리' 라고 했지만, 그림은 건축물과 비계 사이를 이격거리로 그렸어요.","어느 쪽으로 읽어도 계산은 같아요. 건물 둘레에 0.9 × 8 = 7.2 를 더해요."]}],"walk":{"head":{"b":[0.002,0.0137,0.8405,0.1671],"c":[0,0,0.9246,0.1991],"r":8.2558,"img":"img/L5/walk/p044_h.jpg"},"parts":[{"b":[0.087,0.19,0.179,0.057],"c":[0.075,0.1635,0.203,0.11],"r":3.2808,"img":"img/L5/walk/p044_25_01.jpg","say":"문제 1) 답. 수평틀, 세로틀, 교차가세."},{"b":[0.546,0.188,0.277,0.184],"c":[0.5322,0.172,0.3047,0.216],"r":2.5078,"img":"img/L5/walk/p044_25_02.jpg","say":"문제 2) 강관파이프비계 설치 기준의 빈칸 네 개예요."},{"b":[0.55,0.397,0.175,0.056],"c":[0.5375,0.37,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p044_25_03.jpg","say":"문제 2) 답. 1.85, 1.5, 2, 400."},{"b":[0.524,0.497,0.359,0.076],"c":[0.506,0.48,0.3949,0.11],"r":6.3822,"img":"img/L5/walk/p044_25_04.jpg","say":"쌍줄비계 면적 공식. 건물 둘레 길이에 7.2 를 더해 H 를 곱해요."},{"b":[0.361,0.721,0.139,0.239],"c":[0.3305,0.705,0.2,0.271],"r":1.312,"img":"img/L5/walk/p044_25_05.jpg","say":"모서리 번호 ①~⑧. 0.9m가 8개라는 그림이에요."},{"b":[0.704,0.647,0.191,0.193],"c":[0.692,0.631,0.215,0.225],"r":1.6988,"img":"img/L5/walk/p044_25_06.jpg","say":"예제 a=10, b=6, H=9. 정답 352.8㎡, 단위 꼭 적기."}]}},{"p":45,"title":"[문제풀이] 2. 가설공사: 꺾인 평면의 쌍줄비계 면적","terms":["쌍줄비계","이격거리","Floor Plan"],"pass1":[{"kind":"say","lines":["앞 쪽 **쌍줄비계** 공식을 진짜 시험 문제처럼 두 번 써 보는 쪽이에요.","건물이 ㄱ자처럼 꺾여 있어도 바깥 큰 네모의 가로, 세로만 쓰면 돼요."]},{"kind":"points","head":"푸는 순서 세 줄","items":["1 가로 a, 세로 b, 높이 H 를 찾아요.","2 건물 둘레 2(a + b) 에 7.2 를 더해요.","3 높이 H 를 곱하고 단위 ㎡ 를 붙여요."]}],"pass2":[{"kind":"points","head":"꺾인 평면도에서 a, b 읽기","items":["**평면도(Floor Plan)** 는 위에서 내려다본 그림이에요.","ㄱ자로 꺾인 건물도 둘레 길이는 바깥 큰 네모와 같아요.","안으로 들어간 계단 모양 변을 밖으로 밀어 펴면 큰 네모가 되기 때문이에요.","문제 3): a = 37m (25 + 12), b = 15m (5 + 10), H = 25m","문제 4): a = 40m (25 + 15), b = 20m (5 + 15). H 는 그림에 직접 없어요."]},{"kind":"steps","head":"문제 3) 풀이","steps":["1 a = 25 + 12 = 37m, b = 5 + 10 = 15m","2 건물 둘레 길이 = 2(37 + 15) = 2 × 52 = 104m","3 비계 둘레 = 104 + 7.2 = 111.2m","4 A = 25 × 111.2 = 2,780"],"answer":"A = 2,780㎡"},{"kind":"steps","head":"문제 4) 풀이","steps":["1 a = 25 + 15 = 40m, b = 5 + 15 = 20m","2 H = 층고 3.6m × 5층 = 18m","3 건물 둘레 길이 = 2(40 + 20) = 2 × 60 = 120m","4 비계 둘레 = 120 + 7.2 = 127.2m","5 A = 18 × 127.2 = 2,289.6"],"answer":"A = 2,289.6㎡"},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"기출 모양 연습문제","q":"평면도(전체 37m × 15m, H = 25m)에서 쌍줄비계를 설치할 때 외부비계 면적(A)을 산출하시오.","qko":"꺾인 건물의 비계 넓이를 공식으로 구하는 계산 문제예요.","solve":["a = 37m, b = 15m (전체 치수를 써요).","건물 둘레 2(37 + 15) = 104m.","**이격거리** 몫 7.2 를 더해 104 + 7.2 = 111.2m.","높이를 곱해 25 × 111.2 = 2,780."],"answer":"A = 2,780㎡"},{"kind":"check","q":"문제 4) 에서 공식에 넣는 H 는?","choices":["3.6m","15m","18m","20m"],"a":2,"why":"층고 3.6m × 5층 = 18m 예요. 20m 는 세로 b 예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["문제 4) 풀이 둘째 줄 'A=18{2(40+20)+0.9*8]' 은 괄호 짝이 안 맞아요. 값은 맞아요.","층이 그려진 문제는 H 를 층고 × 층수로 먼저 구해요.","a, b 에 25m, 5m 같은 부분 치수를 넣지 않아요. 전체 치수(37, 15 / 40, 20)를 써요."]}],"walk":{"head":{"b":[0.002,0.0137,0.8466,0.2449],"c":[0,0,0.9313,0.2769],"r":5.9792,"img":"img/L5/walk/p045_h.jpg"},"parts":[{"b":[0.093,0.282,0.293,0.254],"c":[0.0784,0.266,0.3223,0.286],"r":2.0034,"img":"img/L5/walk/p045_23_01.jpg","say":"문제 3) 평면도. 전체 가로 37m, 전체 세로 15m, H = 25m."},{"b":[0.14,0.612,0.162,0.273],"c":[0.121,0.596,0.2,0.305],"r":1.1658,"img":"img/L5/walk/p045_23_02.jpg","say":"문제 3) 풀이. A = 25 × 111.2 = 2,780㎡."},{"b":[0.477,0.282,0.306,0.302],"c":[0.4617,0.266,0.3366,0.334],"r":1.7916,"img":"img/L5/walk/p045_23_03.jpg","say":"문제 4) 평면도. 전체 가로 40m, 전체 세로 20m."},{"b":[0.8,0.35,0.094,0.234],"c":[0.747,0.334,0.2,0.266],"r":1.3367,"img":"img/L5/walk/p045_23_04.jpg","say":"1층~5층, 층고 3.6m. H = 3.6 × 5 = 18m 를 여기서 읽어요."},{"b":[0.601,0.613,0.163,0.273],"c":[0.5825,0.597,0.2,0.305],"r":1.1658,"img":"img/L5/walk/p045_23_05.jpg","say":"문제 4) 풀이. A = 18 × 127.2 = 2,289.6㎡."}]}},{"p":46,"title":"[문제풀이] 3. 경량철골공사: 천장틀 구성 그림","terms":["경량철골","인서트","hanger bolt","행거 클립","carrying channel","Minor Channel","M-Bar 클립","M-Bar"],"pass1":[{"kind":"say","lines":["3. **경량철골** 공사 복습이에요. 이 쪽은 천장틀 그림 한 장이에요.","주문 5 '위에서 아래로 매달기' 를 그림으로 다시 확인해요."]},{"kind":"analogy","head":"천장틀 = 천장에 매다는 옷걸이","scene":"천장에 줄을 달고, 굵은 막대를 걸고, 가는 막대를 촘촘히 건 다음 옷(판)을 거는 모습이에요.","map":[["줄","**달대 볼트(hanger bolt)**"],["굵은 막대","**캐링 채널(carrying channel)**"],["가는 막대","**M-Bar**"],["옷","천장판"]]}],"pass2":[{"kind":"compare","head":"그림 라벨과 3강 용어 맞추기","cols":["그림 라벨","3강 용어","하는 일"],"rows":[["인서어트(앵커)","**인서트**","슬라브에 미리 묻어 둔 철물, 볼트를 걸 자리"],["달볼트(달대)","**달대 볼트(hanger bolt)**","천장틀을 위에서 매달아 내리는 볼트"],["조절행거","**행거 클립**","볼트와 캐링 채널을 고정하고 높이를 맞춤"],["캐링찬넬(반자틀받이)","**캐링 채널(carrying channel)**","천장틀의 굵은 주 골조"],["마이너찬넬","**마이너 채널(Minor Channel)**","캐링 채널과 직교해 묶는 보강 채널"],["크립","클립(**M-Bar 클립**)","캐링 채널과 M-Bar 를 연결"],["MS-BAR, MW-BAR(반자틀)","**M-Bar**","천장판을 나사로 박는 가는 틀"],["지정 반자널(천정판/텍스)","천장 마감판","맨 아래에 붙이는 판"]]},{"kind":"steps","head":"그림을 위에서 아래로 읽기","steps":["1 **인서트**: 슬라브 속에 묻힌 자리","2 **달대 볼트(hanger bolt)**: 아래로 내리는 줄","3 조절행거(**행거 클립**): 볼트 끝에서 높이 조절","4 **캐링 채널(carrying channel)**: 굵은 뼈","5 클립(**M-Bar 클립**): 굵은 뼈와 가는 뼈를 물림","6 **M-Bar**: 가는 뼈","7 천장판: 맨 아래 옷"],"answer":"다음 쪽 문제 1) 의 설치 순서와 똑같아요."},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"그림의 '캐링찬넬(반자틀받이)' 은 3강의 어느 부재인가요?","choices":["캐링 채널","마이너 채널","M-Bar","달대 볼트"],"a":0,"why":"같은 부재예요. 3강 표기는 **캐링 채널(carrying channel)** 이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["그림 표기 '캐링찬넬', '마이너찬넬', '크립', '인서어트', '천정판' 은 3강 표기와 달라요.","3강 표기로는 **캐링 채널(carrying channel)**, **마이너 채널(Minor Channel)**, 클립, **인서트**, 천장판이에요.","모두 같은 부재예요. 외울 때는 3강 표기를 기준으로 해요."]}],"walk":{"head":{"b":[0.002,0.0137,0.1345,0.1403],"c":[0,0,0.2,0.1723],"r":2.0636,"img":"img/L5/walk/p046_h.jpg"},"parts":[{"b":[0.049,0.251,0.16,0.109],"c":[0.029,0.235,0.2,0.141],"r":2.5217,"img":"img/L5/walk/p046_22_01.jpg","say":"달볼트(달대)와 조절행거. 천장틀을 매다는 줄과 높이 조절 부속이에요."},{"b":[0.2,0.216,0.104,0.058],"c":[0.152,0.19,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p046_22_02.jpg","say":"캐링찬넬(반자틀받이). 3강 표기로는 캐링 채널이에요."},{"b":[0.357,0.216,0.168,0.109],"c":[0.341,0.2,0.2,0.141],"r":2.5217,"img":"img/L5/walk/p046_22_03.jpg","say":"크립과 마이너찬넬. 3강 표기로는 클립, 마이너 채널이에요."},{"b":[0.146,0.604,0.211,0.066],"c":[0.134,0.582,0.235,0.11],"r":3.798,"img":"img/L5/walk/p046_22_04.jpg","say":"MS-BAR, MW-BAR(반자틀). 판을 박는 M-Bar 예요."},{"b":[0.443,0.571,0.111,0.063],"c":[0.3985,0.5475,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p046_22_05.jpg","say":"지정 반자널(천정판/텍스). 맨 아래 마감판이에요."},{"b":[0.086,0.755,0.159,0.133],"c":[0.0655,0.739,0.2,0.165],"r":2.1549,"img":"img/L5/walk/p046_22_06.jpg","say":"인서어트(앵커)와 달볼트. 슬라브 속 인서트에 볼트를 걸어요."}]}},{"p":47,"title":"[문제풀이] 3. 경량철골공사: 천장틀 설치 순서와 M-Bar 용도","terms":["인서트","hanger bolt","행거 클립","carrying channel","M-Bar 클립","M-Bar"],"pass1":[{"kind":"say","lines":["천장틀 순서 맞추기와 짝 맞추기 문제예요.","'위에서 아래로 매달기' 그대로 순서를 세우면 돼요.","슬라브 속 **인서트** 가 맨 위, 천장판이 맨 아래예요."]}],"pass2":[{"kind":"steps","head":"문제 1) 경량철골 천장틀 설치 순서","steps":["⑥ 인서트: 슬라브에 박힌 **인서트** 자리부터","① 달대 볼트: **달대 볼트(hanger bolt)** 를 걸어 내리고","④ 조절 행거(헹거 클립): 볼트 끝에 **행거 클립** 을 달고","③ 캐링찬넬: **캐링 채널(carrying channel)** 을 걸고","② 클립: **M-Bar 클립** 을 끼우고","⑤ M-BAR: **M-Bar** 를 물리고","⑦ 천장 마감판: 마지막에 판을 붙여요"],"answer":"6 - 1 - 4 - 3 - 2 - 5 - 7"},{"kind":"compare","head":"문제 2) 사용 용도 연결","cols":["부분","부재","그림에서 보면"],"rows":[["(가) 천장판 연결부분","(3) Double M-Bar","판 두 장이 만나는 이음 아래에 있어요"],["(나) 천장판 중간부분","(2) Single M-Bar","판 한 장의 가운데를 받쳐요"],["(다) M-BAR와 캐링찬넬 연결부분","(1) Clip","굵은 뼈와 가는 뼈를 물려요"]]},{"kind":"points","head":"3강 숫자와 이어 보기","items":["3강 상세도에서 **M-Bar** 싱글은 폭 25, 더블은 폭 50 이었어요.","더블이 넓어서 판 두 장의 끝을 함께 받치는 이음 자리에 와요.","**M-Bar** 는 300mm 간격, **캐링 채널(carrying channel)** 은 900mm 간격이었어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"기출 모양 연습문제","q":"경량철골 천장틀 설치 순서를 나열하시오. ① 달대 볼트 ② 클립 ③ 캐링찬넬 ④ 조절 행거 ⑤ M-BAR ⑥ 인서트 ⑦ 천장 마감판","qko":"천장을 위에서 아래로 매다는 순서대로 번호를 놓는 문제예요.","solve":["맨 위는 슬라브 속 ⑥ **인서트**.","거기에 ① **달대 볼트(hanger bolt)** 를 걸고 ④ 조절 행거를 달아요.","③ **캐링 채널(carrying channel)** 을 걸고 ② 클립으로 ⑤ **M-Bar** 를 물려요.","마지막은 ⑦ 천장 마감판."],"answer":"6 - 1 - 4 - 3 - 2 - 5 - 7"},{"kind":"check","q":"천장판 연결부분에 쓰는 것은?","choices":["Clip","Single M-Bar","Double M-Bar","캐링 채널"],"a":2,"why":"이음 자리는 Double M-Bar, 판 가운데는 Single M-Bar, 두 부재 연결은 Clip 이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["보기의 '헹거 클립' 은 '**행거 클립**' 과 같은 말이에요. 표기가 섞여 있어요.","'조절 행거' 와 '행거 클립' 이 같은 칸에 묶여 있어요. 둘 다 같은 자리의 부속이에요.","**인서트** 가 맨 앞, 천장 마감판이 맨 끝. 위에서 아래로예요."]}],"walk":{"head":{"b":[0.002,0.0137,0.4738,0.1876],"c":[0,0,0.5212,0.2196],"r":4.2194,"img":"img/L5/walk/p047_h.jpg"},"parts":[{"b":[0.043,0.213,0.541,0.098],"c":[0.0159,0.197,0.5951,0.13],"r":8.1381,"img":"img/L5/walk/p047_23_01.jpg","say":"문제 1) 보기. 달대 볼트부터 천장 마감판까지 일곱 가지예요."},{"b":[0.043,0.327,0.161,0.053],"c":[0.0235,0.2985,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p047_23_02.jpg","say":"문제 1) 답. 6 - 1 - 4 - 3 - 2 - 5 - 7."},{"b":[0.043,0.492,0.411,0.141],"c":[0.0225,0.476,0.4521,0.173],"r":4.6459,"img":"img/L5/walk/p047_23_03.jpg","say":"문제 2) 보기. 세 부분과 세 부재를 짝지어요."},{"b":[0.043,0.643,0.187,0.053],"c":[0.031,0.6145,0.211,0.11],"r":3.4101,"img":"img/L5/walk/p047_23_04.jpg","say":"문제 2) 답. (가)-(3), (나)-(2), (다)-(1)."},{"b":[0.032,0.73,0.525,0.237],"c":[0.0057,0.714,0.5775,0.269],"r":3.8166,"img":"img/L5/walk/p047_23_05.jpg","say":"참고 그림. 연결부분 Double M-bar, 중간부분 Single M-bar, 크립."}]}},{"p":48,"title":"[문제풀이] 3. 경량철골공사: T-Bar 장점과 코너 비드","terms":["T-Bar","Corner Bead","M-Bar"],"pass1":[{"kind":"say","lines":["**T-Bar** 의 장점과 **코너 비드(Corner Bead)** 를 묻는 쪽이에요.","T-Bar 는 판을 틀 위에 얹어 두기만 해서 들어 올리기 쉬워요.","코너 비드는 모서리가 깨지지 않게 지키는 보호대예요."]}],"pass2":[{"kind":"points","head":"문제 3) T-Bar 시스템의 장점 3가지","items":["① 천장 마감재의 보수 및 유지 관리가 용이하다.","② 천장 내부 시설의 보수 및 점검이 용이하다.","③ 천장 설비의 시공 및 위치 선정이 용이하다.","**T-Bar** 는 격자 틀 날개 위에 패널을 얹는 탈착형이라 이런 장점이 생겨요.","나사로 박는 **M-Bar** 와 다른 점이에요."]},{"kind":"compare","head":"문제 4) 코너 비드 정의 두 가지","cols":["어디","정의"],"rows":[["5강 p48 (이 쪽)","기둥, 벽 등의 모서리에 대어 미장 바름을 보호하기 위한 철물"],["3강 p13","석고보드 벽체가 직각으로 꺾어지는 부분의 코너 파손을 막아주는 제품"]]},{"kind":"points","head":"그림에서 볼 것","items":["왼쪽 그림: 콘크리트 기둥 단면의 네 모서리에 **코너 비드(Corner Bead)** 를 대고 미장 마감해요.","오른쪽 사진: 그물 모양 날개가 달린 금속 모서리재예요.","위 그림은 **T-Bar** system. T자 틀 날개 위에 판을 얹은 모습이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"english","head":"답안에 쓸 문장: T-Bar 장점","en":"T-Bar 시스템은 천장 마감재의 보수 및 유지 관리, 천장 내부 시설의 보수 및 점검, 천장 설비의 시공 및 위치 선정이 용이하다.","ko":"마감재, 내부 시설, 설비. 세 가지 모두 '용이하다' 로 끝내요.","tip":"판을 들어 올릴 수 있다 → 고치기, 들여다보기, 설비 놓기가 쉽다."},{"kind":"english","head":"답안에 쓸 문장: 코너 비드","en":"코너 비드는 기둥, 벽 등의 모서리에 대어 미장 바름을 보호하기 위한 철물이다.","ko":"'모서리', '미장 바름 보호', '철물' 세 낱말이 핵심이에요.","tip":"코너(모서리) + 비드(띠). 모서리에 대는 띠 모양 철물."},{"kind":"check","q":"판을 틀 위에 얹어 두어 천장 내부 점검이 쉬운 천장틀은?","choices":["M-Bar","T-Bar","캐링 채널","마이너 채널"],"a":1,"why":"**T-Bar** 는 탈착형이라 판을 들어 올려 안을 볼 수 있어요. **M-Bar** 는 판을 나사로 박아요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**코너 비드(Corner Bead)** 정의가 3강(석고보드 코너 파손 방지)과 이 쪽(미장 바름 보호 철물)에서 달라요.","둘 다 알아 두고, 묻는 맥락에 맞춰 써요."]}],"walk":{"head":{"b":[0.002,0.0137,0.3452,0.1173],"c":[0,0,0.3797,0.1493],"r":4.5212,"img":"img/L5/walk/p048_h.jpg"},"parts":[{"b":[0.052,0.232,0.238,0.142],"c":[0.04,0.216,0.262,0.174],"r":2.6769,"img":"img/L5/walk/p048_23_01.jpg","say":"문제 3) 답. 마감재 보수, 내부 시설 점검, 설비 시공과 위치 선정이 쉬워요."},{"b":[0.336,0.133,0.134,0.292],"c":[0.303,0.117,0.2,0.324],"r":1.0974,"img":"img/L5/walk/p048_23_02.jpg","say":"T-bar system 그림. 판을 T자 날개 위에 얹어요."},{"b":[0.049,0.565,0.292,0.055],"c":[0.0344,0.5375,0.3212,0.11],"r":5.1911,"img":"img/L5/walk/p048_23_03.jpg","say":"문제 4) 답. 모서리에 대어 미장 바름을 보호하는 철물."},{"b":[0.049,0.669,0.184,0.226],"c":[0.037,0.653,0.208,0.258],"r":1.4332,"img":"img/L5/walk/p048_23_04.jpg","say":"코너비드의 설치위치. 콘크리트 기둥 모서리, 미장 마감."},{"b":[0.252,0.689,0.156,0.246],"c":[0.23,0.673,0.2,0.278],"r":1.279,"img":"img/L5/walk/p048_23_05.jpg","say":"코너 비드 실물 사진이에요."}]}},{"p":49,"title":"[문제풀이] 4. 목공사: 인공 건조법, 목공사 순서, 구조용 목재","terms":["목공사","인공 건조","훈연법","먹매김","마름질","바심질","구조재"],"pass1":[{"kind":"say","lines":["4. **목공사** 복습이에요.","나무를 말리고, 표시하고, 자르고, 뚫고, 세우는 이야기예요."]},{"kind":"analogy","head":"목공사 순서 = 요리 순서","scene":"재료를 말려 손질하고, 칼 댈 자리를 표시하고, 썰고, 구멍을 내고, 접시에 쌓아 올려요.","map":[["재료 말리기","건조처리"],["칼 댈 자리 표시","**먹매김**"],["썰기","**마름질**"],["구멍 내기","**바심질**"],["쌓아 올리기","세우기"]]}],"pass2":[{"kind":"points","head":"문제 1) 인공 건조법 3가지","items":["답: ① 증기법 ② 열기법 ③ 진공법","여기에 **훈연법** 을 더해 총 4개를 외워 두면 좋다고 슬라이드에 적혀 있어요.","**훈연법**: 연소 가마를 실내에 설치하고 나무 부스러기, 톱밥을 태운 연기와 열로 건조해요.","목재의 수액 제거 및 건조를 위한 방법이에요.","**인공 건조** 는 건조실의 온도, 습도, 풍속을 조절해 말리는 방법이에요."]},{"kind":"steps","head":"문제 2) 목공사의 순서","steps":["② 건조처리: 말리고","④ **먹매김**: 표시하고","① **마름질**: 자르고","③ **바심질**: 뚫어서","⑤ 세우기: 조립한다"],"answer":"② → ④ → ① → ③ → ⑤"},{"kind":"points","head":"문제 3) 구조용 목재의 조건","items":["답: ① 강도가 크고, 곧고 긴 부재 ② 수축과 팽창의 변형이 적은 부재 ③ 충해에 대한 저항성이 큰 부재","옆에 더 적힌 것: 강도가 크고 곧고 길 것, 변형이 적을 것, 동일한 품질일 것, 충해에 강할 것, 가공이 용이할 것","**구조재** 는 벽틀처럼 힘을 받는 뼈대에 쓰는 목재예요.","**먹매김** 은 2강에서 배운 말이에요. 도면 치수를 현장에 1:1로 옮겨 그려요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"기출 모양 연습문제","q":"다음 보기에서 목공사의 순서를 번호로 나열하시오. ① 마름질 ② 건조처리 ③ 바심질 ④ 먹매김 ⑤ 세우기","qko":"나무를 말려서 세울 때까지의 순서를 맞추는 문제예요.","solve":["먼저 말려요: ② 건조처리.","자를 선을 표시해요: ④ **먹매김**.","선대로 잘라요: ① **마름질**.","구멍을 뚫어 가공해요: ③ **바심질**. 마지막에 ⑤ 세우기."],"answer":"② → ④ → ① → ③ → ⑤"},{"kind":"english","head":"답안에 쓸 문장: 인공 건조법","en":"목재의 인공 건조법에는 증기법, 열기법, 진공법이 있으며, 훈연법을 더해 4가지로 쓸 수 있다.","ko":"**인공 건조** 3가지를 물으면 증기, 열기, 진공. 여유가 있으면 **훈연법** 까지.","tip":"증기, 열기, 진공, 연기. '기' 소리 셋에 연기 하나."},{"kind":"check","q":"먹매김 바로 다음에 오는 목공사 작업은?","choices":["건조처리","마름질","바심질","세우기"],"a":1,"why":"표시하고(**먹매김**) 다음은 자르고(**마름질**)예요. 뚫어서(**바심질**)는 그다음이에요."}],"walk":{"head":{"b":[0.002,0.0137,0.2652,0.1948],"c":[0,0,0.2917,0.2268],"r":2.2865,"img":"img/L5/walk/p049_h.jpg"},"parts":[{"b":[0.043,0.223,0.176,0.055],"c":[0.031,0.1955,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p049_23_01.jpg","say":"문제 1) 답. 증기법, 열기법, 진공법."},{"b":[0.043,0.292,0.683,0.076],"c":[0.0088,0.2541,0.7513,0.1518],"r":8.7987,"img":"img/L5/walk/p049_23_02.jpg","say":"훈연법을 더해 4개를 외우라는 문장과 훈연법의 뜻이에요."},{"b":[0.043,0.486,0.325,0.096],"c":[0.0267,0.47,0.3575,0.128],"r":4.9653,"img":"img/L5/walk/p049_23_03.jpg","say":"문제 2) 보기. 마름질, 건조처리, 바심질, 먹매김, 세우기."},{"b":[0.043,0.602,0.461,0.104],"c":[0.02,0.586,0.5071,0.136],"r":6.6288,"img":"img/L5/walk/p049_23_04.jpg","say":"문제 2) 답과 외우는 말. 말리고, 표시하고, 자르고, 뚫어서, 조립."},{"b":[0.043,0.802,0.618,0.143],"c":[0.0121,0.786,0.6798,0.175],"r":6.9059,"img":"img/L5/walk/p049_23_05.jpg","say":"문제 3) 구조용 목재의 조건 3가지와 덧붙인 조건들이에요."}]}},{"p":50,"title":"[문제풀이] 4. 목공사: 수장재 고르기, 강도 순서, 함수율","terms":["수장재","옹이","섬유방향","함수율","구조재"],"pass1":[{"kind":"say","lines":["목재를 고를 때 볼 점, 힘이 센 방향 순서, 알맞은 물기 정도를 묻는 쪽이에요."]},{"kind":"analogy","head":"나무는 빨대 다발이에요","scene":"빨대 다발을 길이 방향으로 당기면 잘 버티지만, 옆으로 벌리면 쉽게 갈라져요.","map":[["빨대 길이 방향","**섬유방향**"],["옆으로 벌리기","섬유직각방향 인장"],["빨대에 든 물","**함수율**"]]}],"pass2":[{"kind":"points","head":"문제 4) 수장재 선택 시 유의사항 4가지","items":["① 충분히 건조될 것 ② 외관의 무늬가 고른 것","③ 가공이 용이한 것 ④ **옹이** 등 흠이 없는 것","옆에 더 적힌 것: 외관이 미려할 것","**수장재** 는 실내 마감 목공사(수장 공사)에 쓰는 목재예요. 눈에 보이니 무늬와 흠이 중요해요."]},{"kind":"steps","head":"별표 문제 5) 목재의 강도가 큰 순서","steps":["1 나. **섬유방향** 인장강도 (가장 큼)","2 가. **섬유방향** 압축강도","3 다. 섬유직각방향 압축강도","4 라. 섬유직각방향 인장강도 (가장 작음)"],"answer":"나 > 가 > 다 > 라"},{"kind":"compare","head":"문제 6) 목재의 적정 함수율","cols":["목재","적정 함수율"],"rows":[["**수장재**","15%"],["**구조재**","20%"]]},{"kind":"points","head":"용어 풀이","items":["**함수율**: 목재가 물을 얼마나 머금고 있는지 나타낸 비율.","**옹이**: 나뭇가지가 붙어 있던 자리가 목재 속에 남은 흔적.","**섬유방향**: 나무 섬유가 길게 뻗은 방향. 결방향이라고도 해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"기출 모양 연습문제","q":"일반적으로 목재의 강도가 큰 순서부터 기호로 나열하시오. 가. 섬유방향 압축 나. 섬유방향 인장 다. 섬유직각방향 압축 라. 섬유직각방향 인장","qko":"슬라이드에 별표가 붙은 문제. 방향과 힘의 종류로 강도 순서를 매겨요.","solve":["**섬유방향** 이 섬유직각방향보다 세요. 그래서 나, 가 가 앞쪽.","**섬유방향** 에서는 인장(나)이 압축(가)보다 커요.","섬유직각방향에서는 압축(다)이 인장(라)보다 커요.","인장이 1등과 꼴찌, 양 끝에 와요."],"answer":"나 > 가 > 다 > 라"},{"kind":"check","q":"목재의 적정 함수율에서 수장재는 몇 %인가요?","choices":["10%","15%","20%","30%"],"a":1,"why":"**수장재** 15%, **구조재** 20% 예요."},{"kind":"english","head":"답안에 쓸 문장: 수장재 유의사항","en":"수장 공사용 부재는 충분히 건조될 것, 외관의 무늬가 고를 것, 가공이 용이할 것, 옹이 등 흠이 없을 것.","ko":"4가지를 물으면 건조, 무늬, 가공, 흠. 다섯째로 외관이 미려할 것.","tip":"'건무가흠' 네 글자로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**수장재** 15, **구조재** 20. 두 숫자를 바꿔 쓰지 않아요.","강도 순서는 '인장이 양 끝' 이에요. 섬유방향 인장이 최고, 섬유직각방향 인장이 최저."]}],"walk":{"head":{"b":[0.002,0.0137,0.4865,0.1837],"c":[0,0,0.5351,0.2157],"r":4.4102,"img":"img/L5/walk/p050_h.jpg"},"parts":[{"b":[0.043,0.206,0.134,0.185],"c":[0.01,0.19,0.2,0.217],"r":1.6385,"img":"img/L5/walk/p050_24_01.jpg","say":"문제 4) 답 네 가지. 건조, 무늬, 가공, 옹이."},{"b":[0.195,0.277,0.417,0.038],"c":[0.1741,0.241,0.4587,0.11],"r":7.4133,"img":"img/L5/walk/p050_24_02.jpg","say":"덧붙인 조건들. 외관이 미려할 것이 하나 더 있어요."},{"b":[0.043,0.466,0.139,0.228],"c":[0.0125,0.45,0.2,0.26],"r":1.3675,"img":"img/L5/walk/p050_24_03.jpg","say":"별표가 붙은 문제 5) 보기. 섬유방향과 섬유직각방향의 압축, 인장."},{"b":[0.199,0.466,0.104,0.055],"c":[0.151,0.4385,0.2,0.11],"r":3.2323,"img":"img/L5/walk/p050_24_04.jpg","say":"문제 5) 답. 나 > 가 > 다 > 라."},{"b":[0.043,0.802,0.305,0.129],"c":[0.0277,0.786,0.3355,0.161],"r":3.7046,"img":"img/L5/walk/p050_24_05.jpg","say":"문제 6) 적정 함수율. 수장재 15, 구조재 20."}]}},{"p":51,"title":"[문제풀이] 4. 목공사: MDF, 집성목재, 나뭇결, 수축률","terms":["Medium Density Fiber Board","Glue-Laminated Timber","곧은결","널결"],"pass1":[{"kind":"say","lines":["나무 섬유로 만든 판, 조각을 붙여 만든 목재, 나뭇결 무늬, 줄어드는 방향을 묻는 쪽이에요.","모두 목재의 생김새와 성질 이야기예요."]}],"pass2":[{"kind":"points","head":"문제 7) 용어 쓰기","items":["보기: 목질재료를 주원료로 하여 고온에서 얻은 목섬유를 합성수지 접착제로 결합시켜","성형열압하여 만든 밀도 0.4~0.8g/㎤ 의 목질 판상의 제품","답: M.D.F (중밀도섬유판), 즉 **MDF(Medium Density Fiber Board)**","5강 바탕도장에서도 MDF면이 나왔어요. 퍼티, 샌딩 뒤 프라이머나 서페이서를 써요."]},{"kind":"points","head":"문제 8) 집성목재의 장점 3가지","items":["① 접합을 통해 자유로운 형상을 만들 수 있다.","② 비교적 긴 스팬의 설계가 가능하다.","③ 일반 목재보다 1.5배 이상의 강도를 갖는다.","**집성목(Glue-Laminated Timber)** 은 각재를 섬유방향과 평행하게 접착해 모은 목재예요.","합판은 단판을 직교로, **집성목(Glue-Laminated Timber)** 은 평행으로 붙여요. 스팬은 받침 없이 건너가는 거리예요."]},{"kind":"compare","head":"문제 9) 제재목에서 나타나는 무늬 4가지","cols":["무늬","생김새 (4강 슬라이드)"],"rows":[["**곧은결**","나뭇결이 세로로 곧고 나란하게"],["**널결**","물결 모양 곡선"],["무늬결","여러 원인으로 소용돌이처럼 복잡한 무늬"],["엇결","섬유가 꼬여 결이 어긋나게"]]},{"kind":"steps","head":"문제 10) 수축률이 적은 것부터","steps":["1 ① 목재 길이 방향: 거의 안 줄어요","2 ③ 수직 방향","3 ② 둘레 방향: 가장 많이 줄어요"],"answer":"① < ③ < ②"},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"기출 모양 연습문제","q":"목재의 수축변형은 방향에 따라 다르다. 수축률이 적은 것부터 나열하시오. ① 목재 길이 방향 ② 둘레 방향 ③ 수직 방향","qko":"나무가 마를 때 어느 방향으로 덜, 더 줄어드는지 순서를 매겨요.","solve":["길이 방향은 거의 줄지 않아요. ① 이 맨 앞.","둘레 방향이 가장 많이 줄어요. ② 가 맨 끝.","수직 방향은 그 사이. ③ 이 가운데."],"answer":"① < ③ < ②"},{"kind":"check","q":"MDF(중밀도섬유판)의 밀도 범위로 슬라이드에 적힌 것은?","choices":["0.1~0.3g/㎤","0.4~0.8g/㎤","0.9~1.2g/㎤","1.5~2.0g/㎤"],"a":1,"why":"**MDF(Medium Density Fiber Board)** 는 밀도 0.4~0.8g/㎤ 의 목질 판상 제품이에요."},{"kind":"english","head":"답안에 쓸 문장: 집성목재 장점","en":"집성목재는 접합을 통해 자유로운 형상을 만들 수 있고, 비교적 긴 스팬의 설계가 가능하며, 일반 목재보다 1.5배 이상의 강도를 갖는다.","ko":"**집성목(Glue-Laminated Timber)** 의 장점은 형상, 스팬, 강도 1.5배. 세 가지예요.","tip":"모양 자유, 길게, 세게. 숫자는 1.5배 하나만."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["수축은 길이 < 수직 < 둘레. 4강 표현으로는 줄기(길이) < 반지름(수직) < 나이테 접선(둘레) 방향이에요.","무늬 4가지는 **곧은결**, **널결**, 무늬결, 엇결. '결' 자로 끝나는 넷이에요."]}],"walk":{"head":{"b":[0.002,0.0137,0.2052,0.1701],"c":[0,0,0.2292,0.2021],"r":2.0162,"img":"img/L5/walk/p051_h.jpg"},"parts":[{"b":[0.043,0.198,0.666,0.161],"c":[0.0097,0.182,0.7326,0.193],"r":6.7482,"img":"img/L5/walk/p051_24_01.jpg","say":"문제 7) 보기와 답 M.D.F (중밀도섬유판)."},{"b":[0.043,0.456,0.234,0.141],"c":[0.031,0.44,0.258,0.173],"r":2.6513,"img":"img/L5/walk/p051_24_02.jpg","say":"문제 8) 집성목재의 장점 3가지."},{"b":[0.043,0.688,0.241,0.055],"c":[0.0309,0.6605,0.2651,0.11],"r":4.2844,"img":"img/L5/walk/p051_24_03.jpg","say":"문제 9) 답. 곧은결, 널결, 무늬결, 엇결."},{"b":[0.043,0.831,0.259,0.118],"c":[0.03,0.815,0.2849,0.15],"r":3.3766,"img":"img/L5/walk/p051_24_04.jpg","say":"문제 10) 보기와 답. ① < ③ < ②."}]}},{"p":52,"title":"[문제풀이] 5. 도장공사: 도장 순서, 수성도료 장점, 바탕 고르기","terms":["고름질","putty","초벌칠","중벌칠","정벌칠","왁스먹임","water-based paint","red lead","내알칼리 페인트","도장공사"],"pass1":[{"kind":"say","lines":["5. **도장공사**, 이번 강의 내용의 복습이에요.","칠하는 순서, 수성 도료의 좋은 점, 바탕에 맞는 도료 고르기를 물어요."]},{"kind":"analogy","head":"일반 도장 순서도 화장 순서예요","scene":"피부를 고르고, 매끈하게 다듬고, 베이스, 색조, 마무리를 올린 뒤 광을 내요.","map":[["피부 고르기","**고름질** 및 **퍼티(putty)**"],["매끈하게 다듬기","물갈기 또는 연마"],["베이스","**초벌칠**"],["색조","**중벌칠**"],["마무리","**정벌칠**"],["광 내기","**왁스먹임**"]]}],"pass2":[{"kind":"steps","head":"문제 1) 일반적인 도장 공사의 순서","steps":["② **고름질** 및 **퍼티(putty)**","④ 물갈기 또는 연마작업","③ **초벌칠**","⑤ **중벌칠**","⑥ **정벌칠**","① **왁스먹임**"],"answer":"② → ④ → ③ → ⑤ → ⑥ → ①"},{"kind":"points","head":"문제 2) 수성 페인트의 장점 4가지","items":["① 물을 용제로 사용하므로 공해가 적다.","② 건조가 빠르다.","③ 가격이 저렴하고, 도포방법이 간단하다.","④ 알칼리성에도 도포가 가능하다.","**수성 페인트(water-based paint)** 는 물을 주된 희석제로 쓰는 도료예요."]},{"kind":"compare","head":"문제 3) 알맞은 번호 고르기","cols":["문장","답"],"rows":[["가. 철재에 도장할 때 바탕에 도포하는 것","① **광명단(red lead)**"],["나. 합성수지 에멀전 페인트의 건조","② 빠르다"],["다. 알루미늄 페인트의 광선 및 열 반사력","① 강하다"],["라. 에나멜 페인트(주로 금속면)의 광택","① 잘난다"]]},{"kind":"points","head":"내알칼리 페인트란","items":["**내알칼리 페인트**: 알칼리(염기성)에 잘 견디는 성질을 지닌 페인트.","콘크리트, 시멘트, 모르타르처럼 알칼리 성분이 많은 표면에 칠해도 변색, 박리, 백화 현상이 없게 만든 내화학성 페인트.","그래서 철재 바탕에는 **내알칼리 페인트** 가 아니라 녹을 막는 **광명단(red lead)** 이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"기출 모양 연습문제","q":"일반적인 도장 공사의 순서를 보기에서 골라 쓰시오. ① 왁스먹임 ② 고름질 및 퍼티 ③ 초벌칠 ④ 물갈기 또는 연마작업 ⑤ 중벌칠 ⑥ 정벌칠","qko":"바탕 다듬기부터 마지막 광내기까지 순서를 맞추는 문제예요.","solve":["바탕부터: ② **고름질** 및 퍼티, 그다음 ④ 물갈기 또는 연마.","칠은 아래층부터: ③ **초벌칠** → ⑤ **중벌칠** → ⑥ **정벌칠**.","맨 끝 광내기: ① **왁스먹임**."],"answer":"② → ④ → ③ → ⑤ → ⑥ → ①"},{"kind":"check","q":"철재에 도장할 때 바탕에 도포하는 것은?","choices":["광명단","내알칼리 페인트","오일스테인","신너"],"a":0,"why":"철재는 녹을 막아야 해서 **광명단(red lead)** 이에요. **내알칼리 페인트** 는 콘크리트, 시멘트, 모르타르 바탕용이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드 '가격이 저렵하고' 는 '저렴' 의 오타, '건조가 빠르다..' 는 마침표가 두 개예요.","'함성수지 에멀전 페인트' 는 '합성수지' 의 오타예요.","p4 는 '에멀션', p52 는 '에멀전' 으로 표기가 섞여 있어요. 같은 말이에요.","**광명단(red lead)** 은 철재, **내알칼리 페인트** 는 알칼리성 바탕. 바탕으로 짝을 지어요."]}],"walk":{"head":{"b":[0.002,0.0137,0.3529,0.1453],"c":[0,0,0.3882,0.1773],"r":3.8925,"img":"img/L5/walk/p052_h.jpg"},"parts":[{"b":[0.043,0.161,0.479,0.173],"c":[0.0191,0.145,0.5269,0.205],"r":4.5693,"img":"img/L5/walk/p052_24_01.jpg","say":"문제 1) 보기와 답. ② → ④ → ③ → ⑤ → ⑥ → ①."},{"b":[0.043,0.425,0.214,0.185],"c":[0.031,0.409,0.238,0.217],"r":1.9498,"img":"img/L5/walk/p052_24_02.jpg","say":"문제 2) 수성도료의 장점 4가지."},{"b":[0.043,0.706,0.403,0.25],"c":[0.0228,0.69,0.4433,0.282],"r":2.7946,"img":"img/L5/walk/p052_24_03.jpg","say":"문제 3) 네 문장과 답. 가 ①, 나 ②, 다 ①, 라 ①."},{"b":[0.484,0.742,0.339,0.123],"c":[0.467,0.726,0.3729,0.155],"r":4.277,"img":"img/L5/walk/p052_24_04.jpg","say":"내알칼리 페인트의 뜻. 콘크리트, 시멘트, 모르타르 바탕용이에요."}]}},{"p":53,"title":"[문제풀이] 5. 도장공사: 재료 짝, 바니쉬칠 순서, 공사 중지 조건","terms":["방청제","방부제","착색제","희석제","red lead","크레오소트","오일스테인","신너","varnish","눈먹임","초벌칠","정벌칠"],"pass1":[{"kind":"say","lines":["도장 재료 짝 맞추기, 바니쉬칠 순서, 칠하면 안 되는 날씨를 묻는 마지막 쪽이에요."]},{"kind":"compare","head":"재료 이름 뜻 풀기","cols":["이름","쉬운 뜻"],"rows":[["**방청제**","녹(청) 막기"],["**방부제**","썩음(부) 막기"],["**착색제**","색 입히기"],["**희석제**","묽게 하기"]]}],"pass2":[{"kind":"compare","head":"문제 4) 맞는 것끼리 연결","cols":["보기","짝","뜻"],"rows":[["① **방청제**","(나) **광명단(red lead)**","금속의 녹을 막는 재료"],["② **방부제**","(다) **크레오소트**","목재가 썩는 것을 막는 재료"],["③ **착색제**","(라) **오일스테인**","색을 입히는 재료"],["④ **희석제**","(가) **신너**","도료를 묽게 하는 재료"]]},{"kind":"steps","head":"문제 5) 목재 바니쉬칠 공정 순서","steps":["⑥ 바탕손질","② **눈먹임**: 나뭇결의 작은 구멍 메우기","① 착색","③ **초벌칠**","⑤ **정벌칠**","④ 닦기, 마무리"],"answer":"⑥ → ② → ① → ③ → ⑤ → ④"},{"kind":"points","head":"바니쉬 도장의 일반적인 순서 (슬라이드 아래 글)","items":["샌딩(사포질, 바탕정리) → **눈먹임**(구멍 메우기)","→ 2차 샌딩(눈 먹임 후 다시 평활화) → 초벌 착색","→ 연마지 닦기 → **정벌칠** → 왁스칠","**바니쉬(varnish)** 는 목재 무늬를 살리며 표면을 보호하는 투명 도료예요."]},{"kind":"compare","head":"문제 6) 기후에 따른 공사 중지 조건","cols":["조건","기준"],"rows":[["온도","5℃ 이하"],["온도","35℃ 이상"],["습도","85% 이상"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"기출 모양 연습문제","q":"도장공사에서 기후에 따른 공사 중지 조건 3가지를 쓰시오.","qko":"너무 춥거나, 너무 덥거나, 너무 습하면 칠을 멈춰요.","solve":["너무 추울 때: 온도 5℃ 이하.","너무 더울 때: 온도 35℃ 이상.","너무 습할 때: 습도 85% 이상."],"answer":"① 온도 5℃ 이하 ② 온도 35℃ 이상 ③ 습도 85% 이상"},{"kind":"check","q":"방부제와 짝이 맞는 것은?","choices":["신너","광명단","크레오소트","오일스테인"],"a":2,"why":"**방부제** 는 **크레오소트**. **방청제** 는 광명단, **착색제** 는 **오일스테인**, **희석제** 는 **신너** 예요."},{"kind":"english","head":"답안에 쓸 문장: 공사 중지 조건","en":"도장공사는 기온이 5℃ 이하이거나 35℃ 이상일 때, 습도가 85% 이상일 때 공사를 중지한다.","ko":"숫자 세 개: 5, 35, 85.","tip":"5 와 35 는 온도, 85 는 습도. 끝자리가 모두 5 예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["바니쉬칠 답(6단계, 착색이 **초벌칠** 앞)과 아래 '일반적인 순서'(7단계)는 단계 수와 이름이 달라요. 시험 답은 보기 번호 순서로 써요.","습도 기준이 쪽마다 달라요. p20 '85% 초과', p33 과 이 쪽은 '85% 이상'.","35℃ 이상 기준은 이 쪽에만 있어요.","**방청제** 의 '청' 은 녹, **방부제** 의 '부' 는 썩음이에요."]}],"walk":{"head":{"b":[0.002,0.0137,0.2678,0.1546],"c":[0,0,0.2946,0.1866],"r":2.8067,"img":"img/L5/walk/p053_h.jpg"},"parts":[{"b":[0.043,0.178,0.554,0.148],"c":[0.0153,0.162,0.6094,0.18],"r":6.0188,"img":"img/L5/walk/p053_24_01.jpg","say":"문제 4) 보기와 답. 방청제-광명단, 방부제-크레오소트, 착색제-오일스테인, 희석제-신너."},{"b":[0.043,0.435,0.408,0.175],"c":[0.0226,0.419,0.4488,0.207],"r":3.8544,"img":"img/L5/walk/p053_24_02.jpg","say":"문제 5) 보기와 답. ⑥ → ② → ① → ③ → ⑤ → ④."},{"b":[0.046,0.626,0.615,0.076],"c":[0.0152,0.5957,0.6765,0.1367],"r":8.7979,"img":"img/L5/walk/p053_24_03.jpg","say":"바니쉬 도장의 일반적인 순서. 답과 단계 이름이 조금 달라요."},{"b":[0.043,0.793,0.106,0.141],"c":[0,0.777,0.2,0.173],"r":2.0552,"img":"img/L5/walk/p053_24_04.jpg","say":"문제 6) 공사 중지 조건. 5℃ 이하, 35℃ 이상, 85% 이상."}]}}]};
